// ── End of Day Settlement ─────────────────────────────────────────────────
const _eod = { open: false };

function _eodOpen() {
  $('#eod-overlay').style.display = 'flex';
  _eod.open = true;
  _eodLoad();
}

function _eodClose() {
  $('#eod-overlay').style.display = 'none';
  _eod.open = false;
}

async function _eodLoad() {
  const body   = $('#eod-body');
  const footer = $('#eod-footer');
  footer.style.display = 'none';
  body.innerHTML = '<div class="eod-loading"><i class="fa fa-spinner fa-spin"></i> Loading…</div>';

  const dontSettle = !!state.receiptSettings?.dont_settle_to_account;

  const [eodRes, sumRes, drawerRes] = await Promise.all([
    API.eodStatus(),
    API.todaySummary(),
    dontSettle ? API.cashDrawer() : Promise.resolve(null),
  ]);

  if (eodRes.status !== 200) {
    body.innerHTML = '<div class="eod-loading"><i class="fa fa-circle-exclamation" style="color:#ef4444"></i> Failed to load EOD status.</div>';
    return;
  }

  const d         = eodRes.body;
  const currency  = d.currency ? ' ' + d.currency : '';
  const fmt       = v => (v ?? 0).toFixed(2) + currency;
  const eodSum    = d.summary   || {};
  const unsettled = d.unsettled || [];
  const history   = d.history   || [];
  const byMethod  = eodSum.by_method || {};

  const salesData = sumRes.status === 200 ? (sumRes.body?.data || {}) : {};
  const sales     = salesData.sales || {};
  const salesByMethod = salesData.sales_by_method || {};
  const dr        = drawerRes?.status === 200 ? (drawerRes.body?.data || null) : null;
  const today     = new Date().toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  let html = '';

  // ── Date heading ─────────────────────────────────────────────────────────
  html += `<div class="eod-date-heading">${today}</div>`;

  // ── Today's full summary ──────────────────────────────────────────────────
  html += `<p class="eod-section-lbl"><i class="fa fa-chart-bar"></i> Today's Sales Summary</p>`;
  html += `<div class="eod-summary-bar eod-summary-bar--6">
    <div class="eod-stat">
      <p class="eod-stat__label">Sales</p>
      <p class="eod-stat__value">${sales.count ?? 0}</p>
    </div>
    <div class="eod-stat eod-stat--blue">
      <p class="eod-stat__label">Total Revenue</p>
      <p class="eod-stat__value">${fmt(sales.revenue)}</p>
    </div>
    <div class="eod-stat eod-stat--green">
      <p class="eod-stat__label">Gross Profit</p>
      <p class="eod-stat__value">${fmt(sales.gross_profit)}</p>
    </div>
    <div class="eod-stat">
      <p class="eod-stat__label">Cash</p>
      <p class="eod-stat__value">${fmt(salesByMethod.cash?.total)}</p>
      <p class="eod-stat__sub">${salesByMethod.cash?.count ?? 0} sales</p>
    </div>
    <div class="eod-stat">
      <p class="eod-stat__label">Card</p>
      <p class="eod-stat__value">${fmt(salesByMethod.card?.total)}</p>
      <p class="eod-stat__sub">${salesByMethod.card?.count ?? 0} sales</p>
    </div>
    <div class="eod-stat">
      <p class="eod-stat__label">Credit</p>
      <p class="eod-stat__value">${fmt(salesByMethod.credit?.total)}</p>
      <p class="eod-stat__sub">${salesByMethod.credit?.count ?? 0} sales</p>
    </div>
  </div>`;

  // ── Payment method tabs ───────────────────────────────────────────────────
  {
    const fmtDue = d => d ? new Date(d + 'T00:00:00').toLocaleDateString(undefined, { month:'short', day:'numeric', year:'numeric' }) : '—';

    const tabDef = [
      { key: 'cash',   label: 'Cash',   icon: 'fa-money-bill-wave',      badge: 'eod-badge-cash'   },
      { key: 'card',   label: 'Card',   icon: 'fa-credit-card',           badge: 'eod-badge-card'   },
      { key: 'credit', label: 'Credit', icon: 'fa-file-invoice-dollar',   badge: 'eod-badge-credit' },
    ];

    html += `<p class="eod-section-lbl"><i class="fa fa-layer-group"></i> Sales by Payment Method</p>`;
    html += `<div class="eod-pay-tabs">`;
    tabDef.forEach((t, i) => {
      const m   = salesByMethod[t.key] || { count: 0, total: 0 };
      html += `<div class="eod-pay-tab${i === 0 ? ' active' : ''}" data-eod-tab="${t.key}">
        <i class="fa ${t.icon} eod-pay-tab-icon"></i>
        <span class="eod-pay-tab-label">${t.label}</span>
        <span class="eod-pay-tab-meta">${m.count} sale${m.count !== 1 ? 's' : ''} · ${fmt(m.total)}</span>
      </div>`;
    });
    html += `</div>`;

    tabDef.forEach((t, i) => {
      const m    = salesByMethod[t.key] || { count: 0, total: 0, sales: [] };
      const list = m.sales || [];
      const isCredit = t.key === 'credit';
      html += `<div class="eod-pay-panel${i === 0 ? ' active' : ''}" data-eod-panel="${t.key}">`;
      if (!list.length) {
        html += `<div class="eod-pay-empty"><i class="fa fa-inbox"></i> No ${t.label.toLowerCase()} sales today</div>`;
      } else {
        html += `<div class="eod-tbl-wrap"><table class="eod-tbl"><thead><tr>
          <th>Sale #</th><th>Time</th><th>Customer</th>
          ${isCredit ? '<th>Due Date</th>' : ''}
          <th style="text-align:right">Total</th>
        </tr></thead><tbody>`;
        list.forEach(s => {
          const t2 = s.sold_at ? new Date(s.sold_at).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }) : '—';
          html += `<tr>
            <td style="font-weight:700">${escHtml(s.sale_number || String(s.id))}</td>
            <td style="color:var(--text-muted)">${t2}</td>
            <td style="color:var(--text-muted)">${escHtml(s.customer_name || '—')}</td>
            ${isCredit ? `<td style="color:var(--text-muted)">${fmtDue(s.credit_due_date)}</td>` : ''}
            <td style="text-align:right;font-weight:700">${s.total.toFixed(2)}${currency}</td>
          </tr>`;
        });
        html += `</tbody><tfoot><tr>
          <td colspan="${isCredit ? 4 : 3}" style="text-align:right;font-size:11px;font-weight:700;color:var(--text-muted);padding:8px 10px">Total</td>
          <td style="text-align:right;font-size:14px;font-weight:800;padding:8px 10px">${fmt(m.total)}</td>
        </tr></tfoot></table></div>`;
      }
      html += `</div>`;
    });
  }

  // ── Cash drawer ───────────────────────────────────────────────────────────
  if (dontSettle && dr) {
    html += `<p class="eod-section-lbl" style="margin-top:4px"><i class="fa fa-cash-register"></i> Cash Drawer</p>`;
    html += `<div class="eod-summary-bar eod-summary-bar--4">
      <div class="eod-stat">
        <p class="eod-stat__label">Opening Float</p>
        <p class="eod-stat__value">${dr.opening_float !== null ? fmt(dr.opening_float) : '—'}</p>
      </div>
      <div class="eod-stat">
        <p class="eod-stat__label">Cash Sales</p>
        <p class="eod-stat__value">${fmt(dr.cash_sales)}</p>
      </div>
      <div class="eod-stat eod-stat--warn">
        <p class="eod-stat__label">Withdrawals</p>
        <p class="eod-stat__value">${fmt(dr.total_withdrawals)}</p>
      </div>
      <div class="eod-stat eod-stat--highlight">
        <p class="eod-stat__label">Cash Balance</p>
        <p class="eod-stat__value">${dr.balance !== null ? fmt(dr.balance) : '—'}</p>
      </div>
    </div>`;

    if (dr.withdrawals?.length) {
      html += `<div class="eod-tbl-wrap"><table class="eod-tbl">
        <thead><tr><th>Time</th><th>Note</th><th style="text-align:right">Withdrawn</th></tr></thead>
        <tbody>
        ${dr.withdrawals.map(w => {
          const t = w.time ? new Date(w.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—';
          return `<tr>
            <td style="color:var(--text-muted)">${t}</td>
            <td>${escHtml(w.note || '—')}</td>
            <td style="text-align:right;font-weight:700">${w.amount.toFixed(2)}${currency}</td>
          </tr>`;
        }).join('')}
        </tbody>
      </table></div>`;
    }

    html += `<div style="text-align:right;margin-bottom:18px">
      <button class="psm-btn-cancel" id="eod-withdraw-btn" style="font-size:12px;padding:6px 14px">
        <i class="fa fa-arrow-up-from-bracket"></i> Withdraw Cash
      </button>
    </div>`;
  }

  // ── Settlement section ────────────────────────────────────────────────────
  if (!dontSettle) {
    if (unsettled.length === 0) {
      html += `<div class="eod-all-ok"><i class="fa fa-circle-check"></i> All sales settled — nothing pending for today.</div>`;
    } else {
      html += `<p class="eod-section-lbl"><i class="fa fa-clock"></i> Pending settlement (${unsettled.length})</p>`;
      html += `<div class="eod-summary-bar" style="margin-bottom:12px">
        <div class="eod-stat eod-stat--highlight">
          <p class="eod-stat__label">Unsettled Sales</p>
          <p class="eod-stat__value">${eodSum.total_count ?? 0}</p>
        </div>
        <div class="eod-stat eod-stat--highlight">
          <p class="eod-stat__label">Cash Pending</p>
          <p class="eod-stat__value">${fmt(byMethod.cash?.total)}</p>
        </div>
        <div class="eod-stat eod-stat--highlight">
          <p class="eod-stat__label">Card Pending</p>
          <p class="eod-stat__value">${fmt(byMethod.card?.total)}</p>
        </div>
      </div>`;
      html += `<div class="eod-tbl-wrap"><table class="eod-tbl">
        <thead><tr>
          <th>Sale #</th><th>Time</th><th>Payment</th><th>Account</th><th style="text-align:right">Total</th>
        </tr></thead>
        <tbody>
        ${unsettled.map(s => {
          const t = s.sold_at ? new Date(s.sold_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—';
          const badge = s.payment_method === 'card' ? 'eod-badge-card' : 'eod-badge-cash';
          const label = s.payment_method === 'card' ? 'Card' : 'Cash';
          return `<tr>
            <td style="font-weight:700">${escHtml(s.sale_number || String(s.id))}</td>
            <td style="color:var(--text-muted)">${t}</td>
            <td><span class="${badge}">${label}</span></td>
            <td style="color:var(--text-muted);font-size:11px">${escHtml(s.account_label || '—')}</td>
            <td style="text-align:right;font-weight:700">${s.total.toFixed(2)}${currency}</td>
          </tr>`;
        }).join('')}
        </tbody>
        <tfoot><tr>
          <td colspan="4" style="text-align:right;font-size:11px;font-weight:700;color:var(--text-muted);padding:8px 10px">Total</td>
          <td style="text-align:right;font-size:15px;font-weight:800;padding:8px 10px">${fmt(eodSum.total_amount)}</td>
        </tr></tfoot>
      </table></div>`;

      footer.style.display = '';
      $('#eod-footer-info').textContent = `${eodSum.total_count} sale${eodSum.total_count !== 1 ? 's' : ''} · ${fmt(eodSum.total_amount)} unsettled`;
      const btn = $('#eod-settle-btn');
      btn.disabled = false;
      btn.innerHTML = '<i class="fa fa-check-circle"></i> Settle All to Bank';
    }
  }

  // ── Settlement history ────────────────────────────────────────────────────
  if (history.length) {
    html += `<p class="eod-section-lbl" style="margin-top:4px"><i class="fa fa-clock-rotate-left"></i> Recent settlements</p>`;
    html += `<div class="eod-tbl-wrap"><div>`;
    html += history.map(r => {
      const dt = new Date(r.date + 'T00:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
      return `<div class="eod-history-row">
        <span class="eod-history-date">${dt}</span>
        <span class="eod-history-count">${r.sale_count} sale${r.sale_count !== 1 ? 's' : ''}</span>
        <span class="eod-history-total">${r.total.toFixed(2)}${currency}</span>
      </div>`;
    }).join('');
    html += `</div></div>`;
  }

  body.innerHTML = html;

  // Wire payment method tab clicks
  body.querySelectorAll('[data-eod-tab]').forEach(tab => {
    tab.addEventListener('click', () => {
      const key = tab.dataset.eodTab;
      body.querySelectorAll('[data-eod-tab]').forEach(t => t.classList.toggle('active', t.dataset.eodTab === key));
      body.querySelectorAll('[data-eod-panel]').forEach(p => p.classList.toggle('active', p.dataset.eodPanel === key));
    });
  });

  const wBtn = body.querySelector('#eod-withdraw-btn');
  if (wBtn) wBtn.addEventListener('click', () => _openCashWithdrawModal(dr?.balance ?? null));
}

$('#eod-settle-btn').addEventListener('click', async () => {
  const btn = $('#eod-settle-btn');
  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Settling…';

  const res = await API.eodSettle();
  if (res.status === 200) {
    toast(res.body?.message || 'Settlement complete.', 'success');
    // reload EOD status in panel
    $('#eod-footer').style.display = 'none';
    _eodLoad();
    // also refresh sales list if open
    if (_sal.view === 'transactions') { _sal.all = []; loadSalesList(); }
  } else {
    toast(res.body?.message || 'Settlement failed.', 'error');
    btn.disabled = false;
    btn.innerHTML = '<i class="fa fa-check-circle"></i> Settle All to Bank';
  }
});

$('#eod-close-btn').addEventListener('click', _eodClose);
$('#eod-overlay').addEventListener('click', e => { if (e.target === $('#eod-overlay')) _eodClose(); });
$('#rb-eod-open')?.addEventListener('click', _eodOpen);
// ── End of Day Settlement ─────────────────────────────────────────────────

// ── Cash Drawer ───────────────────────────────────────────────────────────
async function _checkCashDrawerOpening() {
  const s = state.receiptSettings || {};
  if (!s.dont_settle_to_account) return;

  const today = new Date().toISOString().slice(0, 10);
  if (state._cashDrawerOpenedDate === today) return;

  const res = await API.cashDrawer();
  if (res.status !== 200) return;

  const d = res.body?.data || {};
  if (d.is_opened) {
    state._cashDrawerOpenedDate = today;
    return;
  }

  // Show opening modal
  $('#cash-opening-amount').value = '';
  $('#cash-opening-overlay').style.display = 'flex';
  setTimeout(() => $('#cash-opening-amount').focus(), 80);
}

$('#cash-opening-confirm').addEventListener('click', async () => {
  const amount = parseFloat($('#cash-opening-amount').value) || 0;
  const btn = $('#cash-opening-confirm');
  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>';

  const res = await API.cashDrawerOpen(amount);
  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-check"></i> Confirm';

  if (res.status === 200) {
    state._cashDrawerOpenedDate = new Date().toISOString().slice(0, 10);
    $('#cash-opening-overlay').style.display = 'none';
    toast(`Opening cash: ${amount.toFixed(2)} recorded.`, 'success');
  } else {
    toast(res.body?.message || 'Failed to record opening cash.', 'error');
  }
});

$('#cash-opening-skip').addEventListener('click', () => {
  state._cashDrawerOpenedDate = new Date().toISOString().slice(0, 10);
  $('#cash-opening-overlay').style.display = 'none';
});

$('#cash-withdraw-close').addEventListener('click',  () => { $('#cash-withdraw-overlay').style.display = 'none'; });
$('#cash-withdraw-cancel').addEventListener('click', () => { $('#cash-withdraw-overlay').style.display = 'none'; });
$('#cash-withdraw-fill-max').addEventListener('click', () => {
  const max = parseFloat($('#cash-withdraw-amount').max);
  if (max > 0) { $('#cash-withdraw-amount').value = max.toFixed(2); }
});

function _openCashWithdrawModal(balance = null) {
  const cur = state.currency ? ' ' + state.currency : '';
  const amtInput = $('#cash-withdraw-amount');
  amtInput.value = '';
  amtInput.placeholder = balance !== null ? `Max: ${balance.toFixed(2)}${cur}` : '0.00';
  amtInput.max = balance !== null ? balance : '';

  const balEl = $('#cash-withdraw-balance-hint');
  if (balEl) {
    balEl.textContent = balance !== null ? `Available balance: ${balance.toFixed(2)}${cur}` : '';
    balEl.style.display = balance !== null ? 'block' : 'none';
  }

  $('#cash-withdraw-note').value = '';
  $('#cash-withdraw-overlay').style.display = 'flex';
  setTimeout(() => amtInput.focus(), 80);
}

$('#cash-withdraw-confirm').addEventListener('click', async () => {
  const amount = parseFloat($('#cash-withdraw-amount').value);
  if (!amount || amount <= 0) { toast('Enter a valid amount.', 'error'); return; }
  const note = $('#cash-withdraw-note').value.trim() || null;

  const btn = $('#cash-withdraw-confirm');
  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>';

  const res = await API.cashDrawerWithdraw(amount, note);
  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-arrow-up-from-bracket"></i> Withdraw';

  if (res.status === 200) {
    const newBalance = res.body?.data?.balance ?? null;
    $('#cash-withdraw-overlay').style.display = 'none';
    const cur = state.currency ? ' ' + state.currency : '';
    const balMsg = newBalance !== null ? ` — balance: ${newBalance.toFixed(2)}${cur}` : '';
    toast(`Withdrawal of ${amount.toFixed(2)}${cur} recorded${balMsg}.`, 'success');
    if (_eod.open) _eodLoad();
    _loadPosRibbonStats();
  } else {
    toast(res.body?.message || 'Failed to record withdrawal.', 'error');
  }
});
async function _loadPosRibbonStats() {
  const el = $('#pos-ribbon-stats');
  if (!el) return;
  el.innerHTML = '<div class="prs-spin"><i class="fa fa-spinner fa-spin"></i></div>';

  const cur = state.currency ? ' ' + state.currency : '';
  const fmt = v => (v ?? 0).toFixed(2) + cur;

  const [sumRes, drawerRes] = await Promise.all([
    API.todaySummary(),
    state.receiptSettings?.dont_settle_to_account ? API.cashDrawer() : Promise.resolve(null),
  ]);

  if (sumRes.status !== 200) {
    el.innerHTML = '<div class="prs-spin" style="color:#ef4444"><i class="fa fa-triangle-exclamation"></i></div>';
    return;
  }

  const sales  = sumRes.body?.data?.sales || {};
  const profit = sales.gross_profit ?? 0;
  const drawer = drawerRes?.body?.data || null;

  let cashStat = '';
  if (drawer) {
    const bal = drawer.balance;
    cashStat = `<div class="prs-stat">
      <span class="prs-lbl"><i class="fa fa-cash-register"></i> Cash Balance</span>
      <span class="prs-val prs-cash">${bal !== null ? fmt(bal) : '—'}</span>
    </div>`;
  } else {
    const cashTotal = sales.by_method?.cash?.total ?? 0;
    cashStat = `<div class="prs-stat">
      <span class="prs-lbl"><i class="fa fa-money-bill-wave"></i> Cash Sales</span>
      <span class="prs-val prs-cash">${fmt(cashTotal)}</span>
    </div>`;
  }

  el.innerHTML = `<div class="prs-grid">
    <div class="prs-stat">
      <span class="prs-lbl"><i class="fa fa-cart-shopping"></i> Sales Today</span>
      <span class="prs-val">${sales.count ?? 0}</span>
      <span class="prs-sub">${fmt(sales.revenue)}</span>
    </div>
    <div class="prs-stat">
      <span class="prs-lbl"><i class="fa fa-chart-line"></i> Gross Profit</span>
      <span class="prs-val prs-profit">${fmt(profit)}</span>
    </div>
    ${cashStat}
    <div class="prs-stat">
      <span class="prs-lbl"><i class="fa fa-box-open"></i> Items Sold</span>
      <span class="prs-val">${sales.items_sold ?? 0}</span>
    </div>
  </div>`;
}
// ── End Cash Drawer ───────────────────────────────────────────────────────

// ── End Sales Panel ────────────────────────────────────────────────────────

// ── Quotations Panel ──────────────────────────────────────────────────────
const _qt = {
  list:        [],
  status:      'all',
  search:      '',
  activeId:    null,
  editingId:   null,   // null = new, number = edit
  customers:   [],
  lineSeq:     0,
};
let _qtSearchTimer = null;

// ── List ──────────────────────────────────────────────────────────────────
async function loadQuotesList() {
  _qtShowView('list');
  $('#qt-list-loading').style.display = '';
  $('#qt-list-body').innerHTML = '';

  const res = await API.quotations(_qt.search, _qt.status);
  $('#qt-list-loading').style.display = 'none';

  if (res.status !== 200) {
    $('#qt-list-body').innerHTML = '<div class="qt-empty"><i class="fa fa-circle-exclamation"></i> Failed to load quotations.</div>';
    return;
  }

  _qt.list = res.body?.data || [];
  _qtRenderList();
}

function _qtRenderList() {
  const cur = state.currency ? ' ' + state.currency : '';
  if (!_qt.list.length) {
    $('#qt-list-body').innerHTML = `<div class="qt-empty">
      <i class="fa fa-file-circle-question"></i>
      <h4>No Quotations Found</h4>
      <p>Create your first quotation to get started.</p>
    </div>`;
    return;
  }

  // Compute stats
  const counts = { draft: 0, sent: 0, accepted: 0, rejected: 0 };
  let totalVal = 0;
  _qt.list.forEach(q => { if (counts[q.status] !== undefined) counts[q.status]++; totalVal += parseFloat(q.total || 0); });

  let html = `<div class="qt-stats">
    <div class="qt-stat"><span class="qt-stat-val">${_qt.list.length}</span><span class="qt-stat-lbl">Total</span></div>
    <div class="qt-stat blue"><span class="qt-stat-val">${counts.sent}</span><span class="qt-stat-lbl">Sent</span></div>
    <div class="qt-stat green"><span class="qt-stat-val">${counts.accepted}</span><span class="qt-stat-lbl">Accepted</span></div>
    <div class="qt-stat"><span class="qt-stat-val">${counts.draft}</span><span class="qt-stat-lbl">Draft</span></div>
    <div class="qt-stat" style="flex:2"><span class="qt-stat-val" style="font-size:16px">${totalVal.toFixed(2)}${cur}</span><span class="qt-stat-lbl">Total Value</span></div>
  </div>
  <div class="qt-tbl-wrap"><table class="qt-tbl">
    <thead><tr>
      <th>Quote #</th><th>Customer</th><th>Date</th><th>Valid Until</th><th>Status</th>
      <th style="text-align:center;width:90px">Proposals</th>
      <th style="text-align:right">Amount</th><th style="width:28px"></th>
    </tr></thead>
    <tbody>`;

  _qt.list.forEach(q => {
    const date   = q.quote_date  ? new Date(q.quote_date  + 'T00:00:00').toLocaleDateString(undefined, { month:'short', day:'numeric', year:'numeric' }) : '—';
    const expiry = q.expiry_date ? new Date(q.expiry_date + 'T00:00:00').toLocaleDateString(undefined, { month:'short', day:'numeric', year:'numeric' }) : '—';
    const proposalCount = q.proposal_count || 0;
    const proposalCell  = proposalCount > 0
      ? `<span class="qt-proposal-badge"><i class="fa fa-file-lines"></i> ${proposalCount}</span>`
      : `<span class="qt-proposal-badge qt-proposal-none">—</span>`;
    html += `<tr data-qt-id="${q.id}">
      <td><span class="qt-tbl-num">${escHtml(q.quote_number || String(q.id))}</span></td>
      <td class="qt-tbl-customer">${escHtml(q.customer_name || 'Walk-in')}</td>
      <td class="qt-tbl-muted">${date}</td>
      <td class="qt-tbl-muted">${expiry}</td>
      <td><span class="qt-badge qt-badge-${q.status}">${escHtml(q.status_label)}</span></td>
      <td style="text-align:center">${proposalCell}</td>
      <td class="qt-tbl-amt">${parseFloat(q.total || 0).toFixed(2)}${cur}</td>
      <td class="qt-tbl-chevron"><i class="fa fa-chevron-right"></i></td>
    </tr>`;
  });

  html += '</tbody></table></div>';
  $('#qt-list-body').innerHTML = html;
  $$('#qt-list-body tr[data-qt-id]').forEach(row => {
    row.addEventListener('click', () => _qtOpenDetail(Number(row.dataset.qtId)));
  });
}

// ── Detail ────────────────────────────────────────────────────────────────
async function _qtOpenDetail(id) {
  _qt.activeId = id;
  _qtShowView('detail');
  $('#qt-detail-title').textContent = 'Loading…';
  $('#qt-detail-body').innerHTML    = '<div class="qt-loading"><i class="fa fa-spinner fa-spin"></i></div>';
  $('#qt-detail-actions').innerHTML = '';

  const res = await API.quotation(id);
  if (res.status !== 200) {
    $('#qt-detail-body').innerHTML = '<div class="qt-empty"><i class="fa fa-circle-exclamation"></i> Failed to load.</div>';
    return;
  }

  const q   = res.body?.data;
  const cur = state.currency ? ' ' + state.currency : '';
  $('#qt-detail-title').textContent = q.quote_number;

  // Actions in topbar
  let acts = '';
  if (q.is_editable) {
    acts += `<button class="qt-act-btn" id="qd-edit"><i class="fa fa-pen"></i> Edit</button>`;
    if (q.status === 'draft') acts += `<button class="qt-act-btn" id="qd-sent"><i class="fa fa-paper-plane"></i> Mark Sent</button>`;
    if (q.status === 'sent')  acts += `<button class="qt-act-btn accent" id="qd-accept"><i class="fa fa-circle-check"></i> Accept</button>`;
    if (q.status !== 'rejected') acts += `<button class="qt-act-btn" id="qd-reject"><i class="fa fa-circle-xmark"></i> Reject</button>`;
  }
  acts += `<button class="qt-act-btn" id="qd-print"><i class="fa fa-print"></i> Print</button>`;
  acts += `<button class="qt-act-btn danger" id="qd-delete"><i class="fa fa-trash"></i> Delete</button>`;
  $('#qt-detail-actions').innerHTML = acts;

  // Document body
  const dateStr   = q.quote_date  ? new Date(q.quote_date  + 'T00:00:00').toLocaleDateString(undefined, { month:'long', day:'numeric', year:'numeric' }) : '—';
  const expiryStr = q.expiry_date ? new Date(q.expiry_date + 'T00:00:00').toLocaleDateString(undefined, { month:'long', day:'numeric', year:'numeric' }) : '—';

  const itemRows = (q.items || []).map((item, idx) => `<tr>
    <td class="qt-item-n">${idx + 1}</td>
    <td>${escHtml(item.description || '—')}</td>
    <td class="td-r">${parseFloat(item.quantity) % 1 === 0 ? parseInt(item.quantity) : parseFloat(item.quantity).toFixed(2)}</td>
    <td class="td-r">${parseFloat(item.unit_price).toFixed(2)}${cur}</td>
    <td class="td-r qt-item-total">${parseFloat(item.line_total).toFixed(2)}${cur}</td>
  </tr>`).join('');

  const body = `<div class="qt-doc">
    <div class="qt-doc-banner">
      <div class="qt-doc-banner-left">
        <div class="qt-doc-banner-num">${escHtml(q.quote_number)}</div>
        <div class="qt-doc-banner-type">Quotation</div>
      </div>
      <span class="qt-badge qt-badge-${q.status}">${escHtml(q.status_label)}</span>
    </div>
    <div class="qt-doc-body">
      <div class="qt-doc-info">
        <div>
          <div class="qt-doc-bill-label">Bill To</div>
          <div class="qt-doc-bill-name">${escHtml(q.customer_name || 'Walk-in Customer')}</div>
          ${q.reference ? `<div class="qt-doc-bill-ref"><i class="fa fa-hashtag" style="font-size:9px;opacity:.6"></i> ${escHtml(q.reference)}</div>` : ''}
        </div>
        <div class="qt-doc-meta">
          <div class="qt-doc-meta-row"><span>Quote Date</span><strong>${dateStr}</strong></div>
          <div class="qt-doc-meta-row"><span>Valid Until</span><strong>${expiryStr}</strong></div>
        </div>
      </div>

      <div class="qt-doc-items-wrap">
        <table class="qt-doc-items">
          <thead><tr>
            <th style="width:32px">#</th>
            <th>Description</th>
            <th class="td-r" style="width:64px">Qty</th>
            <th class="td-r" style="width:120px">Unit Price</th>
            <th class="td-r" style="width:120px">Total</th>
          </tr></thead>
          <tbody>${itemRows}</tbody>
        </table>
      </div>

      <div class="qt-doc-totals-wrap">
        <div class="qt-doc-totals">
          <div class="qt-doc-total-line"><span>Subtotal</span><span>${q.subtotal.toFixed(2)}${cur}</span></div>
          ${q.discount_amount > 0 ? `<div class="qt-doc-total-line"><span>Discount</span><span>-${q.discount_amount.toFixed(2)}${cur}</span></div>` : ''}
          ${q.tax_amount > 0      ? `<div class="qt-doc-total-line"><span>Tax</span><span>+${q.tax_amount.toFixed(2)}${cur}</span></div>` : ''}
          <div class="qt-doc-total-line grand"><span>Total</span><span>${q.total.toFixed(2)}${cur}</span></div>
        </div>
      </div>

      ${q.notes ? `<hr class="qt-doc-divider">
      <div class="qt-doc-notes-label"><i class="fa fa-note-sticky"></i> Notes</div>
      <div class="qt-doc-notes-box">${escHtml(q.notes)}</div>` : ''}
    </div>
  </div>`;

  $('#qt-detail-body').innerHTML = body;

  // Wire action buttons
  $('#qd-print')?.addEventListener('click', () => _qtPrint(q));
  $('#qd-edit')?.addEventListener('click', () => _qtOpenForm(q));
  $('#qd-sent')?.addEventListener('click', async () => {
    const r = await API.quotationSent(q.id);
    if (r.status === 200) { toast(`Marked as sent`, 'success'); _qtOpenDetail(q.id); } else toast(r.body?.message || 'Error', 'error');
  });
  $('#qd-accept')?.addEventListener('click', async () => {
    const r = await API.quotationAccept(q.id);
    if (r.status === 200) { toast(`Quotation accepted`, 'success'); _qtOpenDetail(q.id); } else toast(r.body?.message || 'Error', 'error');
  });
  $('#qd-reject')?.addEventListener('click', async () => {
    const r = await API.quotationReject(q.id);
    if (r.status === 200) { toast(`Quotation rejected`, 'info'); _qtOpenDetail(q.id); } else toast(r.body?.message || 'Error', 'error');
  });
  $('#qd-delete')?.addEventListener('click', async () => {
    if (!confirm(`Delete ${q.quote_number}?`)) return;
    const r = await API.deleteQuotation(q.id);
    if (r.status === 200) { toast('Quotation deleted', 'info'); loadQuotesList(); }
    else toast(r.body?.message || 'Cannot delete', 'error');
  });
}

// ── Shared: fetch letterhead from server (works even if Design tab never visited) ──
async function _fetchLetterhead() {
  // Locate the stub. Use the cache only for the ID — never trust the cached
  // has_canvas flag, because the editor saves without notifying this window,
  // so the flag can be stale (false) even after the user just saved a canvas.
  let stub = _dsAllData.find(d => d.type === 'letterhead');
  if (!stub) {
    const listRes = await API.designs('letterhead');
    if (listRes.status === 200) {
      const items = listRes.body?.data || [];
      stub = items.find(d => d.type === 'letterhead');
      if (stub && !_dsAllData.find(d => d.id === stub.id)) _dsAllData.push(stub);
    }
  }
  if (!stub) return null;
  // Always fetch the full design so we get the latest canvas_json regardless
  // of what has_canvas says in the cache.
  const res = await API.design(stub.id);
  if (res.status !== 200 || !res.body?.data) return null;
  const full = res.body.data;
  // Keep the cache in sync so the Design tab badge reflects reality.
  const idx = _dsAllData.findIndex(d => d.id === full.id);
  if (idx !== -1) _dsAllData[idx] = { ..._dsAllData[idx], has_canvas: full.has_canvas };
  return full.has_canvas ? full : null;
}

// ── Print (with optional letterhead) ─────────────────────────────────────
async function _qtPrint(q) {
  const lhFull = await _fetchLetterhead();
  await window.electronAPI.openQuotePrint({ quote: q, letterhead: lhFull, currency: state.currency });
}

// ── Form (Create / Edit) ──────────────────────────────────────────────────
async function _qtOpenForm(existing, prefill = null) {
  _qt.editingId  = existing?.id ?? null;
  _qt.lineSeq    = 0;
  _qtShowView('form');
  $('#qt-form-title').textContent = existing ? `Edit ${existing.quote_number}` : 'New Quotation';
  $('#qt-form-alert').style.display = 'none';

  // Load customers if needed
  if (!_qt.customers.length) {
    const cr = await API.customers('', 1);
    _qt.customers = cr.body?.data || [];
  }

  // Populate customer select
  const custSel = $('#qt-f-customer');
  custSel.innerHTML = '<option value="">— Walk-in —</option>';
  _qt.customers.forEach(c => {
    const opt = document.createElement('option');
    opt.value       = c.id;
    opt.textContent = c.name;
    custSel.appendChild(opt);
  });

  const today = new Date().toISOString().slice(0, 10);
  if (existing) {
    custSel.value             = existing.customer_id || '';
    $('#qt-f-ref').value      = existing.reference   || '';
    $('#qt-f-date').value     = existing.quote_date  || today;
    $('#qt-f-expiry').value   = existing.expiry_date || '';
    $('#qt-f-notes').value    = existing.notes       || '';
    $('#qt-f-discount').value = existing.discount_amount > 0 ? existing.discount_amount : '';
    $('#qt-f-tax').value      = existing.tax_amount      > 0 ? existing.tax_amount      : '';
  } else {
    custSel.value             = prefill?.customerId || '';
    $('#qt-f-ref').value      = '';
    $('#qt-f-date').value     = today;
    $('#qt-f-expiry').value   = '';
    $('#qt-f-notes').value    = '';
    $('#qt-f-discount').value = '';
    $('#qt-f-tax').value      = '';
  }

  // Line items
  $('#qt-items-body').innerHTML = '';
  if (existing?.items?.length) {
    existing.items.forEach(i => _qtAddLine(i.description, i.quantity, i.unit_price));
  } else if (prefill?.items?.length) {
    prefill.items.forEach(i => _qtAddLine(i.description, i.quantity, i.unit_price));
  }
  _qtRecalc();
}

function _qtAddLine(desc = '', qty = 1, price = 0) {
  const id  = ++_qt.lineSeq;
  const row = document.createElement('div');
  row.className   = 'qt-line-row';
  row.dataset.lid = id;
  row.innerHTML = `
    <div class="qt-line-desc">
      <input type="text" class="qt-line-input qt-line-desc-input" placeholder="Description or search product…" value="${escHtml(desc)}" data-lid="${id}">
      <div class="qt-product-suggest" id="qt-sug-${id}"></div>
    </div>
    <input type="number" class="qt-line-input qt-line-num" min="0.001" step="any" value="${qty}" data-lid="${id}" data-role="qty">
    <input type="number" class="qt-line-input qt-line-price" min="0" step="any" value="${price || ''}" data-lid="${id}" data-role="price" placeholder="0.00">
    <div class="qt-line-total" id="qt-lt-${id}">${(qty * price).toFixed(2)}</div>
    <button class="qt-line-del" data-lid="${id}"><i class="fa fa-xmark"></i></button>`;
  $('#qt-items-body').appendChild(row);

  // Product + service search on desc input
  const descInp = row.querySelector('.qt-line-desc-input');
  const sug     = row.querySelector('.qt-product-suggest');
  let sugTimer;
  descInp.addEventListener('input', () => {
    clearTimeout(sugTimer);
    const q = descInp.value.trim();
    if (q.length < 2) { sug.style.display = 'none'; sug.innerHTML = ''; return; }
    sugTimer = setTimeout(async () => {
      const [prodRes, svcRes] = await Promise.all([
        API.productSearch(q, 6),
        API.serviceMgmtCatalog(q),
      ]);
      const products = prodRes.body?.data || [];
      const services = svcRes.body?.data  || [];
      if (!products.length && !services.length) { sug.style.display = 'none'; return; }
      sug.innerHTML = [
        ...products.map(p => `<div class="qt-suggest-item" data-name="${escHtml(p.name)}" data-price="${p.unit_sell_price ?? 0}">
          <i class="fa fa-box" style="opacity:.45;margin-right:5px;font-size:11px"></i>${escHtml(p.name)}<span class="qt-suggest-sku">${p.sku ? escHtml(p.sku) : ''}</span>
        </div>`),
        ...services.map(s => `<div class="qt-suggest-item" data-name="${escHtml(s.name)}" data-price="${s.price ?? 0}">
          <i class="fa fa-screwdriver-wrench" style="color:#10b981;margin-right:5px;font-size:11px"></i>${escHtml(s.name)}${s.duration_label ? `<span class="qt-suggest-sku">${escHtml(s.duration_label)}</span>` : ''}
        </div>`),
      ].join('');
      sug.style.display = '';
      sug.querySelectorAll('.qt-suggest-item').forEach(el => {
        el.addEventListener('click', () => {
          descInp.value = el.dataset.name;
          row.querySelector('[data-role="price"]').value = parseFloat(el.dataset.price || 0).toFixed(2);
          sug.style.display = 'none';
          _qtRecalc();
        });
      });
    }, 200);
  });
  descInp.addEventListener('blur', () => setTimeout(() => { sug.style.display = 'none'; }, 200));

  row.querySelector('.qt-line-del').addEventListener('click', () => { row.remove(); _qtRecalc(); });
  row.querySelectorAll('[data-role="qty"],[data-role="price"]').forEach(inp => inp.addEventListener('input', _qtRecalc));
}

function _qtRecalc() {
  let subtotal = 0;
  $$('#qt-items-body .qt-line-row').forEach(row => {
    const qty   = parseFloat(row.querySelector('[data-role="qty"]')?.value   || 0);
    const price = parseFloat(row.querySelector('[data-role="price"]')?.value || 0);
    const lt    = isNaN(qty) || isNaN(price) ? 0 : qty * price;
    const lid   = row.dataset.lid;
    const ltEl  = $(`#qt-lt-${lid}`);
    if (ltEl) ltEl.textContent = lt.toFixed(2);
    subtotal += lt;
  });
  const discount = parseFloat($('#qt-f-discount').value) || 0;
  const tax      = parseFloat($('#qt-f-tax').value)      || 0;
  const total    = Math.max(0, subtotal - discount + tax);
  $('#qt-subtotal').textContent   = subtotal.toFixed(2);
  $('#qt-grand-total').textContent = total.toFixed(2);
}

$('#qt-add-line').addEventListener('click', () => _qtOpenAddModal());
$('#qt-f-discount').addEventListener('input', _qtRecalc);
$('#qt-f-tax').addEventListener('input', _qtRecalc);

// ── Quotation: Add Product Modal ──────────────────────────────────
const _qtMod = { product: null, timer: null };

function _qtOpenAddModal() {
  _qtMod.product = null;
  $('#qt-add-modal-q').value = '';
  $('#qt-add-modal-list').innerHTML = '<div class="qt-add-modal-empty"><i class="fa fa-magnifying-glass"></i><p>Type to search products or services</p></div>';
  $('#qt-add-modal-bottom').style.display = 'none';
  $('#qt-add-modal-add').style.display = 'none';
  $('#qt-add-modal-qty').value = '1';
  $('#qt-add-modal-price').value = '';
  $('#qt-add-modal-disc').value = '0';
  $('#qt-add-modal-total').textContent = '0.00';
  $('#qt-add-overlay').style.display = '';
  setTimeout(() => $('#qt-add-modal-q').focus(), 60);
}

function _qtCloseAddModal() {
  $('#qt-add-overlay').dataset.invMode = '';
  $('#qt-add-overlay').style.display = 'none';
}

async function _qtModalSearch(q) {
  const list = $('#qt-add-modal-list');
  if (!q) {
    list.innerHTML = '<div class="qt-add-modal-empty"><i class="fa fa-magnifying-glass"></i><p>Type to search products or services</p></div>';
    return;
  }
  list.innerHTML = '<div class="qt-add-modal-empty"><i class="fa fa-spinner fa-spin"></i><p>Searching…</p></div>';

  const [prodRes, svcRes] = await Promise.all([
    API.productSearch(q, 12),
    API.serviceMgmtCatalog(q),
  ]);
  const products = prodRes.body?.data || [];
  const services = svcRes.body?.data  || [];

  if (!products.length && !services.length) {
    list.innerHTML = '<div class="qt-add-modal-empty"><i class="fa fa-box-open"></i><p>No products or services found</p></div>';
    return;
  }

  const showLabels = products.length > 0 && services.length > 0;
  let html = '';

  if (products.length) {
    if (showLabels) html += `<div class="qt-add-modal-section-label"><i class="fa fa-box"></i> Products</div>`;
    html += products.map(p => {
      const stock     = parseFloat(p.stock_quantity ?? p.total_stock ?? p.quantity_on_hand ?? 0);
      const reserved  = parseFloat(p.reserved_qty ?? 0);
      const available = p.available_stock !== undefined ? parseFloat(p.available_stock) : stock;
      const inStock   = stock > 0;
      const price     = parseFloat(p.unit_sell_price ?? 0);
      const hasReserved = reserved > 0;

      const stockBadge = `<span class="qt-prod-stk ${inStock ? 'in' : 'out'}">${inStock ? stock + ' in stock' : 'Out of stock'}</span>`;
      const availClass  = available > 5 ? 'avail' : available > 0 ? 'avail-lo' : 'avail-no';
      const availBadge  = hasReserved
        ? `<span class="qt-prod-stk ${availClass}">${available} available</span>`
        : '';

      return `<div class="qt-add-modal-product" data-name="${escHtml(p.name)}" data-price="${price}">
        <div class="qt-prod-ico"><i class="fa fa-box"></i></div>
        <div class="qt-prod-nfo">
          <div class="qt-prod-nm">${escHtml(p.name)}</div>
          <div class="qt-prod-sub">
            ${p.sku ? `<span>${escHtml(p.sku)}</span>` : ''}
            ${stockBadge}${availBadge}
          </div>
        </div>
        <div class="qt-prod-prc">${price.toFixed(2)}</div>
      </div>`;
    }).join('');
  }

  if (services.length) {
    if (showLabels) html += `<div class="qt-add-modal-section-label"><i class="fa fa-screwdriver-wrench"></i> Services</div>`;
    html += services.map(s => {
      const price = parseFloat(s.price ?? 0);
      return `<div class="qt-add-modal-product" data-name="${escHtml(s.name)}" data-price="${price}">
        <div class="qt-prod-ico" style="background:rgba(16,185,129,.12);color:#10b981"><i class="fa fa-screwdriver-wrench"></i></div>
        <div class="qt-prod-nfo">
          <div class="qt-prod-nm">${escHtml(s.name)}</div>
          <div class="qt-prod-sub">
            ${s.duration_label ? `<span>${escHtml(s.duration_label)}</span>` : ''}
          </div>
        </div>
        <div class="qt-prod-prc">${price.toFixed(2)}</div>
      </div>`;
    }).join('');
  }

  list.innerHTML = html;
  list.querySelectorAll('.qt-add-modal-product').forEach(el => {
    el.addEventListener('click', () => {
      list.querySelectorAll('.qt-add-modal-product').forEach(e => e.classList.remove('sel'));
      el.classList.add('sel');
      _qtMod.product = { name: el.dataset.name, price: parseFloat(el.dataset.price || 0) };
      $('#qt-add-modal-price').value = _qtMod.product.price.toFixed(2);
      $('#qt-add-modal-disc').value  = '0';
      $('#qt-add-modal-qty').value   = '1';
      $('#qt-add-modal-sel-name').textContent = _qtMod.product.name;
      $('#qt-add-modal-bottom').style.display = '';
      $('#qt-add-modal-add').style.display    = '';
      _qtModalRecalc();
    });
  });
}

function _qtModalRecalc() {
  const qty   = parseFloat($('#qt-add-modal-qty').value)   || 0;
  const price = parseFloat($('#qt-add-modal-price').value) || 0;
  const disc  = parseFloat($('#qt-add-modal-disc').value)  || 0;
  $('#qt-add-modal-total').textContent = Math.max(0, qty * price - disc).toFixed(2);
}

$('#qt-add-modal-close').addEventListener('click', _qtCloseAddModal);
$('#qt-add-modal-cancel').addEventListener('click', _qtCloseAddModal);
$('#qt-add-overlay').addEventListener('click', e => { if (e.target === $('#qt-add-overlay')) _qtCloseAddModal(); });
document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && $('#qt-add-overlay').style.display !== 'none') _qtCloseAddModal();
});
$('#qt-add-modal-q').addEventListener('input', () => {
  clearTimeout(_qtMod.timer);
  _qtMod.timer = setTimeout(() => _qtModalSearch($('#qt-add-modal-q').value.trim()), 220);
});
['#qt-add-modal-qty', '#qt-add-modal-price', '#qt-add-modal-disc'].forEach(sel => {
  $(sel).addEventListener('input', _qtModalRecalc);
});
$('#qt-add-modal-add').addEventListener('click', () => {
  if (!_qtMod.product) return;
  const qty   = parseFloat($('#qt-add-modal-qty').value)   || 1;
  const price = parseFloat($('#qt-add-modal-price').value) || 0;
  const disc  = parseFloat($('#qt-add-modal-disc').value)  || 0;
  const effectivePrice = qty > 0 ? Math.max(0, (qty * price - disc) / qty) : price;
  _qtAddLine(_qtMod.product.name, qty, effectivePrice);
  _qtCloseAddModal();
  _qtRecalc();
});

// Save
$('#qt-form-save').addEventListener('click', async () => {
  const btn   = $('#qt-form-save');
  const alert = $('#qt-form-alert');
  alert.style.display = 'none';

  // Build items
  const items = [];
  $$('#qt-items-body .qt-line-row').forEach(row => {
    const desc  = row.querySelector('.qt-line-desc-input')?.value.trim() || '';
    const qty   = parseFloat(row.querySelector('[data-role="qty"]')?.value   || 0);
    const price = parseFloat(row.querySelector('[data-role="price"]')?.value || 0);
    if (!desc && qty <= 0 && price <= 0) return;
    items.push({ item_type: 'custom', description: desc, quantity: qty || 1, unit_price: price });
  });

  if (!items.length) {
    alert.textContent = 'Add at least one line item.';
    alert.className   = 'alert alert-danger';
    alert.style.display = '';
    return;
  }

  const body = {
    customer_id:     $('#qt-f-customer').value || null,
    reference:       $('#qt-f-ref').value.trim() || null,
    quote_date:      $('#qt-f-date').value,
    expiry_date:     $('#qt-f-expiry').value || null,
    notes:           $('#qt-f-notes').value.trim() || null,
    discount_amount: parseFloat($('#qt-f-discount').value) || 0,
    tax_amount:      parseFloat($('#qt-f-tax').value)      || 0,
    items,
  };

  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Saving…';

  const res = _qt.editingId
    ? await API.updateQuotation(_qt.editingId, body)
    : await API.createQuotation(body);

  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-floppy-disk"></i> Save Quotation';

  if (res.status >= 400) {
    const msg = res.body?.errors ? Object.values(res.body.errors).flat().join(' ') : (res.body?.message || 'Save failed.');
    alert.textContent    = msg;
    alert.className      = 'alert alert-danger';
    alert.style.display  = '';
    return;
  }

  toast(res.body?.message || 'Saved.', 'success');
  const saved = res.body?.data;
  if (saved) {
    _qt.activeId = saved.id;
    _qtOpenDetail(saved.id);
  } else {
    loadQuotesList();
  }
});

// Form cancel
$('#qt-form-back').addEventListener('click', () => {
  if (_qt.activeId) _qtOpenDetail(_qt.activeId); else _qtShowView('list');
});
$('#qt-form-cancel').addEventListener('click', () => {
  if (_qt.activeId) _qtOpenDetail(_qt.activeId); else _qtShowView('list');
});

// Detail back
$('#qt-detail-back').addEventListener('click', () => { _qt.activeId = null; loadQuotesList(); });

// ── View switcher ─────────────────────────────────────────────────────────
function _qtShowView(view) {
  // Ensure the parent quotes view is visible inside the Sales panel
  if ($('#sal-quotes-view').style.display === 'none') {
    _salSwitchView('quotes');
    return; // _salSwitchView → loadQuotesList → _qtShowView('list')
  }
  $('#qt-list-view').style.display   = view === 'list'   ? ''     : 'none';
  $('#qt-detail-view').style.display = view === 'detail' ? 'flex' : 'none';
  $('#qt-form-view').style.display   = view === 'form'   ? 'flex' : 'none';
}

// ── Search & status filter ────────────────────────────────────────────────
$('#qt-search').addEventListener('input', e => {
  clearTimeout(_qtSearchTimer);
  _qt.search = e.target.value.trim();
  _qtSearchTimer = setTimeout(loadQuotesList, 280);
});

// Status chips — scoped to quotation chips only (data-qst), not invoice chips (data-ist)
$$('.qt-chip[data-qst]').forEach(btn => {
  btn.addEventListener('click', () => {
    $$('.qt-chip[data-qst]').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    _qt.status = btn.dataset.qst;
    loadQuotesList();
  });
});

// Ribbon buttons (switch to quotes view first, then act)
$('#rb-qt-new')?.addEventListener('click', () => { _salSwitchView('quotes'); setTimeout(() => _qtOpenForm(null), 50); });
$('#rb-qt-refresh')?.addEventListener('click', () => { _salSwitchView('quotes'); });
$('#rb-sal-new-wizard')?.addEventListener('click', () => openSaleWizard());
$('#rb-sal-new-invoice')?.addEventListener('click', () => { _salSwitchView('invoices'); setTimeout(() => _invOpenForm(null), 50); });
$('#rb-sal-new-quotation')?.addEventListener('click', () => { _salSwitchView('quotes'); setTimeout(() => _qtOpenForm(null), 50); });
$('#rb-so-new')?.addEventListener('click', () => { _salSwitchView('orders'); setTimeout(() => _soOpenForm(null), 50); });
$('#rb-so-refresh')?.addEventListener('click', () => { _salSwitchView('orders'); loadSalesOrderList(); });
$('#qt-new-btn').addEventListener('click', () => _qtOpenForm(null));
// ── End Quotations Panel ──────────────────────────────────────────────────

// ── Invoices Panel ────────────────────────────────────────────────────────
const _inv = { view: 'list', search: '', status: 'all', activeId: null, editingId: null };
let _invSearchTimer;

function _invShowView(v) {
  $('#sinv-list-view').style.display   = v === 'list'   ? '' : 'none';
  $('#sinv-detail-view').style.display = v === 'detail' ? 'flex' : 'none';
  $('#sinv-form-view').style.display   = v === 'form'   ? 'flex' : 'none';
  _inv.view = v;
}

async function loadInvoicesList() {
  _invShowView('list');
  $('#sinv-list-loading').style.display = '';
  $('#sinv-list-body').innerHTML = '';

  const res = await API.invoices(_inv.search, _inv.status);
  $('#sinv-list-loading').style.display = 'none';

  if (res.status !== 200) {
    $('#sinv-list-body').innerHTML = '<div class="qt-empty"><i class="fa fa-circle-exclamation"></i> Failed to load invoices.</div>';
    return;
  }

  const items = res.body?.data || [];
  if (!items.length) {
    $('#sinv-list-body').innerHTML = `<div class="qt-empty">
      <i class="fa fa-file-invoice"></i>
      <h4>No Invoices Found</h4>
      <p>Create your first invoice to get started.</p>
      <button class="qt-new-btn" id="sinv-empty-new" style="margin-top:14px"><i class="fa fa-file-circle-plus"></i> New Invoice</button>
    </div>`;
    $('#sinv-empty-new')?.addEventListener('click', () => _invOpenForm(null));
    return;
  }

  const cur = state.currency ? ' ' + state.currency : '';

  // KPI stats
  const counts = { draft: 0, sent: 0, paid: 0, overdue: 0, cancelled: 0 };
  let totalVal = 0;
  items.forEach(inv => {
    const key = inv.is_overdue && inv.status !== 'paid' && inv.status !== 'cancelled' ? 'overdue' : inv.status;
    if (counts[key] !== undefined) counts[key]++;
    totalVal += parseFloat(inv.total || 0);
  });

  let html = `<div class="qt-stats">
    <div class="qt-stat"><span class="qt-stat-val">${items.length}</span><span class="qt-stat-lbl">Total</span></div>
    <div class="qt-stat blue"><span class="qt-stat-val">${counts.sent}</span><span class="qt-stat-lbl">Sent</span></div>
    <div class="qt-stat green"><span class="qt-stat-val">${counts.paid}</span><span class="qt-stat-lbl">Paid</span></div>
    <div class="qt-stat" style="--val-col:#ef4444"><span class="qt-stat-val" style="color:#ef4444">${counts.overdue}</span><span class="qt-stat-lbl">Overdue</span></div>
    <div class="qt-stat" style="flex:2"><span class="qt-stat-val" style="font-size:16px">${totalVal.toFixed(2)}${cur}</span><span class="qt-stat-lbl">Total Value</span></div>
  </div>
  <div class="qt-tbl-wrap"><table class="qt-tbl">
    <thead><tr>
      <th>Invoice #</th><th>Customer</th><th>Issue Date</th><th>Due Date</th><th>Status</th>
      <th style="text-align:center;width:90px">Proposals</th>
      <th style="text-align:right">Amount</th><th style="width:28px"></th>
    </tr></thead>
    <tbody>`;

  items.forEach(inv => {
    const isOverdue = inv.is_overdue && inv.status !== 'paid' && inv.status !== 'cancelled';
    const statusKey = isOverdue ? 'overdue' : inv.status;
    const issueDate = inv.issue_date ? new Date(inv.issue_date + 'T00:00:00').toLocaleDateString(undefined, { month:'short', day:'numeric', year:'numeric' }) : '—';
    const dueDate   = inv.due_date   ? new Date(inv.due_date   + 'T00:00:00').toLocaleDateString(undefined, { month:'short', day:'numeric', year:'numeric' }) : '—';
    const overdueClass = isOverdue ? 'style="color:#ef4444;font-weight:600"' : '';
    const proposalCount = inv.proposal_count || 0;
    const proposalCell  = proposalCount > 0
      ? `<span class="qt-proposal-badge"><i class="fa fa-file-lines"></i> ${proposalCount}</span>`
      : `<span class="qt-proposal-badge qt-proposal-none">—</span>`;
    html += `<tr data-sinv-id="${inv.id}">
      <td><span class="qt-tbl-num">${escHtml(inv.invoice_number)}</span></td>
      <td class="qt-tbl-customer">${escHtml(inv.customer_name || 'Walk-in')}</td>
      <td class="qt-tbl-muted">${issueDate}</td>
      <td class="qt-tbl-muted" ${overdueClass}>${dueDate}</td>
      <td><span class="qt-badge qt-badge-${statusKey}">${escHtml(inv.status_label)}</span></td>
      <td style="text-align:center">${proposalCell}</td>
      <td class="qt-tbl-amt">${parseFloat(inv.total || 0).toFixed(2)}${cur}</td>
      <td class="qt-tbl-chevron"><i class="fa fa-chevron-right"></i></td>
    </tr>`;
  });

  html += '</tbody></table></div>';
  $('#sinv-list-body').innerHTML = html;

  $$('#sinv-list-body tr[data-sinv-id]').forEach(row => {
    row.addEventListener('click', () => _invOpenDetail(Number(row.dataset.sinvId)));
  });
}

async function _invOpenDetail(id) {
  _inv.activeId = id;
  _invShowView('detail');
  $('#sinv-detail-title').textContent = 'Loading…';
  $('#sinv-detail-body').innerHTML    = '<div class="qt-loading"><i class="fa fa-spinner fa-spin"></i></div>';
  $('#sinv-detail-actions').innerHTML = '';

  const res = await API.invoice(id);
  if (res.status !== 200) {
    const msg = res.body?.message || (res.status === 0 ? 'Cannot reach server' : 'Failed to load');
    $('#sinv-detail-body').innerHTML = `<div class="qt-empty">
      <i class="fa fa-circle-exclamation"></i>
      <h4>Could not load invoice</h4>
      <p style="font-size:12px;color:var(--text-muted)">${escHtml(msg)} (${res.status || 'network error'})</p>
      <button class="qt-new-btn" id="invd-retry" style="margin-top:12px"><i class="fa fa-rotate-right"></i> Retry</button>
    </div>`;
    $('#invd-retry')?.addEventListener('click', () => _invOpenDetail(id));
    return;
  }

  const inv = res.body?.data;
  if (!inv) {
    $('#sinv-detail-body').innerHTML = '<div class="qt-empty"><i class="fa fa-circle-exclamation"></i> Invalid response from server.</div>';
    return;
  }
  const cur  = state.currency ? ' ' + state.currency : '';
  $('#sinv-detail-title').textContent = inv.invoice_number;

  // Action buttons
  let acts = '';
  if (inv.is_editable) {
    acts += `<button class="qt-act-btn" id="invd-edit"><i class="fa fa-pen"></i> Edit</button>`;
  }
  if (inv.status === 'draft') {
    acts += `<button class="qt-act-btn" id="invd-sent"><i class="fa fa-paper-plane"></i> Mark Sent</button>`;
  }
  if (inv.status === 'sent' || inv.status === 'overdue') {
    acts += `<button class="qt-act-btn accent" id="invd-paid"><i class="fa fa-circle-check"></i> Mark Paid</button>`;
  }
  if (inv.status === 'sent') {
    acts += `<button class="qt-act-btn" id="invd-overdue"><i class="fa fa-circle-exclamation"></i> Mark Overdue</button>`;
  }
  if (inv.status !== 'paid' && inv.status !== 'cancelled') {
    acts += `<button class="qt-act-btn" id="invd-cancel"><i class="fa fa-ban"></i> Cancel</button>`;
  }
  acts += `<button class="qt-act-btn" id="invd-print"><i class="fa fa-print"></i> Print</button>`;
  if (inv.status !== 'paid') {
    acts += `<button class="qt-act-btn danger" id="invd-delete"><i class="fa fa-trash"></i> Delete</button>`;
  }
  $('#sinv-detail-actions').innerHTML = acts;

  const dateStr = inv.issue_date ? new Date(inv.issue_date + 'T00:00:00').toLocaleDateString(undefined, { month:'long', day:'numeric', year:'numeric' }) : '—';
  const dueStr  = inv.due_date   ? new Date(inv.due_date   + 'T00:00:00').toLocaleDateString(undefined, { month:'long', day:'numeric', year:'numeric' }) : '—';

  // ── Per-line aggregates ───────────────────────────────────────────────────
  const taxRulesForLookup = Array.isArray(state.receiptSettings?.tax_rules)
    ? state.receiptSettings.tax_rules.filter(r => parseFloat(r.value || 0) > 0)
    : [];

  let rawSubtotal = 0, perLineDiscTotal = 0, perLineTaxTotal = 0;
  const hasAnyDisc = (inv.items || []).some(i => parseFloat(i.discount_value) > 0);
  const hasAnyTax  = (inv.items || []).some(i => parseFloat(i.tax_pct) > 0);

  (inv.items || []).forEach(item => {
    const gross    = parseFloat(item.quantity) * parseFloat(item.unit_price);
    const discType = item.discount_type || 'pct';
    const discVal  = parseFloat(item.discount_value) || 0;
    const discAmt  = discType === 'flat' ? Math.min(discVal, gross) : (gross * discVal / 100);
    const net      = Math.max(0, gross - discAmt);
    const taxType  = item.tax_type || 'pct';
    const taxVal   = parseFloat(item.tax_pct) || 0;
    const taxAmt   = taxType === 'flat' ? taxVal : (net * taxVal / 100);
    rawSubtotal      += gross;
    perLineDiscTotal += discAmt;
    perLineTaxTotal  += taxAmt;
  });

  // ── Item table rows ───────────────────────────────────────────────────────
  const itemRows = (inv.items || []).map((item, idx) => {
    const qty      = parseFloat(item.quantity);
    const price    = parseFloat(item.unit_price);
    const gross    = qty * price;
    const discType = item.discount_type || 'pct';
    const discVal  = parseFloat(item.discount_value) || 0;
    const discAmt  = discType === 'flat' ? Math.min(discVal, gross) : (gross * discVal / 100);
    const net      = Math.max(0, gross - discAmt);
    const taxType  = item.tax_type || 'pct';
    const taxVal   = parseFloat(item.tax_pct) || 0;
    const taxAmt   = taxType === 'flat' ? taxVal : (net * taxVal / 100);

    // Disc cell
    let discCell = '—';
    if (discVal > 0) {
      const discLabel = discType === 'flat'
        ? `−${discAmt.toFixed(2)}${cur}`
        : `${discVal}%`;
      discCell = `<span class="invd-adj-badge invd-disc-badge">${discLabel}</span>`;
    }

    // Tax cell — try to match a rule name from settings
    let taxCell = '—';
    if (taxVal > 0) {
      const matchRule = taxRulesForLookup.find(r =>
        (r.type === taxType || (r.type === 'percentage' && taxType === 'pct')) &&
        String(r.value) === String(taxVal)
      );
      const taxLabel = matchRule
        ? escHtml(matchRule.name) + (taxType !== 'flat' ? ' ' + taxVal + '%' : '')
        : (taxType === 'flat' ? taxAmt.toFixed(2) + cur : taxVal + '%');
      taxCell = `<span class="invd-adj-badge invd-tax-badge">${taxLabel}</span>`;
    }

    return `<tr>
      <td class="qt-item-n">${idx + 1}</td>
      <td>${escHtml(item.description || '—')}</td>
      <td class="td-r">${qty % 1 === 0 ? parseInt(qty) : qty.toFixed(2)}</td>
      <td class="td-r">${price.toFixed(2)}${cur}</td>
      <td class="td-r">${discCell}</td>
      <td class="td-r">${taxCell}</td>
      <td class="td-r qt-item-total">${parseFloat(item.line_total).toFixed(2)}${cur}</td>
    </tr>`;
  }).join('');

  // ── Summary rows ──────────────────────────────────────────────────────────
  const hasPerLineAdj  = perLineDiscTotal > 0.001 || perLineTaxTotal > 0.001;
  const hasHeaderDisc  = parseFloat(inv.discount_amount) > 0;
  const hasHeaderTax   = parseFloat(inv.tax_amount) > 0;

  let summaryHtml = '';
  if (hasPerLineAdj) {
    summaryHtml += `<div class="qt-doc-total-line"><span>Gross Subtotal</span><span>${rawSubtotal.toFixed(2)}${cur}</span></div>`;
    if (perLineDiscTotal > 0.001)
      summaryHtml += `<div class="qt-doc-total-line invd-tot-disc"><span>Item Discounts</span><span>−${perLineDiscTotal.toFixed(2)}${cur}</span></div>`;
    if (perLineTaxTotal > 0.001)
      summaryHtml += `<div class="qt-doc-total-line invd-tot-tax"><span>Item Taxes</span><span>+${perLineTaxTotal.toFixed(2)}${cur}</span></div>`;
    if (hasHeaderDisc || hasHeaderTax)
      summaryHtml += `<div class="qt-doc-total-line invd-tot-sub"><span>Line Subtotal</span><span>${parseFloat(inv.subtotal).toFixed(2)}${cur}</span></div>`;
  } else {
    summaryHtml += `<div class="qt-doc-total-line"><span>Subtotal</span><span>${parseFloat(inv.subtotal).toFixed(2)}${cur}</span></div>`;
  }
  if (hasHeaderDisc)
    summaryHtml += `<div class="qt-doc-total-line invd-tot-disc"><span>Discount</span><span>−${parseFloat(inv.discount_amount).toFixed(2)}${cur}</span></div>`;
  if (hasHeaderTax)
    summaryHtml += `<div class="qt-doc-total-line invd-tot-tax"><span>Tax</span><span>+${parseFloat(inv.tax_amount).toFixed(2)}${cur}</span></div>`;
  summaryHtml += `<div class="qt-doc-total-line grand"><span>Total</span><span>${parseFloat(inv.total).toFixed(2)}${cur}</span></div>`;

  let body;
  try {
  const totalAmt   = parseFloat(inv.total).toFixed(2);

  body = `<div class="invd-layout">
    <div class="invd-main">

      <!-- ── Invoice details ─────────────────────────────────────────── -->
      <div class="qt-card" style="margin-bottom:16px">
        <div class="qt-card-hd"><i class="fa fa-circle-info"></i> Invoice Details</div>
        <div class="qt-fields-grid">
          <div class="qt-field">
            <span class="qt-label">Customer</span>
            <div class="invd-view-val">${escHtml(inv.customer_name || 'Walk-in Customer')}</div>
          </div>
          <div class="qt-field">
            <span class="qt-label">Status</span>
            <div><span class="qt-badge qt-badge-${inv.status}">${escHtml(inv.status_label)}</span></div>
          </div>
          <div class="qt-field">
            <span class="qt-label">Issue Date</span>
            <div class="invd-view-val">${dateStr}</div>
          </div>
          <div class="qt-field">
            <span class="qt-label">Due Date</span>
            <div class="invd-view-val">${dueStr}</div>
          </div>
          ${inv.payment_method_label ? `<div class="qt-field">
            <span class="qt-label">Payment Method</span>
            <div class="invd-view-val">${escHtml(inv.payment_method_label)}</div>
          </div>` : ''}
          ${inv.reference ? `<div class="qt-field">
            <span class="qt-label">Reference</span>
            <div class="invd-view-val">${escHtml(inv.reference)}</div>
          </div>` : ''}
          <div class="qt-field">
            <span class="qt-label">Amount Due</span>
            <div class="invd-view-val invd-view-amt">${totalAmt}${cur}</div>
          </div>
        </div>
      </div>

      <!-- ── Line items ───────────────────────────────────────────────── -->
      <div class="qt-card" style="margin-bottom:16px">
        <div class="qt-card-hd"><i class="fa fa-list"></i> Items</div>
        <table class="qt-doc-items">
          <thead><tr>
            <th style="width:32px">#</th>
            <th>Description</th>
            <th class="td-r" style="width:52px">Qty</th>
            <th class="td-r" style="width:105px">Unit Price</th>
            <th class="td-r" style="width:90px">Disc</th>
            <th class="td-r" style="width:115px">Tax</th>
            <th class="td-r" style="width:105px">Total</th>
          </tr></thead>
          <tbody>${itemRows}</tbody>
        </table>
      </div>

      <!-- ── Summary + notes ─────────────────────────────────────────── -->
      <div class="qt-card">
        <div class="qt-card-hd"><i class="fa fa-calculator"></i> Summary</div>
        <div style="padding:16px">
          <div class="qt-doc-totals-wrap">
            <div class="qt-doc-totals">${summaryHtml}</div>
          </div>
          ${inv.notes ? `<hr class="qt-doc-divider">
          <div class="qt-doc-notes-label"><i class="fa fa-note-sticky"></i> Notes</div>
          <div class="qt-doc-notes-box">${escHtml(inv.notes)}</div>` : ''}
        </div>
      </div>

    </div>

    <div class="invd-sidebar">
      <div class="invd-sidebar-label">Quick Actions</div>

      <button class="invd-quick-btn" id="invd-qa-payment">
        <span class="invd-quick-icon" style="background:#dbeafe;color:#1d4ed8"><i class="fa fa-credit-card"></i></span>
        <span class="invd-quick-text">
          <span class="invd-quick-title">Payment</span>
          <span class="invd-quick-sub">Record a payment</span>
        </span>
        <i class="fa fa-chevron-right invd-quick-arrow"></i>
      </button>

      <button class="invd-quick-btn" id="invd-qa-proposal">
        <span class="invd-quick-icon" style="background:#ede9fe;color:#6d28d9"><i class="fa fa-file-lines"></i></span>
        <span class="invd-quick-text">
          <span class="invd-quick-title">Create Project Proposal</span>
          <span class="invd-quick-sub">Generate a proposal from this invoice</span>
        </span>
        <i class="fa fa-chevron-right invd-quick-arrow"></i>
      </button>

      <button class="invd-quick-btn" id="invd-qa-pm">
        <span class="invd-quick-icon" style="background:#dcfce7;color:#15803d"><i class="fa fa-list-check"></i></span>
        <span class="invd-quick-text">
          <span class="invd-quick-title">Move to Project Manager</span>
          <span class="invd-quick-sub">Track this invoice as a project</span>
        </span>
        <i class="fa fa-chevron-right invd-quick-arrow"></i>
      </button>
    </div>
  </div>`;
  } catch (err) {
    console.error('[_invOpenDetail] body build error:', err);
    $('#sinv-detail-body').innerHTML = `<div class="qt-empty"><i class="fa fa-circle-exclamation"></i> Render error: ${escHtml(err.message)}</div>`;
    return;
  }

  $('#sinv-detail-body').innerHTML = body;

  // Wire actions
  $('#invd-edit')?.addEventListener('click', () => _invOpenForm(inv));
  $('#invd-sent')?.addEventListener('click', () => _invShowSendModal(inv));
  $('#invd-paid')?.addEventListener('click', async () => {
    const r = await API.invoicePaid(inv.id);
    if (r.status === 200) { toast('Invoice marked as paid', 'success'); _invOpenDetail(inv.id); }
    else toast(r.body?.message || 'Error', 'error');
  });
  $('#invd-overdue')?.addEventListener('click', async () => {
    const r = await API.invoiceOverdue(inv.id);
    if (r.status === 200) { toast('Marked as overdue', 'info'); _invOpenDetail(inv.id); }
    else toast(r.body?.message || 'Error', 'error');
  });
  $('#invd-cancel')?.addEventListener('click', async () => {
    if (!confirm(`Cancel invoice ${inv.invoice_number}?`)) return;
    const r = await API.invoiceCancel(inv.id);
    if (r.status === 200) { toast('Invoice cancelled', 'info'); _invOpenDetail(inv.id); }
    else toast(r.body?.message || 'Error', 'error');
  });
  $('#invd-print')?.addEventListener('click', () => _invPrint(inv));
  $('#invd-delete')?.addEventListener('click', async () => {
    if (!confirm(`Delete ${inv.invoice_number}?`)) return;
    const r = await API.deleteInvoice(inv.id);
    if (r.status === 200) { toast('Invoice deleted', 'info'); loadInvoicesList(); }
    else toast(r.body?.message || 'Error', 'error');
  });

  // Quick action sidebar
  $('#invd-qa-payment')?.addEventListener('click', () => _invdComingSoon('Payment'));
  $('#invd-qa-proposal')?.addEventListener('click', () => openInvProposalModal(inv));
  $('#invd-qa-pm')?.addEventListener('click', () => _invdComingSoon('Move to Project Manager'));
}

// ── Send Invoice modal (share link + social sharing) ─────────────────────────
async function _invShowSendModal(inv) {
  // Remove any existing instance
  document.getElementById('invd-send-modal')?.remove();

  const invNum = escHtml(inv.invoice_number || '');
  const custName = escHtml(inv.customer_name || '');

  // Build modal skeleton with loading state
  const overlay = document.createElement('div');
  overlay.id = 'invd-send-modal';
  overlay.className = 'invd-send-overlay';
  overlay.innerHTML = `
    <div class="invd-send-box" role="dialog" aria-modal="true">
      <div class="invd-send-hdr">
        <div class="invd-send-hdr-left">
          <span class="invd-send-hdr-icon"><i class="fa fa-paper-plane"></i></span>
          <div>
            <div class="invd-send-title">Send Invoice</div>
            <div class="invd-send-sub">${invNum}${custName ? ' · ' + custName : ''}</div>
          </div>
        </div>
        <button class="invd-send-close" id="invd-send-close"><i class="fa fa-xmark"></i></button>
      </div>

      <div class="invd-send-body">
        <div class="invd-send-link-section">
          <div class="invd-send-section-lbl"><i class="fa fa-link"></i> Shareable Link</div>
          <div class="invd-send-link-row">
            <div class="invd-send-link-box" id="invd-send-link-box">
              <i class="fa fa-spinner fa-spin" style="color:var(--text-muted)"></i>
              <span id="invd-send-link-txt" style="color:var(--text-muted)">Generating link…</span>
            </div>
            <button class="invd-send-copy-btn" id="invd-send-copy" disabled>
              <i class="fa fa-copy"></i> Copy
            </button>
          </div>
        </div>

        <div class="invd-send-social-section">
          <div class="invd-send-section-lbl"><i class="fa fa-share-nodes"></i> Share via</div>
          <div class="invd-send-social-row">
            <button class="invd-send-social-btn invd-social-wa" id="invd-send-wa" disabled>
              <svg class="invd-social-ico" viewBox="0 0 24 24" fill="currentColor"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347z"/><path d="M12 0C5.373 0 0 5.373 0 12c0 2.127.558 4.122 1.532 5.849L.057 23.57a.75.75 0 0 0 .918.919l5.709-1.47A11.944 11.944 0 0 0 12 24c6.627 0 12-5.373 12-12S18.627 0 12 0zm0 21.75a9.724 9.724 0 0 1-4.966-1.362l-.357-.212-3.685.949.974-3.578-.232-.37A9.75 9.75 0 1 1 12 21.75z"/></svg>
              WhatsApp
            </button>
            <button class="invd-send-social-btn invd-social-fb" id="invd-send-fb" disabled>
              <svg class="invd-social-ico" viewBox="0 0 24 24" fill="currentColor"><path d="M24 12.073C24 5.405 18.627 0 12 0S0 5.405 0 12.073C0 18.1 4.388 23.094 10.125 24v-8.437H7.078v-3.49h3.047V9.41c0-3.025 1.792-4.697 4.533-4.697 1.312 0 2.686.236 2.686.236v2.97h-1.513c-1.491 0-1.956.932-1.956 1.889v2.265h3.328l-.532 3.49h-2.796V24C19.612 23.094 24 18.1 24 12.073z"/></svg>
              Facebook
            </button>
            <button class="invd-send-social-btn invd-social-email" id="invd-send-email" disabled>
              <i class="fa fa-envelope invd-social-ico"></i>
              Email
            </button>
          </div>
        </div>

        <div class="invd-send-info-note">
          <i class="fa fa-circle-info"></i>
          Anyone with this link can view the invoice without logging in.
        </div>
      </div>

      <div class="invd-send-footer">
        <button class="invd-send-btn-cancel" id="invd-send-cancel">Close</button>
        <button class="invd-send-btn-send" id="invd-send-confirm">
          <i class="fa fa-paper-plane"></i> Mark as Sent
        </button>
      </div>
    </div>`;

  document.body.appendChild(overlay);
  requestAnimationFrame(() => overlay.classList.add('invd-send-in'));

  let shareUrl = inv.share_url || null;

  // Enable share link (generate token if needed)
  const fetchShareLink = async () => {
    const r = await API.invoiceEnableShare(inv.id);
    if (r.status === 200 && r.body?.share_url) {
      shareUrl = r.body.share_url;
      const box  = document.getElementById('invd-send-link-box');
      const txt  = document.getElementById('invd-send-link-txt');
      const copy = document.getElementById('invd-send-copy');
      const wa   = document.getElementById('invd-send-wa');
      const fb   = document.getElementById('invd-send-fb');
      const em   = document.getElementById('invd-send-email');
      if (txt) { box.innerHTML = ''; box.textContent = shareUrl; }
      if (copy) copy.disabled = false;
      if (wa)   wa.disabled   = false;
      if (fb)   fb.disabled   = false;
      if (em)   em.disabled   = false;
    } else {
      const box = document.getElementById('invd-send-link-box');
      if (box) box.innerHTML = '<span style="color:#ef4444"><i class="fa fa-triangle-exclamation"></i> Failed to generate link</span>';
    }
  };
  fetchShareLink();

  // Close helpers
  let _closing = false;
  const close = () => {
    if (_closing) return;
    _closing = true;
    overlay.classList.remove('invd-send-in');
    // Fallback: if transitionend never fires (prefers-reduced-motion, timing
    // edge case), remove after the transition duration anyway.
    const fallback = setTimeout(() => overlay.remove(), 350);
    overlay.addEventListener('transitionend', () => { clearTimeout(fallback); overlay.remove(); }, { once: true });
    document.removeEventListener('keydown', escClose);
  };
  // NOTE: no { once: true } — we want to check EVERY keydown while the modal
  // is open, not just the first one (once:true removes the listener after any key).
  function escClose(e) { if (e.key === 'Escape') close(); }
  document.getElementById('invd-send-close')?.addEventListener('click', close);
  document.getElementById('invd-send-cancel')?.addEventListener('click', close);
  overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
  document.addEventListener('keydown', escClose);

  // Copy link
  document.getElementById('invd-send-copy')?.addEventListener('click', async () => {
    if (!shareUrl) return;
    try {
      await navigator.clipboard.writeText(shareUrl);
      const btn = document.getElementById('invd-send-copy');
      if (btn) { btn.innerHTML = '<i class="fa fa-check"></i> Copied!'; btn.classList.add('copied'); }
      setTimeout(() => {
        const b = document.getElementById('invd-send-copy');
        if (b) { b.innerHTML = '<i class="fa fa-copy"></i> Copy'; b.classList.remove('copied'); }
      }, 2000);
    } catch { toast('Could not copy to clipboard', 'error'); }
  });

  // Social share handlers
  document.getElementById('invd-send-wa')?.addEventListener('click', () => {
    if (!shareUrl) return;
    const msg = `Hi, please find your invoice ${inv.invoice_number} here: ${shareUrl}`;
    window.electronAPI.openExternal(`https://wa.me/?text=${encodeURIComponent(msg)}`);
  });

  document.getElementById('invd-send-fb')?.addEventListener('click', () => {
    if (!shareUrl) return;
    window.electronAPI.openExternal(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`);
  });

  document.getElementById('invd-send-email')?.addEventListener('click', () => {
    if (!shareUrl) return;
    const subj = `Invoice ${inv.invoice_number}`;
    const body  = `Hi${custName ? ' ' + inv.customer_name : ''},\n\nPlease find your invoice ${inv.invoice_number} at the link below:\n\n${shareUrl}\n\nThank you for your business.`;
    window.electronAPI.openExternal(`mailto:?subject=${encodeURIComponent(subj)}&body=${encodeURIComponent(body)}`);
  });

  // Mark as Sent
  document.getElementById('invd-send-confirm')?.addEventListener('click', async () => {
    const btn = document.getElementById('invd-send-confirm');
    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Sending…'; }
    const r = await API.invoiceSent(inv.id);
    if (r.status === 200) {
      close();
      toast('Invoice marked as sent', 'success');
      _invOpenDetail(inv.id);
    } else {
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa fa-paper-plane"></i> Mark as Sent'; }
      toast(r.body?.message || 'Error', 'error');
    }
  });
}

function _invdComingSoon(feature) {
  const existing = $('#sinv-detail-body .invd-sidebar .invd-cs-toast');
  if (existing) return;
  const el = document.createElement('div');
  el.className = 'invd-cs-toast';
  el.innerHTML = `<i class="fa fa-clock"></i> <strong>${escHtml(feature)}</strong> — Coming soon`;
  $('#sinv-detail-body .invd-sidebar').appendChild(el);
  setTimeout(() => el.remove(), 2800);
}

// ── Invoice → Create Project Proposal modal ───────────────────────────────
let _invPropInv = null;

async function openInvProposalModal(inv) {
  _invPropInv = inv;

  // Pre-fill project name and reset fields
  $('#invd-pm-name').value    = `Proposal for ${inv.invoice_number}`;
  $('#invd-pm-desc').value    = '';
  $('#invd-pm-alert').style.display      = 'none';
  $('#invd-pm-progress').style.display   = 'none';
  $('#invd-pm-add-cust-form').style.display = 'none';
  $('#invd-pm-cust-name').value  = '';
  $('#invd-pm-cust-phone').value = '';
  $('#invd-pm-subtitle').textContent = `From ${inv.invoice_number}`;
  $('#invd-pm-inv-page-label').textContent = `Invoice ${inv.invoice_number}`;

  // Populate customer dropdown
  const sel = $('#invd-pm-customer');
  sel.innerHTML = '<option value="">— Walk-in —</option>';
  const cr = await API.customers('', 1);
  if (cr.status === 200) {
    (cr.body?.data || []).forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id; opt.textContent = c.name;
      if (c.id === inv.customer_id) opt.selected = true;
      sel.appendChild(opt);
    });
  }

  $('#invd-prop-modal').style.display = 'flex';
  setTimeout(() => $('#invd-pm-name')?.focus(), 60);
}

function _closeInvProposalModal() {
  $('#invd-prop-modal').style.display = 'none';
  _invPropInv = null;
}

function _invPmProgress(title, sub, pct) {
  const prog = $('#invd-pm-progress');
  prog.style.display = 'flex';
  $('#invd-pm-prog-title').textContent = title;
  $('#invd-pm-prog-sub').textContent   = sub;
  $('#invd-pm-prog-bar').style.width   = pct + '%';
}

async function _generateInvProposal() {
  const title   = $('#invd-pm-name').value.trim();
  const desc    = $('#invd-pm-desc').value.trim();
  const custSel = $('#invd-pm-customer');
  const rawText = custSel.options[custSel.selectedIndex]?.text || '';
  const client  = rawText === '— Walk-in —' ? null : rawText.trim() || null;
  const alertEl = $('#invd-pm-alert');

  alertEl.style.display = 'none';
  if (!title) {
    alertEl.textContent = 'Project name is required.';
    alertEl.style.display = '';
    $('#invd-pm-name').focus();
    return;
  }
  if (!desc) {
    alertEl.textContent = 'Project description is required — it tells the AI what to write.';
    alertEl.style.display = '';
    $('#invd-pm-desc').focus();
    return;
  }

  const inv = _invPropInv;
  if (!inv) return;

  const genBtn = $('#invd-pm-generate');
  genBtn.disabled = true;

  try {
    // Step 1 — create blank 6-page proposal skeleton
    _invPmProgress('Creating proposal…', 'Setting up 6 pages', 10);
    const createRes = await API.createProposal({ title, client });
    if (createRes.status !== 201 || !createRes.body?.data?.group) {
      throw new Error(createRes.body?.errors?.title?.[0] || createRes.body?.message || 'Failed to create proposal.');
    }
    const group = createRes.body.data.group;

    // Step 2 — AI fills all 6 pages on the server (this is the slow step, ~10-20s)
    _invPmProgress('Generating AI content…', 'Writing all 6 proposal pages — this may take up to 60 seconds', 30);
    const fillRes = await API.aiProposalFill(group, { title, client, description: desc });
    if (fillRes.status !== 200) {
      // Surface the real AI error — do NOT silently continue with blank pages
      throw new Error(fillRes.body?.message || 'AI generation failed. Please check your description and try again.');
    }

    // Step 3 — fetch the 6 AI-filled pages and open the editor
    // The invoice is auto-imported as the last page by the editor on open
    _invPmProgress('Opening editor…', 'Loading proposal into editor', 85);
    const pagesRes = await API.proposalPages(group);
    if (pagesRes.status !== 200 || !pagesRes.body?.data?.pages?.length) {
      throw new Error('Failed to load proposal pages.');
    }
    const prop = pagesRes.body.data;

    await window.electronAPI.openEditor({
      proposalTitle:        prop.title,
      proposalGroup:        prop.group,
      proposalPages:        prop.pages,
      proposalStartPage:    0,
      autoImportInvoiceId:  inv.id,
      width:                prop.pages[0]?.width  ?? 794,
      height:               prop.pages[0]?.height ?? 1123,
      id:                   prop.pages[0]?.id,
      type:                 'project-proposal',
      title:                prop.title,
    });

    _closeInvProposalModal();
    toast(`Proposal "${title}" created with AI content — opening editor`, 'success');

  } catch (err) {
    $('#invd-pm-progress').style.display = 'none';
    alertEl.textContent = err.message || 'Generation failed. Please try again.';
    alertEl.style.display = '';
  } finally {
    genBtn.disabled = false;
  }
}

// Wire modal buttons once on DOMContentLoaded
document.addEventListener('DOMContentLoaded', () => {
  $('#invd-pm-close')?.addEventListener('click', _closeInvProposalModal);
  $('#invd-pm-cancel')?.addEventListener('click', _closeInvProposalModal);
  $('#invd-prop-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) _closeInvProposalModal(); });
  $('#invd-pm-generate')?.addEventListener('click', _generateInvProposal);

  // Add customer toggle
  $('#invd-pm-add-cust-toggle')?.addEventListener('click', () => {
    const form = $('#invd-pm-add-cust-form');
    form.style.display = form.style.display === 'none' ? '' : 'none';
    if (form.style.display !== 'none') setTimeout(() => $('#invd-pm-cust-name')?.focus(), 40);
  });
  $('#invd-pm-add-cust-cancel')?.addEventListener('click', () => {
    $('#invd-pm-add-cust-form').style.display = 'none';
    $('#invd-pm-cust-name').value = '';
    $('#invd-pm-cust-phone').value = '';
  });
  $('#invd-pm-add-cust-save')?.addEventListener('click', async () => {
    const name  = $('#invd-pm-cust-name').value.trim();
    const phone = $('#invd-pm-cust-phone').value.trim();
    if (!name) { $('#invd-pm-cust-name').focus(); return; }
    const saveBtn = $('#invd-pm-add-cust-save');
    saveBtn.disabled = true;
    saveBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>';
    const r = await API.createCustomer({ name, phone });
    saveBtn.disabled = false;
    saveBtn.innerHTML = '<i class="fa fa-check"></i> Save Customer';
    if (r.status === 201 && r.body?.data) {
      const c = r.body.data;
      const sel = $('#invd-pm-customer');
      const opt = document.createElement('option');
      opt.value = c.id; opt.textContent = c.name; opt.selected = true;
      sel.appendChild(opt);
      $('#invd-pm-add-cust-form').style.display = 'none';
      $('#invd-pm-cust-name').value = '';
      $('#invd-pm-cust-phone').value = '';
      toast(`Customer "${c.name}" added`, 'success');
    } else {
      toast(r.body?.message || 'Failed to create customer', 'error');
    }
  });
});

// ── Invoice print (with optional letterhead) ──────────────────────────────
// ── Invoice preview modal (shows the invoice before/instead of printing) ──────
let _invpFitSc = 0.5, _invpZoom = 1, _invpPanX = 0, _invpPanY = 0;
let _invpCurrentInv = null;

function _invpApplyTransform() {
  const sc = $('#invp-scaler');
  if (!sc) return;
  sc.style.transform = `translate(${_invpPanX}px,${_invpPanY}px) scale(${_invpFitSc * _invpZoom})`;
}
function _invpUpdateZoomLabel() {
  const el = $('#invp-zoom-label');
  if (el) el.textContent = Math.round(_invpZoom * 100) + '%';
}
function _invpResetView() {
  const bg = $('#invp-bg');
  if (!bg) return;
  const w = bg.clientWidth, h = bg.clientHeight;
  if (!w || !h) return;
  _invpFitSc = Math.min((w - 40) / 794, (h - 40) / 1123);
  _invpZoom  = 1;
  _invpPanX  = (w - 794 * _invpFitSc) / 2;
  _invpPanY  = (h - 1123 * _invpFitSc) / 2;
  _invpApplyTransform();
  _invpUpdateZoomLabel();
}
function _invpZoomAt(nz, px, py) {
  const bg = $('#invp-bg');
  nz = Math.max(0.25, Math.min(6, nz));
  if (px === undefined) { px = (bg ? bg.clientWidth : 600) / 2; py = (bg ? bg.clientHeight : 500) / 2; }
  const r = nz / _invpZoom;
  _invpPanX = px - (px - _invpPanX) * r;
  _invpPanY = py - (py - _invpPanY) * r;
  _invpZoom = nz;
  _invpApplyTransform();
  _invpUpdateZoomLabel();
}

async function showInvoicePreviewModal(inv) {
  _invpCurrentInv = inv;
  const modal = $('#inv-preview-modal');
  if (!modal) { _invPrint(inv); return; }

  const title = document.getElementById('invp-title');
  const badge = document.getElementById('invp-badge');
  if (title) title.textContent = 'Invoice ' + (inv.invoice_number || '');
  if (badge) {
    const bgMap  = { paid: '#dcfce7', overdue: '#fee2e2', draft: '#f1f5f9', sent: '#dbeafe', cancelled: '#fee2e2' };
    const txtMap = { paid: '#15803d', overdue: '#dc2626', draft: '#64748b', sent: '#1d4ed8', cancelled: '#dc2626' };
    badge.textContent      = inv.status_label || inv.status || '';
    badge.style.background = bgMap[inv.status]  || '#f1f5f9';
    badge.style.color      = txtMap[inv.status] || '#64748b';
  }

  const ic    = _isetupGetCfg();
  const tpl   = _isetupResolveTpl(ic.template, ic.color);
  const mg    = { top: ic.mgTop, bot: ic.mgBot, left: ic.mgLeft, right: ic.mgRight };
  const frame = document.getElementById('invp-frame');

  // Show immediately without letterhead so the modal opens instantly
  if (frame) frame.srcdoc = _invBuildActualDoc(inv, tpl, mg, state.currency || '');
  modal.style.display = 'flex';
  setTimeout(_invpResetView, 50);

  // Load letterhead asynchronously and update the preview once ready
  if (!ic.lhEnabled) return;
  const lhFull = await _fetchLetterhead();
  if (lhFull && lhFull.canvas_json && frame) {
    const lhDataUrl = await window.electronAPI.renderCanvasToDataUrl(
      lhFull.canvas_json,
      lhFull.width  || 794,
      lhFull.height || 1123
    );
    if (lhDataUrl) frame.srcdoc = _invBuildActualDoc(inv, tpl, mg, state.currency || '', lhDataUrl);
  }
}

async function _invPrint(inv) {
  const ic     = _isetupGetCfg();
  const tpl    = _isetupResolveTpl(ic.template, ic.color);
  const mg     = { top: ic.mgTop, bot: ic.mgBot, left: ic.mgLeft, right: ic.mgRight };
  const lhFull = ic.lhEnabled ? await _fetchLetterhead() : null;
  let   lhDataUrl = null;
  if (lhFull && lhFull.canvas_json) {
    lhDataUrl = await window.electronAPI.renderCanvasToDataUrl(
      lhFull.canvas_json,
      lhFull.width  || 794,
      lhFull.height || 1123
    );
  }
  const html = _invBuildActualDoc(inv, tpl, mg, state.currency || '', lhDataUrl);
  await window.electronAPI.openInvoicePrint({
    html,
    number:      inv.invoice_number || '',
    status:      inv.status         || '',
    statusLabel: inv.status_label   || '',
  });
}

// ── Invoice form ──────────────────────────────────────────────────────────
let _invLineSeq = 0;

function _invAddLine(desc = '', qty = 1, price = 0, discType = 'pct', discValue = 0, taxType = 'pct', taxValue = 0) {
  const id  = ++_invLineSeq;
  const row = document.createElement('div');
  row.className        = 'qt-line-row';
  row.dataset.lineId   = id;
  row.dataset.discType = discType;

  const cur = state.currency || '¤';
  const s   = state.receiptSettings || {};
  const taxRules = Array.isArray(s.tax_rules)
    ? s.tax_rules.filter(r => parseFloat(r.value || 0) > 0)
    : [];

  // Build tax option list; pre-select rule that matches stored taxType+taxValue
  const taxOpts = taxRules.map((r, ri) => {
    const lbl = escHtml(r.name) + (r.type === 'flat'
      ? ' (' + escHtml(cur) + parseFloat(r.value).toFixed(2) + ')'
      : ' ' + parseFloat(r.value) + '%');
    const sel = r.type === taxType && String(r.value) === String(taxValue) ? ' selected' : '';
    return `<option value="${ri}"${sel}>${lbl}</option>`;
  }).join('');

  row.innerHTML = `
    <div class="qt-line-desc">
      <input type="text" class="qt-line-input qt-line-desc-input" placeholder="Description or search product…" value="${escHtml(desc)}" data-role="desc" data-lid="${id}">
    </div>
    <input type="number" class="qt-line-input qt-line-num"   value="${qty}" min="0.001" step="any" data-role="qty">
    <input type="number" class="qt-line-input qt-line-price" value="${price > 0 ? price.toFixed(2) : ''}" min="0" step="any" data-role="price" placeholder="0.00">
    <div class="qt-line-disc-wrap">
      <input type="number" class="qt-line-disc-inp${discValue > 0 ? ' has-val' : ''}"
        value="${discValue > 0 ? discValue : ''}" min="0" ${discType === 'pct' ? 'max="100"' : ''} step="any" data-role="disc" placeholder="0">
      <button class="qt-disc-toggle${discType === 'flat' ? ' is-flat' : ''}" data-role="disc-toggle" title="Toggle % / flat">${discType === 'flat' ? escHtml(cur) : '%'}</button>
    </div>
    <select class="qt-line-tax-sel${taxValue > 0 ? ' has-tax' : ''}" data-role="tax">
      <option value="">– None</option>
      ${taxOpts}
    </select>
    <div class="qt-line-total" id="inv-lt-${id}">0.00</div>
    <button class="qt-line-del" title="Remove"><i class="fa fa-xmark"></i></button>`;

  const descInp  = row.querySelector('.qt-line-desc-input');
  const priceInp = row.querySelector('[data-role="price"]');

  // ── Suggestion portal — appended to body to escape overflow:hidden containers ──
  const sug = document.createElement('div');
  sug.className = 'qt-product-suggest';
  // Override position to fixed so it escapes all scrollable/overflow containers
  // CSS class has display:none + position:absolute + right:0 — all must be overridden inline
  sug.style.cssText = 'position:fixed!important;z-index:9999;display:none;right:auto!important;';
  document.body.appendChild(sug);

  function _sugPosition() {
    const r = descInp.getBoundingClientRect();
    sug.style.top   = r.bottom + 2 + 'px';
    sug.style.left  = r.left + 'px';
    sug.style.width = r.width + 'px';
    sug.style.right = 'auto';
  }
  // Must set display:'block' not '' — empty string falls back to CSS class's display:none
  function _sugShow() { _sugPosition(); sug.style.display = 'block'; }
  function _sugHide() { sug.style.display = 'none'; sug.innerHTML = ''; }

  // Reposition on scroll (close is simpler and avoids stale coordinates)
  const _onScroll = () => _sugHide();
  window.addEventListener('scroll', _onScroll, { passive: true, capture: true });

  let sugTimer;

  // ── Full POS product-selection logic on suggestion click ─────────────────
  async function _invHandleSugClick(el) {
    _sugHide();
    const isProduct = el.dataset.type === 'product';

    if (!isProduct) {
      // Service: simple fill — no layers or warranty
      descInp.value  = el.dataset.name;
      priceInp.value = parseFloat(el.dataset.price || 0).toFixed(2);
      _invRecalc();
      priceInp.focus();
      return;
    }

    // Product: fetch full detail for layer-picker + warranty
    const res = await API.product(el.dataset.id);
    const p   = res.status === 200 ? (res.body?.data ?? res.body) : null;

    if (!p) {
      descInp.value  = el.dataset.name;
      priceInp.value = parseFloat(el.dataset.price || 0).toFixed(2);
      _invRecalc();
      return;
    }

    const layers    = p.layers || [];
    const inStock   = layers.filter(l => parseFloat(l.quantity_remaining) > 0);
    const stockMode = state.receiptSettings?.stock_selection_mode ?? 'fifo';
    let chosenPrice;

    // ── Stock / batch picker (mirrors POS handleProductClick) ────────────
    if (stockMode === 'choose' && layers.length > 1) {
      const pickable = inStock.length > 0 ? inStock : layers;
      const layer = await posPickStockLayer(p, pickable);
      if (!layer) return; // cancelled
      chosenPrice = parseFloat(layer.unit_sell_price);
    } else if (posLayersDifferInPrice(layers)) {
      const pickable = inStock.length > 0 ? inStock : layers;
      if (pickable.length > 1) {
        const layer = await posPickStockLayer(p, pickable);
        if (!layer) return; // cancelled
        chosenPrice = parseFloat(layer.unit_sell_price);
      } else {
        chosenPrice = parseFloat(pickable[0]?.unit_sell_price ?? p.unit_sell_price ?? 0);
      }
    } else if (inStock.length > 0) {
      chosenPrice = parseFloat(inStock[0].unit_sell_price);
    } else if (layers.length > 0) {
      chosenPrice = parseFloat(layers[0].unit_sell_price);
    } else {
      chosenPrice = parseFloat(p.discounted_sell_price ?? p.unit_sell_price ?? el.dataset.price ?? 0);
    }

    // ── Warranty (mirrors POS handleProductClick) ─────────────────────────
    if (p.has_warranty) {
      if (p.warranty_duration) {
        const wty = _resolveWarrantyFromDuration(p.warranty_duration);
        row.dataset.warrantyType = wty.type;
        row.dataset.warrantyDate = wty.date ?? '';
      } else {
        const wty = await _askWarranty(p.name);
        if (wty === null) return; // cancelled
        row.dataset.warrantyType = wty.type;
        row.dataset.warrantyDate = wty.date ?? '';
      }
    }

    descInp.value  = p.name;
    priceInp.value = chosenPrice.toFixed(2);
    _invRecalc();
    priceInp.focus();
  }

  // ── Typeahead input listener ──────────────────────────────────────────────
  descInp.addEventListener('input', () => {
    clearTimeout(sugTimer);
    const q = descInp.value.trim();
    if (q.length < 2) { _sugHide(); return; }
    sugTimer = setTimeout(async () => {
      const [prodRes, svcRes] = await Promise.all([
        API.productSearch(q, 6),
        API.serviceMgmtCatalog(q),
      ]);
      const products = prodRes.body?.data || [];
      const services = svcRes.body?.data  || [];
      if (!products.length && !services.length) { _sugHide(); return; }
      sug.innerHTML = [
        ...products.map(p => `<div class="qt-suggest-item" data-type="product" data-id="${p.id}" data-name="${escHtml(p.name)}" data-price="${p.unit_sell_price ?? 0}">
          <i class="fa fa-box" style="opacity:.45;margin-right:5px;font-size:11px"></i>${escHtml(p.name)}<span class="qt-suggest-sku">${p.sku ? escHtml(p.sku) : ''}</span>
        </div>`),
        ...services.map(s => `<div class="qt-suggest-item" data-type="service" data-id="${s.id}" data-name="${escHtml(s.name)}" data-price="${s.price ?? 0}">
          <i class="fa fa-screwdriver-wrench" style="color:#10b981;margin-right:5px;font-size:11px"></i>${escHtml(s.name)}${s.duration_label ? `<span class="qt-suggest-sku">${escHtml(s.duration_label)}</span>` : ''}
        </div>`),
      ].join('');
      _sugShow();
      sug.querySelectorAll('.qt-suggest-item').forEach(el => {
        el.addEventListener('mousedown', e => {
          e.preventDefault(); // prevent blur firing before mousedown resolves
          _invHandleSugClick(el);
        });
      });
    }, 200);
  });

  descInp.addEventListener('blur', () => setTimeout(_sugHide, 150));

  row.querySelector('[data-role="qty"]').addEventListener('input', _invRecalc);
  priceInp.addEventListener('input', _invRecalc);

  // Discount value input
  const discInp = row.querySelector('[data-role="disc"]');
  discInp.addEventListener('input', () => {
    discInp.classList.toggle('has-val', (parseFloat(discInp.value) || 0) > 0);
    _invRecalc();
  });

  // Discount type toggle: % ↔ flat
  row.querySelector('[data-role="disc-toggle"]').addEventListener('click', () => {
    const isFlat = row.dataset.discType === 'flat';
    row.dataset.discType = isFlat ? 'pct' : 'flat';
    const tog = row.querySelector('[data-role="disc-toggle"]');
    tog.textContent = isFlat ? '%' : escHtml(state.currency || '¤');
    tog.classList.toggle('is-flat', !isFlat);
    discInp.removeAttribute('max');
    if (!isFlat) discInp.setAttribute('max', '100');
    _invRecalc();
  });

  // Tax rule select — read chosen rule from settings, store type+value on row dataset
  const taxSel = row.querySelector('[data-role="tax"]');
  // Seed initial dataset from params
  if (taxValue > 0) {
    row.dataset.taxType  = taxType;
    row.dataset.taxValue = taxValue;
  }
  taxSel.addEventListener('change', () => {
    const rules = Array.isArray(state.receiptSettings?.tax_rules)
      ? state.receiptSettings.tax_rules.filter(r => parseFloat(r.value || 0) > 0)
      : [];
    const ri = taxSel.value === '' ? -1 : parseInt(taxSel.value);
    const rule = ri >= 0 && rules[ri] ? rules[ri] : null;
    taxSel.classList.toggle('has-tax', !!rule);
    // Normalize 'percentage' (POS settings format) → 'pct'
    const ruleType = rule ? (rule.type === 'percentage' ? 'pct' : rule.type) : 'pct';
    row.dataset.taxType  = ruleType;
    row.dataset.taxValue = rule ? rule.value : 0;
    _invRecalc();
  });

  row.querySelector('.qt-line-del').addEventListener('click', () => {
    _sugHide();
    window.removeEventListener('scroll', _onScroll, { capture: true });
    sug.remove();
    row.remove();
    _invRecalc();
  });

  $('#sinv-items-body').appendChild(row);
  if (!desc) setTimeout(() => descInp.focus(), 40);
  _invRecalc();
}

function _invRecalc() {
  let sub = 0;
  $$('#sinv-items-body .qt-line-row').forEach(row => {
    const qty      = parseFloat(row.querySelector('[data-role="qty"]')?.value)   || 0;
    const price    = parseFloat(row.querySelector('[data-role="price"]')?.value) || 0;
    const discType = row.dataset.discType || 'pct';
    const discVal  = parseFloat(row.querySelector('[data-role="disc"]')?.value)  || 0;
    const taxType  = row.dataset.taxType  || 'pct';
    const taxValue = parseFloat(row.dataset.taxValue) || 0;

    const gross   = qty * price;
    const discAmt = discType === 'flat'
      ? Math.min(discVal, gross)
      : (gross * discVal / 100);
    const net     = Math.max(0, gross - discAmt);
    const taxAmt  = taxType === 'flat' ? taxValue : (net * taxValue / 100);
    const lt      = Math.round((net + taxAmt) * 100) / 100;

    const ltEl = document.getElementById(`inv-lt-${row.dataset.lineId}`);
    if (ltEl) ltEl.textContent = lt.toFixed(2);
    sub += lt;
  });
  const disc = parseFloat($('#sinv-f-discount').value) || 0;
  const tax  = parseFloat($('#sinv-f-tax').value)      || 0;
  $('#sinv-subtotal').textContent    = sub.toFixed(2);
  $('#sinv-grand-total').textContent = Math.max(0, sub - disc + tax).toFixed(2);
}

async function _invOpenForm(existing, prefill = null) {
  _inv.editingId = existing?.id ?? null;
  _invLineSeq    = 0;
  _invShowView('form');
  $('#sinv-form-title').textContent    = existing ? `Edit ${existing.invoice_number}` : 'New Invoice';
  $('#sinv-form-alert').style.display  = 'none';
  $('#sinv-items-body').innerHTML      = '';
  $('#sinv-f-discount').value          = '';
  $('#sinv-f-tax').value               = '';
  $('#sinv-f-notes').value             = '';
  $('#sinv-f-ref').value               = '';
  $('#sinv-subtotal').textContent      = '0.00';
  $('#sinv-grand-total').textContent   = '0.00';
  $('#sinv-f-date').value              = existing?.issue_date || new Date().toISOString().slice(0, 10);
  $('#sinv-f-due').value               = existing?.due_date   || '';
  $('#sinv-f-payment').value           = existing?.payment_method || '';

  if (existing?.discount_amount) $('#sinv-f-discount').value = existing.discount_amount;
  if (existing?.tax_amount)      $('#sinv-f-tax').value      = existing.tax_amount;
  if (existing?.notes)           $('#sinv-f-notes').value    = existing.notes;
  if (existing?.reference)       $('#sinv-f-ref').value      = existing.reference;

  // Populate customer dropdown
  const sel = $('#sinv-f-customer');
  sel.innerHTML = '<option value="">— Walk-in —</option>';
  const custRes = await API.customers('', 1);
  if (custRes.status === 200) {
    (custRes.body?.data || []).forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id; opt.textContent = c.name;
      if (existing?.customer_id === c.id || (!existing && prefill?.customerId == c.id)) opt.selected = true;
      sel.appendChild(opt);
    });
  }

  if (existing?.items?.length) {
    existing.items.forEach(i => _invAddLine(
      i.description, i.quantity, i.unit_price,
      i.discount_type || 'pct', i.discount_value || 0,
      i.tax_type || 'pct', i.tax_pct || 0,
    ));
  } else if (prefill?.items?.length) {
    prefill.items.forEach(i => _invAddLine(
      i.description, i.quantity, i.unit_price,
      i.discount_type || 'pct', i.discount_value || 0,
      i.tax_type || 'pct', i.tax_pct || 0,
    ));
  }
  _invRecalc();
}


$('#sinv-add-line').addEventListener('click', () => _invAddLine());
$('#sinv-f-discount').addEventListener('input', _invRecalc);
$('#sinv-f-tax').addEventListener('input', _invRecalc);

$('#sinv-form-save').addEventListener('click', async () => {
  const btn   = $('#sinv-form-save');
  const lines = [];
  $$('#sinv-items-body .qt-line-row').forEach(row => {
    const qty      = parseFloat(row.querySelector('[data-role="qty"]').value)   || 0;
    const price    = parseFloat(row.querySelector('[data-role="price"]').value) || 0;
    const discType = row.dataset.discType || 'pct';
    const discVal  = parseFloat(row.querySelector('[data-role="disc"]')?.value) || 0;
    const taxType  = row.dataset.taxType  || 'pct';
    const taxValue = parseFloat(row.dataset.taxValue) || 0;
    let   desc  = (row.querySelector('[data-role="desc"]')?.value || '').trim();
    // Append warranty info to description if captured during product selection
    if (row.dataset.warrantyType === 'lifetime') {
      desc += (desc ? ' ' : '') + '(Warranty: Lifetime)';
    } else if (row.dataset.warrantyType === 'date' && row.dataset.warrantyDate) {
      desc += (desc ? ' ' : '') + `(Warranty expires: ${row.dataset.warrantyDate})`;
    }
    if (qty > 0 || price > 0 || desc) {
      lines.push({
        item_type:      'custom',
        description:    desc,
        quantity:       qty,
        unit_price:     price,
        discount_type:  discType,
        discount_value: discVal,
        tax_pct:        taxValue,
        tax_type:       taxType,
      });
    }
  });

  if (!lines.length) {
    $('#sinv-form-alert').textContent = 'Add at least one line item.';
    $('#sinv-form-alert').style.display = '';
    return;
  }

  $('#sinv-form-alert').style.display = 'none';
  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Saving…';

  const body = {
    customer_id:     parseInt($('#sinv-f-customer').value) || null,
    reference:       $('#sinv-f-ref').value.trim()    || null,
    issue_date:      $('#sinv-f-date').value,
    due_date:        $('#sinv-f-due').value            || null,
    notes:           $('#sinv-f-notes').value.trim()   || null,
    payment_method:  $('#sinv-f-payment').value        || null,
    discount_amount: parseFloat($('#sinv-f-discount').value) || 0,
    tax_amount:      parseFloat($('#sinv-f-tax').value)      || 0,
    items:           lines,
  };

  const res = _inv.editingId
    ? await API.updateInvoice(_inv.editingId, body)
    : await API.createInvoice(body);

  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-floppy-disk"></i> Save Invoice';

  if (res.status === 200 || res.status === 201) {
    const saved = res.body?.data;
    toast(res.status === 201 ? `Invoice ${saved.invoice_number} created` : 'Invoice updated', 'success');
    _inv.activeId = saved.id;
    _invOpenDetail(saved.id);
  } else {
    $('#sinv-form-alert').textContent = res.body?.message || 'Failed to save invoice.';
    $('#sinv-form-alert').style.display = '';
  }
});

$('#sinv-form-back').addEventListener('click', () => {
  if (_inv.activeId) _invOpenDetail(_inv.activeId); else _invShowView('list');
});
$('#sinv-form-cancel').addEventListener('click', () => {
  if (_inv.activeId) _invOpenDetail(_inv.activeId); else _invShowView('list');
});
$('#sinv-detail-back').addEventListener('click', () => { _inv.activeId = null; loadInvoicesList(); });

$('#sinv-search').addEventListener('input', () => {
  _inv.search = $('#sinv-search').value.trim();
  clearTimeout(_invSearchTimer);
  _invSearchTimer = setTimeout(loadInvoicesList, 280);
});

$$('.sinv-chip').forEach(btn => {
  btn.addEventListener('click', () => {
    $$('.sinv-chip').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    _inv.status = btn.dataset.ist;
    loadInvoicesList();
  });
});

$('#sinv-new-btn').addEventListener('click', () => _invOpenForm(null));
