// Call at the top of any modal close handler that may have been opened from the wizard.
// If billingActive is true the wizard was waiting — clear the flag and reopen.
// Returns true when the wizard was resumed so the caller can skip its normal teardown if needed.
function _bwzCheckResume() {
  if (!_bwz.billingActive) return false;
  const next = _bwz.billingNextStep;
  _bwz.billingActive = false;
  _bwzResumeWizard(next);
  return true;
}

function _bwzResumeWizard(nextStep) {
  if (nextStep === null) { _bwzClose(); return; }
  // Products sub-steps: 'ps:1', 'ps:2'
  if (typeof nextStep === 'string' && nextStep.startsWith('ps:')) {
    const n = parseInt(nextStep.split(':')[1]);
    _bwzShowProductsPanel(); // makes products panel visible, sets step indicators + loads existing
    _bwzPsGoto(n);           // override to the correct sub-step
    _bwzComeForward();
    _bwzShowResumeBanner();
    return;
  }
  // POS sub-steps: 'pos:1', 'pos:2', 'pos:3', 'pos:4'
  if (typeof nextStep === 'string' && nextStep.startsWith('pos:')) {
    const n = parseInt(nextStep.split(':')[1]);
    _bwzShowPosPanel(); // makes POS panel visible, sets step indicators
    _bwzPosGoto(n);     // override to the correct sub-step
    _bwzComeForward();
    _bwzShowResumeBanner();
    return;
  }
  // System Configuration sub-steps: 'sc:1', 'sc:2', 'sc:3', 'sc:4'
  if (typeof nextStep === 'string' && nextStep.startsWith('sc:')) {
    const n = parseInt(nextStep.split(':')[1]);
    _bwzShowSysConfigPanel(); // makes sysconfig panel visible, sets step indicators
    _bwzScGoto(n);            // override to the correct sub-step
    _bwzComeForward();
    _bwzShowResumeBanner();
    return;
  }
  // Billing panel resume — refresh counts and stay on billing panel
  _bwzShowBillingPanel(); // ensures panel is visible with correct step state
  _bwzComeForward();
  _bwzShowResumeBanner();
}

// Brief "resuming" banner — fades out after 2 s (F2)
function _bwzShowResumeBanner() {
  const el = $('#bwz-resume-banner');
  if (!el) return;
  el.style.display = '';
  el.classList.remove('bwz-resume-out');
  clearTimeout(_bwz._resumeTimer);
  _bwz._resumeTimer = setTimeout(() => {
    el.classList.add('bwz-resume-out');
    setTimeout(() => { el.style.display = 'none'; el.classList.remove('bwz-resume-out'); }, 400);
  }, 2000);
}

