// SKU generate
$('#prod-sku-gen')?.addEventListener('click', _prodGenerateSku);

// Batch: add row
$('#prod-batch-add-btn')?.addEventListener('click', () => {
  _prod.batches.push({ qty: '', cost: '', selling: '', wholesale: '' });
  _prodBatchRender();
});

