async function openProductDetail(productId, productName) {
  _prodActiveId   = productId;
  _prodActiveData = null;
  $('#inv-list-view').style.display   = 'none';
  $('#inv-detail-view').style.display = 'flex';
  $('#inv-detail-breadcrumb').textContent = productName || 'Product Detail';

  // Reset to Overview tab
  $$('#inv-tabs .inv-tab').forEach(t => t.classList.remove('active'));
  $('#inv-tabs .inv-tab[data-tab="overview"]').classList.add('active');
  $$('.inv-tab-pane').forEach(p => p.classList.remove('active'));
  $('#inv-pane-overview').classList.add('active');

  // Loading state in hero
  $('#inv-hero-name').textContent = productName || '…';
  $('#inv-hero-meta').innerHTML   = '<i class="fa fa-spinner fa-spin"></i>';
  $('#inv-hero-badges').innerHTML = '';
  $('#inv-hero-img').innerHTML    = '<div class="inv-thumb-ph inv-thumb-lg"><i class="fa fa-box"></i></div>';
  $('#inv-tab-delivery').style.display = 'none';
  ['overview','pricing','stock','images','variants','delivery'].forEach(t => {
    $(`#inv-pane-${t}`).innerHTML = `<div class="inv-pane-loading"><i class="fa fa-spinner fa-spin"></i> Loading…</div>`;
  });

  // Fetch product and stock history in parallel
  const [res, histRes] = await Promise.all([
    API.product(productId),
    API.productStockHistory(productId),
  ]);
  const p = res.body?.data || res.body || null;
  if (!p || res.status !== 200) {
    $('#inv-hero-meta').innerHTML = '<span style="color:#e74c3c">Failed to load product</span>';
    return;
  }

  const stockHistory = histRes.status === 200 ? (histRes.body?.data || []) : [];
  renderProductDetail(p, stockHistory);
}

function renderProductDetail(p, stockHistory = []) {
  _prodActiveData = p;
  // ── Hero ──
  const images = p.images || p.product_images || (p.image ? [{ url: p.image }] : []);
  const firstImg = images[0]?.url || images[0]?.image_url || p.image || null;
  $('#inv-hero-img').innerHTML = firstImg
    ? `<img src="${firstImg}" class="inv-hero-img-el" alt="${escHtml(p.name)}">`
    : `<div class="inv-thumb-ph inv-thumb-lg"><i class="fa fa-box"></i></div>`;

  $('#inv-hero-name').textContent = p.name || '—';

  const metaParts = [];
  if (p.sku)       metaParts.push(`<span><i class="fa fa-barcode"></i> ${escHtml(p.sku)}</span>`);
  if (p.barcode)   metaParts.push(`<span><i class="fa fa-qrcode"></i> ${escHtml(p.barcode)}</span>`);
  if (p.category?.name) metaParts.push(`<span><i class="fa fa-tag"></i> ${escHtml(p.category.name)}</span>`);
  $('#inv-hero-meta').innerHTML = metaParts.join('<span class="inv-sep">·</span>');

  const stock = p.stock_quantity;
  const badges = [];
  if (p.is_active === false || p.status === 'inactive') badges.push(`<span class="inv-badge inv-badge-gray">Inactive</span>`);
  else badges.push(`<span class="inv-badge inv-badge-green">Active</span>`);
  if (stock != null) {
    if (stock <= 0) badges.push(`<span class="inv-badge inv-badge-red">Out of stock</span>`);
    else if (stock <= 5) badges.push(`<span class="inv-badge inv-badge-amber">Low stock</span>`);
    else badges.push(`<span class="inv-badge inv-badge-blue">In stock</span>`);
  }
  if (p.has_variants || p.variants?.length) badges.push(`<span class="inv-badge inv-badge-purple">Has variants</span>`);
  if (p.has_warranty)       badges.push(`<span class="inv-badge inv-badge-blue"><i class="fa fa-shield-halved"></i> Warranty</span>`);
  if (p.track_expiry)       badges.push(`<span class="inv-badge inv-badge-amber"><i class="fa fa-calendar-xmark"></i> Expiry</span>`);
  if (p.courier_delivery)   badges.push(`<span class="inv-badge inv-badge-purple"><i class="fa fa-truck"></i> Courier</span>`);
  if (p.loyalty_redeemable) badges.push(`<span class="inv-badge inv-badge-green"><i class="fa fa-star"></i> Loyalty</span>`);
  if (p.is_rental)          badges.push(`<span class="inv-badge inv-badge-blue"><i class="fa fa-key"></i> Rental</span>`);
  $('#inv-hero-badges').innerHTML = badges.join('');

  // ── Overview tab ──
  const statusLabel = (p.is_active === false) ? 'Inactive' : 'Active';
  const statusClass = (p.is_active === false) ? 'inv-badge-gray' : 'inv-badge-green';
  const typeLabel   = p.is_bundle ? 'Bundle' : 'Single';

  const categories = p.category
    ? [p.category]
    : (Array.isArray(p.category_ids) && p.category_ids.length ? p.category_ids.map(id => ({ id, name: String(id) })) : []);
  const catChips = categories.length
    ? categories.map(c => `<span class="inv-detail-chip">${escHtml(c.name || String(c))}</span>`).join('')
    : '<span class="inv-detail-none">—</span>';

  const brandName = p.brand?.name || p.brand_name || p.brand || null;
  const brandChip = brandName
    ? `<span class="inv-detail-chip">${escHtml(brandName)}</span>`
    : '<span class="inv-detail-none">—</span>';

  const unitName = p.unit_name || p.unit?.name || p.unit || null;

  const detailCells = [
    { label: 'SKU',        value: p.sku        ? escHtml(p.sku)      : '<span class="inv-detail-none">—</span>' },
    { label: 'STATUS',     value: `<span class="inv-badge ${statusClass}">${statusLabel}</span>` },
    { label: 'TYPE',       value: `<strong>${typeLabel}</strong>` },
    { label: 'CATEGORIES', value: catChips },
    { label: 'BRANDS',     value: brandChip },
    { label: 'UNIT',       value: unitName ? escHtml(unitName) : '<span class="inv-detail-none">—</span>' },
  ];

  const descHtml = (p.description || p.short_description)
    ? `<div class="inv-section" style="margin-top:14px">
        <div class="inv-section-title"><i class="fa fa-align-left"></i> Description</div>
        <div class="inv-desc-body">${escHtml(String(p.description || p.short_description))}</div>
       </div>`
    : '';

  const metaHtml = (p.created_at || p.updated_at)
    ? `<div class="inv-detail-meta-row">
        ${p.created_at ? `<span><i class="fa fa-calendar-plus"></i> Created ${new Date(p.created_at).toLocaleDateString()}</span>` : ''}
        ${p.updated_at ? `<span><i class="fa fa-calendar-check"></i> Updated ${new Date(p.updated_at).toLocaleDateString()}</span>` : ''}
       </div>`
    : '';

  $('#inv-pane-overview').innerHTML = `
    <div class="inv-chart-block">
      <div class="inv-chart-header">
        <div class="inv-chart-title"><i class="fa fa-chart-bar"></i> Units sold</div>
        <div class="inv-chart-periods">
          <button class="inv-chart-period" data-period="daily">Daily</button>
          <button class="inv-chart-period active" data-period="weekly">Weekly</button>
          <button class="inv-chart-period" data-period="monthly">Monthly</button>
        </div>
      </div>
      <div id="inv-chart-container" class="inv-chart-container"></div>
    </div>
    <div class="inv-section" style="margin-top:14px">
      <div class="inv-section-title"><i class="fa fa-circle-info"></i> Details</div>
      <div class="inv-detail-grid">
        ${detailCells.map(c => `
          <div class="inv-detail-cell">
            <div class="inv-detail-cell-label">${c.label}</div>
            <div class="inv-detail-cell-value">${c.value}</div>
          </div>`).join('')}
      </div>
    </div>
    ${descHtml}
    ${metaHtml}`;

  // Load chart & wire period buttons
  loadAndRenderChart(p.id, 'weekly');
  $('#inv-pane-overview').addEventListener('click', e => {
    const btn = e.target.closest('.inv-chart-period');
    if (btn) loadAndRenderChart(p.id, btn.dataset.period);
  });

  // ── Pricing tab ──
  // unit_price = product-level selling price (from /online/products/{id} show endpoint)
  // unit_sell_price = resolved sell price from stock layers (from catalog card)
  const sellingPrice   = p.unit_price != null ? parseFloat(p.unit_price) : (p.unit_sell_price != null ? parseFloat(p.unit_sell_price) : null);
  const costPrice      = p.cost_price != null ? parseFloat(p.cost_price) : null;
  const wholesalePrice = p.wholesale_price != null ? parseFloat(p.wholesale_price) : null;

  const profit     = (sellingPrice != null && costPrice != null) ? (sellingPrice - costPrice) : null;
  const marginPct  = (profit != null && costPrice > 0) ? ((profit / costPrice) * 100).toFixed(1) : null;

  const cur = state.currency ? ' ' + state.currency : '';

  const _fmt = v => v != null ? parseFloat(v).toFixed(2) + cur : null;

  const priceRows = [
    ['Cost Price',       costPrice    != null ? `<strong style="font-size:16px">${_fmt(costPrice)}</strong>` : '<span style="color:var(--text-muted)">—</span>'],
    ['Selling Price',    sellingPrice != null ? `<strong style="font-size:18px;color:var(--accent)">${_fmt(sellingPrice)}</strong>` : '<span style="color:var(--text-muted)">—</span>'],
    ['Wholesale Price',  wholesalePrice != null ? `<span style="color:#d97706;font-weight:600"><i class="fa fa-tags"></i> ${_fmt(wholesalePrice)}</span>` : '<span style="color:var(--text-muted)">—</span>'],
    ['Profit',           profit != null
      ? `<span style="font-weight:700;color:${profit >= 0 ? '#16a34a' : '#dc2626'}">${profit >= 0 ? '+' : ''}${_fmt(profit)}${marginPct != null ? ` <span style="font-size:11px;opacity:.8;">(${marginPct >= 0 ? '+' : ''}${marginPct}% margin)</span>` : ''}</span>`
      : '<span style="color:var(--text-muted)">— set cost &amp; selling price</span>'],
  ];

  $('#inv-pane-pricing').innerHTML = `
    <div class="inv-section">
      <div class="inv-section-title"><i class="fa fa-tag"></i> Pricing</div>
      <table class="inv-detail-table">
        ${priceRows.map(([label, val]) => `
          <tr><td class="inv-dt-label">${label}</td><td class="inv-dt-val">${val}</td></tr>`).join('')}
      </table>
    </div>`;

  // ── Stock tab ──
  const locations      = p.stock_locations || p.warehouses || [];
  const totalReceived  = stockHistory.reduce((s, h) => s + parseFloat(h.quantity_received  || 0), 0);
  const grnRemaining   = stockHistory.reduce((s, h) => s + parseFloat(h.quantity_remaining || 0), 0);
  // Use stock_quantity (the canonical denormalized column) to match POS grid
  const displayStock   = stock ?? '—';
  const stockRows = [
    ['Available Stock', displayStock !== '—' ? `<strong style="font-size:15px;color:var(--accent)">${Number(displayStock) % 1 === 0 ? Number(displayStock) : Number(displayStock).toFixed(3)}</strong>` : '—'],
    ['Low Stock Alert', p.low_stock_threshold ?? p.alert_quantity ?? '—'],
    ['Manage Stock',    p.manage_stock != null ? (p.manage_stock ? 'Yes' : 'No') : '—'],
    ['Allow Backorder', p.allow_backorder != null ? (p.allow_backorder ? 'Yes' : 'No') : '—'],
    ['Weight',          p.weight ? `${p.weight} ${p.weight_unit || ''}`.trim() : null],
    ['Dimensions',      (p.length || p.width || p.height) ? `${p.length||0} × ${p.width||0} × ${p.height||0}` : null],
  ].filter(([, v]) => v != null);

  const locHtml = locations.length ? `
    <div class="inv-section" style="margin-top:16px">
      <div class="inv-section-title"><i class="fa fa-warehouse"></i> Stock Locations</div>
      <table class="inv-detail-table">
        <thead><tr><th class="inv-dt-label">Location</th><th class="inv-dt-val">Qty</th></tr></thead>
        <tbody>${locations.map(l => `<tr><td class="inv-dt-label">${escHtml(l.name||l.warehouse_name||'—')}</td><td class="inv-dt-val">${l.quantity??l.stock??'—'}</td></tr>`).join('')}</tbody>
      </table>
    </div>` : '';
  const _stockNum    = stock != null ? Number(stock) : null;
  const _threshold   = p.low_stock_threshold ?? p.alert_quantity ?? 5;
  const _stockColor  = _stockNum == null ? '' : _stockNum <= 0 ? ' inv-stock-kpi--red' : _stockNum <= _threshold ? ' inv-stock-kpi--amber' : ' inv-stock-kpi--green';
  const _stockDisp   = _stockNum != null ? (_stockNum % 1 === 0 ? _stockNum : _stockNum.toFixed(3)) : '—';
  const stockSummaryHtml = `
    <div class="inv-stock-summary">
      <div class="inv-stock-kpi${_stockColor}">
        <div class="inv-stock-kpi-val">${_stockDisp}</div>
        <div class="inv-stock-kpi-label">Available Stock</div>
      </div>
      <div class="inv-stock-kpi inv-stock-kpi--blue">
        <div class="inv-stock-kpi-val">${totalReceived % 1 === 0 ? totalReceived : totalReceived.toFixed(3)}</div>
        <div class="inv-stock-kpi-label">Total Received (GRN)</div>
      </div>
      <div class="inv-stock-kpi inv-stock-kpi--gray">
        <div class="inv-stock-kpi-val">${grnRemaining % 1 === 0 ? grnRemaining : grnRemaining.toFixed(3)}</div>
        <div class="inv-stock-kpi-label">GRN Remaining</div>
      </div>
    </div>`;

  const grnHistHtml = (() => {
    if (!stockHistory.length) {
      return `<div class="inv-section" style="margin-top:16px">
        <div class="inv-section-title"><i class="fa fa-truck-ramp-box"></i> Stock Receive History</div>
        <div class="inv-pane-empty" style="padding:20px 0"><i class="fa fa-inbox"></i><p>No GRN records found</p></div>
      </div>`;
    }
    const cards = stockHistory.map((h, idx) => {
      const src     = h.source_type || (h.grn_number ? 'grn' : 'opening');
      const date    = h.received_at ? new Date(h.received_at).toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' }) : '—';
      const qtyIn   = parseFloat(h.quantity_received || 0);
      const qtyLeft = parseFloat(h.quantity_remaining || 0);
      const pct     = qtyIn > 0 ? Math.max(0, Math.min(100, (qtyLeft / qtyIn) * 100)) : 0;
      const costVal   = h.unit_cost != null ? parseFloat(h.unit_cost).toFixed(2) : '';
      const sellPrice = h.selling_unit_price != null ? parseFloat(h.selling_unit_price).toFixed(2) : '';
      const wsPrice   = h.wholesale_unit_price != null ? parseFloat(h.wholesale_unit_price).toFixed(2) : '';

      const qtyStatusCls = qtyLeft <= 0 ? 'srh-qty-depleted' : qtyLeft < qtyIn ? 'srh-qty-partial' : 'srh-qty-full';
      const qtyLabel     = qtyLeft <= 0 ? 'Depleted' : qtyLeft < qtyIn ? 'Partially used' : 'Full';
      const barCls       = qtyLeft <= 0 ? 'srh-bar-depleted' : qtyLeft < qtyIn ? 'srh-bar-partial' : 'srh-bar-full';

      // ── Source header ──
      let badgeHtml, refHtml;
      if (src === 'opening') {
        badgeHtml = `<span class="inv-src-badge inv-src-opening"><i class="fa fa-box-open"></i> Opening Stock</span>`;
        refHtml   = '';
      } else if (src === 'po') {
        badgeHtml = `<span class="inv-src-badge inv-src-po"><i class="fa fa-file-invoice"></i> Purchase Order</span>`;
        refHtml   = [
          h.po_number    ? `<span class="srh-ref-chip srh-ref-po"><i class="fa fa-file-invoice"></i> ${escHtml(h.po_number)}</span>` : '',
          h.grn_number   ? `<span class="srh-ref-chip srh-ref-grn"><i class="fa fa-truck-ramp-box"></i> ${escHtml(h.grn_number)}</span>` : '',
          h.supplier_name? `<span class="srh-ref-chip srh-ref-sup"><i class="fa fa-building-user"></i> ${escHtml(h.supplier_name)}</span>` : '',
        ].filter(Boolean).join('');
      } else if (src === 'transfer') {
        badgeHtml = `<span class="inv-src-badge inv-src-transfer"><i class="fa fa-right-left"></i> Stock Transfer</span>`;
        refHtml   = [
          h.transfer_number     ? `<span class="srh-ref-chip srh-ref-grn"><i class="fa fa-hashtag"></i> ${escHtml(h.transfer_number)}</span>` : '',
          h.from_branch_name    ? `<span class="srh-ref-chip srh-ref-ref"><i class="fa fa-right-from-bracket"></i> from ${escHtml(h.from_branch_name)}</span>` : '',
          h.transferred_by_name ? `<span class="srh-ref-chip srh-ref-sup"><i class="fa fa-user"></i> ${escHtml(h.transferred_by_name)}</span>` : '',
        ].filter(Boolean).join('');
      } else {
        badgeHtml = `<span class="inv-src-badge inv-src-grn"><i class="fa fa-truck-ramp-box"></i> Goods Receive</span>`;
        refHtml   = [
          h.grn_number    ? `<span class="srh-ref-chip srh-ref-grn"><i class="fa fa-hashtag"></i> ${escHtml(h.grn_number)}</span>` : '',
          h.grn_reference ? `<span class="srh-ref-chip srh-ref-ref"><i class="fa fa-tag"></i> ${escHtml(h.grn_reference)}</span>` : '',
          h.supplier_name ? `<span class="srh-ref-chip srh-ref-sup"><i class="fa fa-building-user"></i> ${escHtml(h.supplier_name)}</span>` : '',
        ].filter(Boolean).join('');
      }

      const batchChip = h.batch_sku
        ? `<span class="srh-batch-chip"><i class="fa fa-barcode"></i> ${escHtml(h.batch_sku)}</span>` : '';

      const qtyDisp = `${qtyLeft % 1 === 0 ? qtyLeft : qtyLeft.toFixed(2)} / ${qtyIn % 1 === 0 ? qtyIn : qtyIn.toFixed(2)}`;
      return `
      <div class="srh-row">
        <div class="srh-row-info">
          ${badgeHtml}
          ${refHtml}
          ${batchChip}
          <span class="srh-qty-pill ${qtyStatusCls}">
            <span class="srh-qty-mini-bar"><span class="srh-qty-mini-fill ${barCls}" style="width:${pct.toFixed(1)}%"></span></span>
            ${qtyDisp}
          </span>
          <span class="srh-date"><i class="fa fa-calendar-day"></i> ${date}</span>
        </div>
        <div class="srh-row-prices">
          <div class="srh-inline-field">
            <span class="srh-inline-label">Cost</span>
            <div class="srh-price-input-wrap">
              <input type="number" class="inv-layer-cost-input srh-price-input" data-layer-id="${h.id}"
                value="${costVal}" min="0" step="0.01" placeholder="0.00">
              <button class="inv-layer-cost-save srh-price-btn" data-layer-id="${h.id}" title="Save cost price"><i class="fa fa-check"></i></button>
            </div>
            <span class="inv-layer-cost-status srh-price-status" data-layer-id="${h.id}"></span>
          </div>
          <div class="srh-inline-field srh-inline-field--sell">
            <span class="srh-inline-label">Selling</span>
            <div class="srh-price-input-wrap">
              <input type="number" class="inv-layer-price-input srh-price-input" data-layer-id="${h.id}"
                value="${sellPrice}" min="0" step="0.01" placeholder="0.00">
              <button class="inv-layer-price-save srh-price-btn srh-price-btn--sell" data-layer-id="${h.id}" title="Save selling price"><i class="fa fa-check"></i></button>
            </div>
            <span class="inv-layer-price-status srh-price-status" data-layer-id="${h.id}"></span>
          </div>
          <div class="srh-inline-field srh-inline-field--ws">
            <span class="srh-inline-label">Wholesale</span>
            <div class="srh-price-input-wrap">
              <input type="number" class="inv-layer-ws-input srh-price-input" data-layer-id="${h.id}"
                value="${wsPrice}" min="0" step="0.01" placeholder="0.00">
              <button class="inv-layer-ws-save srh-price-btn srh-price-btn--ws" data-layer-id="${h.id}" title="Save wholesale price"><i class="fa fa-check"></i></button>
            </div>
            <span class="inv-layer-ws-status srh-price-status" data-layer-id="${h.id}"></span>
          </div>
        </div>
      </div>`;
    }).join('');
    return `<div class="inv-section srh-section">
      <div class="srh-section-header">
        <span class="inv-section-title" style="margin:0"><i class="fa fa-layer-group"></i> Stock Receive History</span>
        <span class="srh-count-badge">${stockHistory.length} batch${stockHistory.length !== 1 ? 'es' : ''}</span>
      </div>
      <div class="srh-cards">${cards}</div>
    </div>`;
  })();

  $('#inv-pane-stock').innerHTML = `
    <div class="inv-section">
      <div class="inv-section-title" style="display:flex;align-items:center;justify-content:space-between">
        <span><i class="fa fa-boxes-stacked"></i> Stock Information</span>
        <button class="po-btn-ghost" id="stock-tab-transfer-btn" style="font-size:11px;padding:4px 10px;gap:5px"><i class="fa fa-right-left"></i> Transfer Stock</button>
      </div>
      <table class="inv-detail-table">
        ${stockRows.map(([label, val]) => `
          <tr><td class="inv-dt-label">${escHtml(String(label))}</td><td class="inv-dt-val">${val}</td></tr>`).join('')}
      </table>
    </div>${locHtml}${stockHistory.length ? stockSummaryHtml : ''}${grnHistHtml}`;

  // Wire save buttons for per-layer cost, selling, and wholesale price
  _bindLayerCostSave(p.id, stockHistory);
  _bindLayerPriceSave(p.id, stockHistory);
  _bindLayerWholesaleSave(p.id, stockHistory);

  // Shortcut: open the Stock Transfer modal with this product already selected
  $('#stock-tab-transfer-btn')?.addEventListener('click', () => {
    _transferOpenModal({ id: p.id, name: p.name });
  });

  // ── Images tab ──
  if (images.length) {
    $('#inv-pane-images').innerHTML = `
      <div class="inv-section">
        <div class="inv-section-title"><i class="fa fa-images"></i> Product Images (${images.length})</div>
        <div class="inv-images-grid">
          ${images.map(img => {
            const url = img.url || img.image_url || img;
            return `<div class="inv-img-card">
              <img src="${url}" alt="Product image" loading="lazy">
            </div>`;
          }).join('')}
        </div>
      </div>`;
  } else {
    $('#inv-pane-images').innerHTML = `<div class="inv-pane-empty"><i class="fa fa-image"></i><p>No images uploaded</p></div>`;
  }

  // ── Variants tab ──
  const variants = p.variants || p.product_variants || [];
  if (variants.length) {
    $('#inv-pane-variants').innerHTML = `
      <div class="inv-section">
        <div class="inv-section-title"><i class="fa fa-layer-group"></i> Variants (${variants.length})</div>
        <table class="inv-detail-table inv-variants-table">
          <thead>
            <tr>
              <th class="inv-dt-label">Variant</th>
              <th class="inv-dt-val">SKU</th>
              <th class="inv-dt-val">Price</th>
              <th class="inv-dt-val">Stock</th>
              <th class="inv-dt-val">Status</th>
            </tr>
          </thead>
          <tbody>
            ${variants.map(v => `
              <tr>
                <td class="inv-dt-label">${escHtml(v.name || v.variant_name || v.options?.map(o => o.value).join(' / ') || '—')}</td>
                <td class="inv-dt-val">${escHtml(v.sku || '—')}</td>
                <td class="inv-dt-val">${v.price != null ? parseFloat(v.price).toFixed(2) : '—'}</td>
                <td class="inv-dt-val">${v.stock_quantity ?? v.stock ?? '—'}</td>
                <td class="inv-dt-val"><span class="inv-badge ${v.is_active !== false ? 'inv-badge-green' : 'inv-badge-gray'}">${v.is_active !== false ? 'Active' : 'Inactive'}</span></td>
              </tr>`).join('')}
          </tbody>
        </table>
      </div>`;
  } else {
    $('#inv-pane-variants').innerHTML = `<div class="inv-pane-empty"><i class="fa fa-layer-group"></i><p>No variants for this product</p></div>`;
  }

  // ── Delivery tab (only visible when this product has courier delivery enabled) ──
  const deliveryMethods = Array.isArray(p.delivery_methods) ? p.delivery_methods : [];
  const deliveryTabBtn = $('#inv-tab-delivery');
  if (deliveryTabBtn) deliveryTabBtn.style.display = deliveryMethods.length ? '' : 'none';
  if (deliveryMethods.length) {
    const deliveryCur = state.currency ? ' ' + state.currency : '';
    $('#inv-pane-delivery').innerHTML = `
      <div class="inv-section">
        <div class="inv-section-title"><i class="fa fa-truck"></i> Delivery Partners (${deliveryMethods.length})</div>
        <div class="inv-delivery-list">
          ${deliveryMethods.map(m => {
            const meta = _DELIVERY_PARTNERS_META[m.key] || { name: m.key, icon: 'fa-truck' };
            return `
            <div class="inv-delivery-row">
              <div class="inv-delivery-row-icon"><i class="fa ${meta.icon}"></i></div>
              <div class="inv-delivery-row-name">${escHtml(meta.name)}</div>
              <div class="inv-delivery-row-price">${m.price != null ? parseFloat(m.price).toFixed(2) + deliveryCur : '—'}</div>
            </div>`;
          }).join('')}
        </div>
      </div>`;
  } else {
    $('#inv-pane-delivery').innerHTML = `<div class="inv-pane-empty"><i class="fa fa-truck"></i><p>Courier delivery is not enabled for this product</p></div>`;
    if (deliveryTabBtn && deliveryTabBtn.classList.contains('active')) {
      deliveryTabBtn.classList.remove('active');
      $('#inv-tabs .inv-tab[data-tab="overview"]')?.classList.add('active');
      $$('.inv-tab-pane').forEach(pane => pane.classList.remove('active'));
      $('#inv-pane-overview')?.classList.add('active');
    }
  }

  // ── Rental tab (only shown when this product is rentable) ──
  const rentalTabBtn = $('#inv-tab-rental');
  if (p.is_rental) {
    rentalTabBtn.style.display = '';
    const dailyRate  = p.rental_daily_rate != null ? parseFloat(p.rental_daily_rate) : null;
    const maxDays    = p.rental_max_days ?? null;
    const lateFeeMul = p.rental_late_fee_multiplier != null ? parseFloat(p.rental_late_fee_multiplier) : null;
    const needsClean = !!p.rental_needs_cleaning;

    let lateFeeVal = '<span class="inv-detail-none">—</span>';
    if (lateFeeMul != null) {
      lateFeeVal = `${lateFeeMul}× daily rate`;
      if (dailyRate != null) lateFeeVal += ` <span style="color:var(--text-muted);font-size:12px">(${(dailyRate * lateFeeMul).toFixed(2)} per late day)</span>`;
    }

    const rentalRows = [
      ['Daily Rate',        dailyRate != null ? dailyRate.toFixed(2) : '<span class="inv-detail-none">—</span>'],
      ['Max Rental Days',   maxDays != null ? maxDays : '<span class="inv-detail-none">—</span>'],
      ['Late Fee',          lateFeeVal],
      ['Cleaning Required', needsClean
        ? '<span class="inv-badge inv-badge-amber"><i class="fa fa-broom"></i> Required before next rental</span>'
        : '<span class="inv-badge inv-badge-green">Not required</span>'],
    ];

    $('#inv-pane-rental').innerHTML = `
      <div class="inv-section">
        <div class="inv-section-title"><i class="fa fa-key"></i> Rental Terms</div>
        <table class="inv-detail-table">
          ${rentalRows.map(([label, val]) => `<tr><td class="inv-dt-label">${escHtml(label)}</td><td class="inv-dt-val">${val}</td></tr>`).join('')}
        </table>
      </div>`;
  } else {
    rentalTabBtn.style.display = 'none';
  }
}

// ── Sales chart (Canvas) ─────────────────────────────────────────────────
function drawSalesChart(canvasId, labels, series) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  const ctx    = canvas.getContext('2d');
  const W = canvas.width  = canvas.offsetWidth  * window.devicePixelRatio;
  const H = canvas.height = canvas.offsetHeight * window.devicePixelRatio;
  ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
  const w = canvas.offsetWidth;
  const h = canvas.offsetHeight;

  const PAD = { top: 24, right: 16, bottom: 48, left: 44 };
  const chartW = w - PAD.left - PAD.right;
  const chartH = h - PAD.top  - PAD.bottom;

  const isDark  = document.body.classList.contains('dark');
  const colBar  = isDark ? 'rgba(130,150,255,0.75)' : 'rgba(109,120,255,0.65)';
  const colGrid = isDark ? 'rgba(255,255,255,.08)'   : 'rgba(0,0,0,.07)';
  const colText = isDark ? 'rgba(255,255,255,.45)'   : 'rgba(0,0,0,.4)';

  ctx.clearRect(0, 0, w, h);

  const maxVal = Math.max(...series, 1);
  const nice   = v => v === Math.floor(v) ? String(v) : v.toFixed(1);

  // Grid lines & Y labels
  const yTicks = 4;
  ctx.font      = `11px system-ui`;
  ctx.textAlign = 'right';
  for (let i = 0; i <= yTicks; i++) {
    const val = (maxVal / yTicks) * i;
    const y   = PAD.top + chartH - (chartH * i / yTicks);
    ctx.strokeStyle = colGrid;
    ctx.lineWidth   = 1;
    ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + chartW, y); ctx.stroke();
    ctx.fillStyle = colText;
    ctx.fillText(nice(val), PAD.left - 6, y + 4);
  }

  // Bars
  const n       = labels.length;
  const barW    = Math.max(4, (chartW / n) * 0.55);
  const gap     = chartW / n;

  series.forEach((val, i) => {
    const barH = chartH * (val / maxVal);
    const x    = PAD.left + gap * i + (gap - barW) / 2;
    const y    = PAD.top  + chartH - barH;
    const r    = Math.min(4, barW / 2);
    ctx.fillStyle = colBar;
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + barW - r, y);
    ctx.quadraticCurveTo(x + barW, y, x + barW, y + r);
    ctx.lineTo(x + barW, y + barH);
    ctx.lineTo(x, y + barH);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    ctx.fill();
  });

  // X labels — show every Nth to avoid crowding
  const step = Math.ceil(n / 8);
  ctx.fillStyle  = colText;
  ctx.textAlign  = 'center';
  ctx.font       = '10px system-ui';
  labels.forEach((lbl, i) => {
    if (i % step !== 0 && i !== n - 1) return;
    const x = PAD.left + gap * i + gap / 2;
    ctx.fillText(lbl, x, h - PAD.bottom + 16);
  });
}

async function loadAndRenderChart(productId, period) {
  const container = $('#inv-chart-container');
  if (!container) return;

  // Update active period button
  $$('.inv-chart-period').forEach(b => b.classList.toggle('active', b.dataset.period === period));

  container.innerHTML = '<div class="inv-chart-loading"><i class="fa fa-spinner fa-spin"></i></div>';

  const res = await API.productSalesChart(productId, period);
  if (res.status !== 200) { container.innerHTML = ''; return; }

  const { labels = [], series = [], total = 0, subtitle = '' } = res.body?.data || {};

  container.innerHTML = `
    <div class="inv-chart-summary">
      <span class="inv-chart-total"><strong>${total % 1 === 0 ? total : total.toFixed(3)}</strong> units in this period</span>
      <span class="inv-chart-subtitle">${escHtml(subtitle)}</span>
    </div>
    <div class="inv-chart-wrap"><canvas id="inv-sales-canvas"></canvas></div>`;

  requestAnimationFrame(() => drawSalesChart('inv-sales-canvas', labels, series));
}

// Tab switching in detail view
$('#inv-tabs').addEventListener('click', e => {
  const tab = e.target.closest('.inv-tab');
  if (!tab) return;
  $$('#inv-tabs .inv-tab').forEach(t => t.classList.remove('active'));
  tab.classList.add('active');
  $$('.inv-tab-pane').forEach(p => p.classList.remove('active'));
  $(`#inv-pane-${tab.dataset.tab}`).classList.add('active');
});

// ── Products ───────────────────────────────────────────────────────────────
async function loadProducts(search = '', catId = 0, page = 1) {
  const grid = $('#product-grid');
  grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--text-muted)"><i class="fa fa-spinner fa-spin" style="font-size:24px"></i></div>';
  setStatus('Loading products…');

  const applyRecent  = state.filterRecentSales && !search;
  const effectiveCat = search ? 0 : catId;
  const res = await API.bootstrap(search, effectiveCat, page, {
    sort: applyRecent ? 'recent_sales' : 'name_asc',
    recentSales: applyRecent,
  });
  if (res.status !== 200) {
    grid.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:40px;color:#e74c3c"><i class="fa fa-circle-exclamation"></i> Failed to load products</div>`;
    setStatus('Error loading products');
    return;
  }

  const { products = [], categories = [], currency = '', settings = {}, business = {}, product_units = [], products_meta = {} } = res.body?.data || res.body || {};
  state.products        = products;
  state.categories      = categories;
  state.receiptSettings = settings;
  state.productUnits    = product_units;
  state.activePage      = products_meta.current_page || page;
  if (currency)       state.currency = currency;
  if (business?.name) state._bizName = state._bizName || business.name;

  // Apply purchase-order mode based on setting (default: enabled)
  _applyPurchaseOrderMode(settings.purchase_order_enabled !== false);

  buildCategoryBar(categories, catId);
  buildProductGrid(products);
  buildPosPagination(products_meta);
  setStatus(`Zeebroo POS · ${products_meta.total || products.length} products`);
}

function buildCategoryBar(categories, active) {
  const bar  = $('#category-filter');
  const rs   = state.filterRecentSales;
  bar.innerHTML =
    `<div class="cat-chip ${!rs && active === 0 ? 'active' : ''}" data-cat="0">All</div>` +
    `<div class="cat-chip cat-chip-recent ${rs ? 'active' : ''}" data-cat="recent"><i class="fa fa-clock-rotate-left"></i> Recent</div>`;
  categories.forEach(c => {
    const chip = document.createElement('div');
    chip.className = `cat-chip ${!rs && c.id === active ? 'active' : ''}`;
    chip.dataset.cat = c.id;
    chip.textContent = c.name;
    bar.appendChild(chip);
  });
  bar.querySelectorAll('.cat-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      if (chip.dataset.cat === 'recent') {
        state.filterRecentSales = true;
        state.activeCategory    = 0;
      } else {
        state.filterRecentSales = false;
        state.activeCategory    = Number(chip.dataset.cat);
      }
      _ssClose();
      loadProducts(state.searchQuery, state.activeCategory);
    });
  });
  updateScrollArrows('category-filter', 'cat-scroll-left', 'cat-scroll-right');
}

function buildProductGrid(products) {
  _pgSelIdx = -1;
  const grid = $('#product-grid');
  if (!products.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:60px;color:var(--text-muted)"><i class="fa fa-box-open" style="font-size:32px;display:block;margin-bottom:10px;opacity:.3"></i>No products found</div>';
    return;
  }
  grid.innerHTML = products.map(p => {
    const outOfStock    = (parseFloat(p.stock_quantity) || 0) <= 0;
    const effectivePrice = p.discounted_sell_price ?? p.unit_sell_price ?? 0;
    const origPrice     = p.discounted_sell_price !== null && p.discounted_sell_price !== undefined ? p.unit_sell_price : null;
    const discount      = p.discount ?? null;

    let priceHtml;
    if (origPrice !== null) {
      let badge = '';
      if (discount) {
        const lbl = discount.type === 'percentage'
          ? `-${Math.round(discount.value)}%`
          : `-${parseFloat(discount.amount ?? 0).toFixed(2)}`;
        badge = ` <span class="p-discount-badge">${lbl}</span>`;
      }
      priceHtml = `<span class="p-price-orig">${parseFloat(origPrice).toFixed(2)}</span> ${parseFloat(effectivePrice).toFixed(2)}${badge}`;
    } else {
      priceHtml = parseFloat(effectivePrice).toFixed(2);
    }

    const metaParts = [];
    if (p.sku) metaParts.push(escHtml(p.sku));
    if (p.stock_quantity != null) metaParts.push(`${p.stock_quantity} in stock`);

    return `<div class="product-card${outOfStock ? ' is-out' : ''}" data-id="${p.id}" data-name="${escHtml(p.name)}" data-sku="${escHtml(p.sku ?? '')}" data-price="${effectivePrice}" data-stock="${p.stock_quantity ?? ''}">
      ${p.image_url ? `<img src="${p.image_url}" alt="${escHtml(p.name)}" loading="lazy">` : `<div class="p-icon"><i class="fa fa-box"></i></div>`}
      <div class="p-name">${escHtml(p.name)}</div>
      ${metaParts.length ? `<div class="p-meta">${metaParts.join(' · ')}</div>` : ''}
      <div class="p-price">${priceHtml}</div>
    </div>`;
  }).join('');

  grid.querySelectorAll('.product-card:not(.is-out)').forEach(card => {
    const p = state.products.find(pr => pr.id === Number(card.dataset.id));
    card.addEventListener('click', () => {
      if (p) handleProductClick(p);
      else addToCart({ id: Number(card.dataset.id), name: card.dataset.name, price: parseFloat(card.dataset.price), stock: card.dataset.stock !== '' ? Number(card.dataset.stock) : null, layerId: null, layerLabel: null });
    });
  });
}

// ── Product card context menu ────────────────────────────────────────────────
(function () {
  const menu    = $('#prod-ctx-menu');
  const copyName = $('#prod-ctx-copy-name');
  const copySku  = $('#prod-ctx-copy-sku');
  if (!menu) return;

  let _ctxCard = null;

  function showMenu(x, y, card) {
    _ctxCard = card;
    const hasSku = !!card.dataset.sku;
    copySku.classList.toggle('disabled', !hasSku);
    // Position — keep menu on screen
    menu.style.display = 'block';
    const mw = menu.offsetWidth, mh = menu.offsetHeight;
    const vw = window.innerWidth,  vh = window.innerHeight;
    menu.style.left = (x + mw > vw ? vw - mw - 6 : x) + 'px';
    menu.style.top  = (y + mh > vh ? vh - mh - 6 : y) + 'px';
  }

  function hideMenu() { menu.style.display = 'none'; _ctxCard = null; }

  document.addEventListener('contextmenu', e => {
    const card = e.target.closest('.product-card');
    if (!card || !card.closest('#product-grid')) { hideMenu(); return; }
    e.preventDefault();
    showMenu(e.clientX, e.clientY, card);
  });

  document.addEventListener('click',     () => hideMenu());
  document.addEventListener('keydown',   e => { if (e.key === 'Escape') hideMenu(); });
  document.addEventListener('scroll',    () => hideMenu(), true);

  copyName.addEventListener('click', () => {
    if (!_ctxCard) return;
    navigator.clipboard.writeText(_ctxCard.dataset.name || '').then(() => toast('Product name copied', 'success'));
    hideMenu();
  });

  copySku.addEventListener('click', () => {
    if (!_ctxCard || !_ctxCard.dataset.sku) return;
    navigator.clipboard.writeText(_ctxCard.dataset.sku).then(() => toast('SKU copied', 'success'));
    hideMenu();
  });
})();

function buildPosPagination(meta) {
  const pg      = $('#pos-pagination');
  const current = meta?.current_page || 1;
  const last    = meta?.last_page    || 1;
  if (last <= 1) { pg.innerHTML = ''; return; }
  const pages = [];
  for (let i = Math.max(1, current - 2); i <= Math.min(last, current + 2); i++) pages.push(i);
  pg.innerHTML =
    (current > 1 ? `<button class="inv-pg-btn" data-p="${current - 1}"><i class="fa fa-chevron-left"></i></button>` : '') +
    pages.map(p => `<button class="inv-pg-btn${p === current ? ' active' : ''}" data-p="${p}">${p}</button>`).join('') +
    (current < last ? `<button class="inv-pg-btn" data-p="${current + 1}"><i class="fa fa-chevron-right"></i></button>` : '');
  pg.querySelectorAll('.inv-pg-btn').forEach(btn =>
    btn.addEventListener('click', () => loadProducts(state.searchQuery, state.activeCategory, Number(btn.dataset.p)))
  );
}

// ── Search with auto-suggest ───────────────────────────────────────────────
let searchTimer;
let _ssSelIdx  = -1;
const MAX_SUGGEST = 8;

function _ssItems() { return [...$$('#search-suggest .ss-item')]; }

function _ssHighlight(idx) {
  const items = _ssItems();
  if (!items.length) return;
  _ssSelIdx = Math.max(0, Math.min(items.length - 1, idx));
  items.forEach((el, i) => el.classList.toggle('active', i === _ssSelIdx));
  items[_ssSelIdx]?.scrollIntoView({ block: 'nearest' });
}

function _ssClose() {
  $('#search-suggest').style.display = 'none';
  _ssSelIdx = -1;
}

function _ssOpen() {
  $('#search-suggest').style.display = '';
}

// Add product directly to cart without showing layer picker (barcode scanner mode)
async function _addToCartDirectly(p) {
  const layers = p.layers || [];
  const layer  = layers.find(l => parseFloat(l.quantity_remaining) > 0) || null;
  let cartItem;
  if (layer) {
    // FIFO: no layerId pinning — backend consumeFifo spans all layers if needed
    cartItem = {
      id: p.id, layerId: null, layerLabel: null,
      name: p.name, price: parseFloat(layer.unit_sell_price),
      stock: p.stock_quantity != null ? parseFloat(p.stock_quantity) : null,
    };
  } else {
    cartItem = {
      id: p.id, layerId: null, layerLabel: null,
      name: p.name, price: parseFloat(p.discounted_sell_price ?? layers[0]?.unit_sell_price ?? p.unit_sell_price ?? 0),
      stock: p.stock_quantity != null ? parseFloat(p.stock_quantity) : null,
    };
  }
  if (p.has_warranty) {
    const tab = activeTab();
    const key = cartItem.layerId != null ? `${cartItem.id}:${cartItem.layerId}` : `${cartItem.id}`;
    const alreadyInCart = tab?.cart.some(i => i._key === key);
    if (!alreadyInCart) {
      if (p.warranty_duration) {
        const wty = _resolveWarrantyFromDuration(p.warranty_duration);
        cartItem.warrantyType = wty.type;
        cartItem.warrantyDate = wty.date ?? null;
      } else {
        const wty = await _askWarranty(cartItem.name);
        if (wty === null) return;
        cartItem.warrantyType = wty.type;
        cartItem.warrantyDate = wty.date ?? null;
      }
    }
  }
  addToCart(cartItem);
}

// Find product by exact SKU (case-insensitive, trimmed)
function _findBySku(q) {
  const lower = q.trim().toLowerCase();
  if (!lower) return null;
  return state.products.find(p => p.sku && p.sku.trim().toLowerCase() === lower) || null;
}

// Try exact SKU match → add to cart and clear; returns true if matched
function _trySkuAdd(q) {
  const match = _findBySku(q);
  if (!match) return false;
  _addToCartDirectly(match);
  $('#product-search').value = '';
  state.searchQuery = '';
  _ssClose();
  clearTimeout(searchTimer);
  return true;
}

function _ssRender(q) {
  const box = $('#search-suggest');
  if (!q) { _ssClose(); return; }

  // Exact SKU match → auto-add immediately, no dropdown (barcode scanner mode)
  if (_trySkuAdd(q)) return;

  const lower = q.toLowerCase();
  const matches = state.products.filter(p =>
    p.name.toLowerCase().includes(lower) ||
    (p.sku && p.sku.toLowerCase().includes(lower))
  );

  if (!matches.length) {
    box.innerHTML = `<div class="ss-empty"><i class="fa fa-box-open"></i>No products found for "<strong>${escHtml(q)}</strong>"</div>`;
    _ssOpen(); return;
  }

  const shown  = matches.slice(0, MAX_SUGGEST);
  const more   = matches.length - shown.length;
  const cur    = state.currency ? ' ' + state.currency : '';

  box.innerHTML = shown.map((p, idx) => {
    const price      = parseFloat(p.discounted_sell_price ?? p.unit_sell_price ?? 0);
    const outOfStock = (parseFloat(p.stock_quantity) || 0) <= 0;
    const imgHtml    = p.image_url
      ? `<img class="ss-thumb" src="${p.image_url}" alt="">`
      : `<div class="ss-icon"><i class="fa fa-box"></i></div>`;
    const metaParts  = [];
    if (p.sku) metaParts.push(p.sku);
    if (p.category_name) metaParts.push(p.category_name);

    return `<div class="ss-item${outOfStock ? ' ss-out' : ''}" data-id="${p.id}" data-idx="${idx}">
      ${imgHtml}
      <div class="ss-body">
        <div class="ss-name">${escHtml(p.name)}</div>
        ${metaParts.length ? `<div class="ss-meta">${escHtml(metaParts.join(' · '))}</div>` : ''}
      </div>
      <div class="ss-right">
        <span class="ss-price">${price.toFixed(2)}${cur}</span>
        ${outOfStock
          ? '<span class="ss-out-badge">Out of stock</span>'
          : (p.stock_quantity != null ? `<span class="ss-stock">${p.stock_quantity} in stock</span>` : '')}
      </div>
    </div>`;
  }).join('') + (more > 0 ? `<div class="ss-footer"><i class="fa fa-ellipsis"></i> ${more} more — keep typing to narrow down</div>` : '');

  box.querySelectorAll('.ss-item').forEach(el => {
    el.addEventListener('mousedown', ev => {
      ev.preventDefault(); // prevent blur before click fires
      const p = state.products.find(pr => pr.id === Number(el.dataset.id));
      if (!p) return;
      if ((parseFloat(p.stock_quantity) || 0) <= 0 && (p.layers || []).every(l => parseFloat(l.quantity_remaining) <= 0)) {
        toast(`${p.name} is out of stock`, 'info'); return;
      }
      handleProductClick(p);
      $('#product-search').value = '';
      state.searchQuery = '';
      _ssClose();
      clearTimeout(searchTimer);
      loadProducts('', state.activeCategory);
    });
    el.addEventListener('mousemove', () => {
      _ssSelIdx = Number(el.dataset.idx);
      _ssItems().forEach((x, i) => x.classList.toggle('active', i === _ssSelIdx));
    });
  });

  _ssOpen();
  _ssSelIdx = -1;
}

$('#product-search').addEventListener('focus', () => {
  _pgClear();
  if ($('#product-search').value.trim()) _ssRender($('#product-search').value.trim());
});

$('#product-search').addEventListener('blur', () => {
  setTimeout(_ssClose, 150);
});

$('#product-search').addEventListener('input', (e) => {
  clearTimeout(searchTimer);
  const q = e.target.value;
  state.searchQuery = q;
  _ssRender(q.trim());
  if (q.trim()) {
    searchTimer = setTimeout(() => loadProducts(state.searchQuery, state.activeCategory), 400);
  }
});

// API fallback for batch SKUs (e.g. PRD-IIW3ZFGK-02) that aren't in local state
async function _tryBatchSkuApiAdd(q) {
  const res = await API.productBySku(q);
  if (res.status !== 200) return false;
  const p = res.body?.data || res.body;
  if (!p || !p.id) return false;
  const layerId = p.matched_layer_id ?? null;
  const matchedLayer = layerId && p.layers ? p.layers.find(l => l.id === layerId) : null;
  const price = matchedLayer
    ? parseFloat(matchedLayer.unit_sell_price)
    : parseFloat(p.discounted_sell_price ?? p.unit_sell_price ?? p.price ?? 0);
  const cartItem = { id: p.id, name: p.name, price, stock: p.layer_qty_remaining ?? p.stock_quantity ?? null, layerId };
  if (p.has_warranty) {
    const tab = activeTab();
    const key = layerId != null ? `${p.id}:${layerId}` : `${p.id}`;
    const alreadyInCart = tab?.cart.some(i => i._key === key);
    if (!alreadyInCart) {
      if (p.warranty_duration) {
        const wty = _resolveWarrantyFromDuration(p.warranty_duration);
        cartItem.warrantyType = wty.type;
        cartItem.warrantyDate = wty.date ?? null;
      } else {
        const wty = await _askWarranty(cartItem.name);
        if (wty === null) {
          $('#product-search').value = ''; state.searchQuery = ''; _ssClose(); clearTimeout(searchTimer);
          return true;
        }
        cartItem.warrantyType = wty.type;
        cartItem.warrantyDate = wty.date ?? null;
      }
    }
  }
  addToCart(cartItem);
  $('#product-search').value = '';
  state.searchQuery = '';
  _ssClose();
  clearTimeout(searchTimer);
  return true;
}

$('#product-search').addEventListener('keydown', async (e) => {
  const box  = $('#search-suggest');
  const open = box.style.display !== 'none';
  const q    = $('#product-search').value.trim();

  if (e.key === 'ArrowDown') {
    e.preventDefault();
    if (!open && q) { _ssRender(q); return; }
    _ssHighlight(_ssSelIdx < 0 ? 0 : _ssSelIdx + 1);
    return;
  }
  if (e.key === 'ArrowUp') {
    e.preventDefault();
    if (open) _ssHighlight(_ssSelIdx <= 0 ? 0 : _ssSelIdx - 1);
    return;
  }
  if (e.key === 'Enter') {
    e.preventDefault();
    // 1. Exact product-level SKU match in local state (fast path)
    if (q && _trySkuAdd(q)) return;
    // 2. Batch SKU API lookup (e.g. PRD-IIW3ZFGK-02 not in local state)
    if (q) {
      const handled = await _tryBatchSkuApiAdd(q);
      if (handled) return;
    }
    // 3. Highlighted suggestion
    if (open && _ssSelIdx >= 0) {
      _ssItems()[_ssSelIdx]?.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })); return;
    }
    // 4. First available suggestion
    if (open) {
      const first = $('#search-suggest .ss-item:not(.ss-out)');
      first?.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
    }
    return;
  }
  if (e.key === 'Escape') {
    e.preventDefault();
    _ssClose();
    return;
  }
});

$('#btn-refresh-products').addEventListener('click', () => loadProducts(state.searchQuery, state.activeCategory));
$('#rb-refresh').addEventListener('click', () => loadProducts(state.searchQuery, state.activeCategory));

// ── Category chip bar: left/right scroll arrows ─────────────────────────────
function updateScrollArrows(trackId, leftId, rightId) {
  const track = $('#' + trackId), left = $('#' + leftId), right = $('#' + rightId);
  if (!track || !left || !right) return;
  const max = track.scrollWidth - track.clientWidth;
  left.disabled  = track.scrollLeft <= 1;
  right.disabled = max <= 1 || track.scrollLeft >= max - 1;
}
function wireCategoryScroll(trackId, leftId, rightId) {
  const track = $('#' + trackId), left = $('#' + leftId), right = $('#' + rightId);
  if (!track || !left || !right) return;
  left.addEventListener('click', () => track.scrollBy({ left: -160, behavior: 'smooth' }));
  right.addEventListener('click', () => track.scrollBy({ left: 160, behavior: 'smooth' }));
  track.addEventListener('scroll', () => updateScrollArrows(trackId, leftId, rightId));
  window.addEventListener('resize', () => updateScrollArrows(trackId, leftId, rightId));
  // The bar can be built/measured while its tab/panel is still display:none
  // (clientWidth/scrollWidth both read 0 then), so re-check whenever the
  // track's actual rendered size changes — e.g. when its panel becomes visible.
  if (window.ResizeObserver) {
    new ResizeObserver(() => updateScrollArrows(trackId, leftId, rightId)).observe(track);
  }
  updateScrollArrows(trackId, leftId, rightId);
}
wireCategoryScroll('category-filter', 'cat-scroll-left', 'cat-scroll-right');
wireCategoryScroll('service-category-filter', 'svc-cat-scroll-left', 'svc-cat-scroll-right');

// ── POS Mode Switcher ──────────────────────────────────────────────────────
function switchPosMode(mode) {
  if (state.posMode === mode) return;
  state.posMode = mode;
  $$('.pos-mode-btn').forEach(b => b.classList.toggle('active', b.dataset.mode === mode));

  const productEls = [
    $('#product-search-bar'), $('#category-filter-wrap'),
    $('#product-grid'), $('#pos-pagination'),
  ];
  const svcSection = $('#pos-service-section');

  if (mode === 'products') {
    productEls.forEach(el => el && (el.style.display = ''));
    if (svcSection) svcSection.style.display = 'none';
    loadProducts(state.searchQuery, state.activeCategory);
  } else {
    productEls.forEach(el => el && (el.style.display = 'none'));
    if (svcSection) { svcSection.style.display = 'flex'; svcSection.style.flexDirection = 'column'; }
    loadServices(state.serviceSearchQuery, state.serviceActiveCategory);
  }
}

$$('.pos-mode-btn').forEach(btn => {
  btn.addEventListener('click', () => switchPosMode(btn.dataset.mode));
});

// ── Services ──────────────────────────────────────────────────────────────
async function loadServices(search = '', catId = 0) {
  const grid = $('#service-grid');
  if (!grid) return;
  grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--text-muted)"><i class="fa fa-spinner fa-spin" style="font-size:24px"></i></div>';
  setStatus('Loading services…');

  const res = await API.servicePosCatalog(search, catId);
  if (res.status !== 200) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:40px;color:#e74c3c"><i class="fa fa-circle-exclamation"></i> Failed to load services</div>';
    setStatus('Error loading services');
    return;
  }

  const { services = [], categories = [] } = res.body?.data || {};
  state.services = services;
  buildServiceCategoryBar(categories, catId);
  buildServiceGrid(services);
  setStatus(`Services · ${services.length} available`);
}

function buildServiceCategoryBar(categories, active) {
  const bar = $('#service-category-filter');
  if (!bar) return;
  bar.innerHTML = `<div class="cat-chip ${active === 0 ? 'active' : ''}" data-cat="0">All</div>`;
  categories.forEach(c => {
    const chip = document.createElement('div');
    chip.className = `cat-chip ${c.id === active ? 'active' : ''}`;
    chip.dataset.cat = c.id;
    chip.textContent = c.name;
    bar.appendChild(chip);
  });
  bar.querySelectorAll('.cat-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      state.serviceActiveCategory = Number(chip.dataset.cat);
      loadServices(state.serviceSearchQuery, state.serviceActiveCategory);
    });
  });
  updateScrollArrows('service-category-filter', 'svc-cat-scroll-left', 'svc-cat-scroll-right');
}

function buildServiceGrid(services) {
  const grid = $('#service-grid');
  if (!grid) return;
  if (!services.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:60px;color:var(--text-muted)"><i class="fa fa-screwdriver-wrench" style="font-size:32px;display:block;margin-bottom:10px;opacity:.3"></i>No services found</div>';
    return;
  }
  const cur      = state.currency ? ' ' + state.currency : '';
  const featured = services.filter(s => s.is_featured);
  const rest     = services.filter(s => !s.is_featured);

  const cardHtml = s =>
    `<div class="svc-card${s.is_featured ? ' svc-card--featured' : ''}" data-id="${s.id}">
      ${s.is_featured ? '<div class="svc-featured-badge"><i class="fa fa-star"></i></div>' : ''}
      <div class="svc-icon"><i class="fa fa-screwdriver-wrench"></i></div>
      <div class="svc-name">${escHtml(s.name)}</div>
      ${s.duration_label && s.duration_label !== '—' ? `<div class="svc-dur"><i class="fa fa-clock"></i> ${escHtml(s.duration_label)}</div>` : ''}
      <div class="svc-price">${s.price > 0 ? parseFloat(s.price).toFixed(2) + cur : 'Free'}</div>
      ${s.has_warranty ? '<div class="svc-wty-badge"><i class="fa fa-shield-halved"></i></div>' : ''}
      ${s.custom_requirement_enabled ? '<div class="svc-creq-badge"><i class="fa fa-list-check"></i></div>' : ''}
    </div>`;

  let html = '';
  if (featured.length) {
    html += `<div class="svc-section-label" style="grid-column:1/-1"><i class="fa fa-star"></i> Featured</div>`;
    html += featured.map(cardHtml).join('');
  }
  if (rest.length) {
    if (featured.length) html += `<div class="svc-section-label" style="grid-column:1/-1"><i class="fa fa-list"></i> All Services</div>`;
    html += rest.map(cardHtml).join('');
  }
  grid.innerHTML = html;

  grid.querySelectorAll('.svc-card').forEach(card => {
    const s = services.find(x => x.id === Number(card.dataset.id));
    if (s) card.addEventListener('click', () => addServiceToCart(s));
  });
}

async function addServiceToCart(service) {
  _beep.currentTime = 0; _beep.play().catch(() => {});
  const tab = activeTab();
  if (!tab) return;
  const key = `svc:${service.id}`;
  const existing = tab.cart.find(i => i._key === key);
  if (existing) {
    existing.qty += 1;
  } else {
    const cartItem = {
      id: service.id, name: service.name,
      price: parseFloat(service.price) || 0,
      qty: 1, _key: key,
      _basePrice: parseFloat(service.price) || 0,
      _discountPct: null, _note: null,
      _type: 'service',
      layerId: null, layerLabel: null, stock: null,
      warrantyType: null, warrantyDate: null,
      customRequirementValues: null,
    };
    if (service.has_warranty) {
      const wty = await _askWarranty(service.name);
      if (wty === null) return; // cancelled
      cartItem.warrantyType = wty.type;
      cartItem.warrantyDate = wty.date ?? null;
    }
    if (service.custom_requirement_enabled && (service.custom_requirement_fields || []).length) {
      const values = await _askCustomRequirement(service);
      if (values === null) return; // cancelled
      cartItem.customRequirementValues = values;
    }
    tab.cart.push(cartItem);
  }
  renderCart(); renderPosTabBar();
  requestAnimationFrame(() => {
    const input = $(`#cart-items .ci-qty-input[data-key="${CSS.escape(key)}"]`);
    if (input) { input.focus(); input.select(); }
  });
}

// Service search input
let _svcSearchTimer = null;
$('#service-search')?.addEventListener('input', e => {
  clearTimeout(_svcSearchTimer);
  state.serviceSearchQuery = e.target.value;
  _svcSearchTimer = setTimeout(() => loadServices(state.serviceSearchQuery, state.serviceActiveCategory), 400);
});
$('#btn-refresh-services')?.addEventListener('click', () => loadServices(state.serviceSearchQuery, state.serviceActiveCategory));

// ── Product grid keyboard navigation ───────────────────────────────────────
let _pgSelIdx = -1;

function _pgCards() {
  return [...$$('#product-grid .product-card:not(.is-out)')];
}

function _pgColumns() {
  const cards = _pgCards();
  if (cards.length < 2) return 1;
  const firstTop = cards[0].getBoundingClientRect().top;
  let cols = 0;
  for (const c of cards) {
    if (Math.abs(c.getBoundingClientRect().top - firstTop) > 4) break;
    cols++;
  }
  return Math.max(1, cols);
}

function _pgSelect(idx) {
  const cards = _pgCards();
  if (!cards.length) return;
  _pgSelIdx = Math.max(0, Math.min(cards.length - 1, idx));
  $$('#product-grid .product-card').forEach(c => c.classList.remove('kbd-selected'));
  cards[_pgSelIdx].classList.add('kbd-selected');
  cards[_pgSelIdx].scrollIntoView({ block: 'nearest', behavior: 'smooth' });
}

function _pgClear() {
  _pgSelIdx = -1;
  $$('#product-grid .product-card').forEach(c => c.classList.remove('kbd-selected'));
}

function _posIsActive() {
  return $('#panel-pos')?.classList.contains('active');
}

function _noModalOpen() {
  return ![...$$('.modal-overlay')].some(m => m.style.display !== 'none') &&
         $('#pos-layer-picker')?.getAttribute('aria-hidden') !== 'false' &&
         $('#search-suggest')?.style.display === 'none';
}

// ── End product grid keyboard navigation ───────────────────────────────────

// ── Cart item keyboard navigation ──────────────────────────────────────────
let _ciSelIdx = -1;
let _ciSelKey = null;

function _ciItems() {
  return [...$$('#cart-items .cart-item')];
}

function _ciSelect(idx) {
  const items = _ciItems();
  if (!items.length) return;
  _ciSelIdx = Math.max(0, Math.min(items.length - 1, idx));
  _ciSelKey = items[_ciSelIdx]?.dataset.key || null;
  items.forEach((el, i) => el.classList.toggle('cart-item--selected', i === _ciSelIdx));
  items[_ciSelIdx]?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  _pgClear(); // deselect product grid when cart is active
}

function _ciClear() {
  _ciSelIdx = -1;
  _ciSelKey = null;
  _ciItems().forEach(el => el.classList.remove('cart-item--selected'));
}

function _ciRestoreSelection() {
  if (!_ciSelKey) return;
  const items = _ciItems();
  const idx = items.findIndex(el => el.dataset.key === _ciSelKey);
  if (idx >= 0) {
    _ciSelIdx = idx;
    items[idx].classList.add('cart-item--selected');
  } else {
    _ciSelIdx = -1;
    _ciSelKey = null;
  }
}
// ── Cart item discount modal ────────────────────────────────────────────────
function openDiscountModal() {
  const tab = activeTab();
  if (!tab || _ciSelKey === null) return;
  const item = tab.cart.find(i => i._key === _ciSelKey);
  if (!item) return;

  const modal = $('#ci-discount-modal');
  const input = $('#ci-discount-input');
  if (!modal || !input) return;

  $('#ci-discount-title').textContent = `Discount — ${item.name}`;
  input.value = item._discountPct != null ? item._discountPct : '';
  modal.style.display = 'flex';
  requestAnimationFrame(() => { input.focus(); input.select(); });
}

function _closeDiscountModal() {
  $('#ci-discount-modal').style.display = 'none';
}

$('#ci-discount-close')?.addEventListener('click',  _closeDiscountModal);
$('#ci-discount-cancel')?.addEventListener('click', _closeDiscountModal);
$('#ci-discount-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) _closeDiscountModal(); });

$('#ci-discount-apply')?.addEventListener('click', () => {
  const tab  = activeTab();
  const item = tab?.cart.find(i => i._key === _ciSelKey);
  if (!item) { _closeDiscountModal(); return; }

  const pct = parseFloat($('#ci-discount-input').value);
  if (isNaN(pct) || pct < 0 || pct > 100) {
    toast('Enter a discount between 0 and 100', 'error'); return;
  }
  item._discountPct = pct;
  item.price = pct > 0
    ? parseFloat((item._basePrice * (1 - pct / 100)).toFixed(2))
    : item._basePrice;
  _closeDiscountModal();
  renderCart();
  toast(pct > 0 ? `${pct}% discount applied` : 'Discount removed', 'success');
});

$('#ci-discount-input')?.addEventListener('keydown', e => {
  if (e.key === 'Enter')  { $('#ci-discount-apply').click(); e.preventDefault(); }
  if (e.key === 'Escape') { _closeDiscountModal(); e.preventDefault(); }
});

// ── Cart item note / modifier modal ─────────────────────────────────────────
function openNoteModal() {
  const tab = activeTab();
  if (!tab || _ciSelKey === null) return;
  const item = tab.cart.find(i => i._key === _ciSelKey);
  if (!item) return;

  const modal = $('#ci-note-modal');
  const input = $('#ci-note-input');
  if (!modal || !input) return;

  $('#ci-note-title').textContent = `Note — ${item.name}`;
  input.value = item._note ?? '';
  modal.style.display = 'flex';
  requestAnimationFrame(() => { input.focus(); });
}

function _closeNoteModal() {
  $('#ci-note-modal').style.display = 'none';
}

$('#ci-note-close')?.addEventListener('click',  _closeNoteModal);
$('#ci-note-cancel')?.addEventListener('click', _closeNoteModal);
$('#ci-note-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) _closeNoteModal(); });

$('#ci-note-apply')?.addEventListener('click', () => {
  const tab  = activeTab();
  const item = tab?.cart.find(i => i._key === _ciSelKey);
  if (!item) { _closeNoteModal(); return; }

  item._note = $('#ci-note-input').value.trim() || null;
  _closeNoteModal();
  renderCart();
  toast(item._note ? 'Note saved' : 'Note cleared', 'success');
});

$('#ci-note-input')?.addEventListener('keydown', e => {
  if (e.key === 'Enter')  { $('#ci-note-apply').click(); e.preventDefault(); }
  if (e.key === 'Escape') { _closeNoteModal(); e.preventDefault(); }
});

// ── Undo last scan ──────────────────────────────────────────────────────────
function undoLastCartItem() {
  const tab = activeTab();
  if (!tab || !tab.cart.length) { toast('Nothing to undo', 'info'); return; }
  const last = tab.cart[tab.cart.length - 1];
  if (last.qty > 1) {
    last.qty -= 1;
  } else {
    tab.cart.pop();
  }
  _ciClear();
  renderCart();
  renderPosTabBar();
  toast('Last item undone', 'info');
}

// ── Park / Hold sale ────────────────────────────────────────────────────────
function parkCurrentSale() {
  const tab = activeTab();
  if (!tab || !tab.cart.length) { toast('Cart is empty — nothing to park', 'info'); return; }
  const label = prompt(`Name this held sale:`, `Hold ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
  if (label === null) return; // cancelled
  state.parkedSales.push({
    id: state._nextParkedId++,
    label: label.trim() || `Hold ${state._nextParkedId}`,
    cart: JSON.parse(JSON.stringify(tab.cart)), // deep copy
    customer: tab._customer || null,
    parkedAt: Date.now(),
  });
  tab.cart = [];
  tab._customer = null;
  renderCart();
  renderPosTabBar();
  renderCartCustomer();
  toast(`Sale held as "${state.parkedSales[state.parkedSales.length - 1].label}"`, 'success');
  updateParkedBadge();
}

function updateParkedBadge() {
  const badge = $('#park-badge');
  if (badge) badge.textContent = state.parkedSales.length || '';
  badge && (badge.style.display = state.parkedSales.length ? '' : 'none');
}

function openParkedSalesModal() {
  const modal  = $('#park-modal');
  const list   = $('#park-modal-list');
  if (!modal || !list) return;

  if (!state.parkedSales.length) {
    list.innerHTML = '<div class="park-empty"><i class="fa fa-inbox"></i><span>No held sales</span></div>';
  } else {
    const cur = state.currency ? ' ' + state.currency : '';
    list.innerHTML = state.parkedSales.map(ps => {
      const total = ps.cart.reduce((s, i) => s + i.price * i.qty, 0);
      const items = ps.cart.reduce((s, i) => s + i.qty, 0);
      const time  = new Date(ps.parkedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      return `<div class="park-row" data-id="${ps.id}">
        <div class="park-row-main">
          <span class="park-row-label">${escHtml(ps.label)}</span>
          <span class="park-row-meta">${items} item${items !== 1 ? 's' : ''} &middot; ${time}</span>
        </div>
        <div class="park-row-total">${total.toFixed(2)}${cur}</div>
        <button class="park-row-recall" data-id="${ps.id}" title="Recall"><i class="fa fa-rotate-left"></i></button>
        <button class="park-row-del" data-id="${ps.id}" title="Discard"><i class="fa fa-trash"></i></button>
      </div>`;
    }).join('');

    list.querySelectorAll('.park-row-recall').forEach(btn => {
      btn.addEventListener('click', e => { e.stopPropagation(); recallParkedSale(Number(btn.dataset.id)); });
    });
    list.querySelectorAll('.park-row-del').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        if (!confirm('Discard this held sale?')) return;
        state.parkedSales = state.parkedSales.filter(p => p.id !== Number(btn.dataset.id));
        updateParkedBadge();
        openParkedSalesModal(); // re-render
      });
    });
    list.querySelectorAll('.park-row').forEach(row => {
      row.addEventListener('click', () => recallParkedSale(Number(row.dataset.id)));
    });
  }

  modal.style.display = 'flex';
}

function recallParkedSale(id) {
  const ps = state.parkedSales.find(p => p.id === id);
  if (!ps) return;
  const tab = activeTab();
  if (!tab) return;

  if (tab.cart.length > 0) {
    if (!confirm('Replace current cart with the held sale?')) return;
  }
  tab.cart = JSON.parse(JSON.stringify(ps.cart));
  tab._customer = ps.customer;
  state.parkedSales = state.parkedSales.filter(p => p.id !== id);
  updateParkedBadge();
  $('#park-modal').style.display = 'none';
  renderCart();
  renderPosTabBar();
  renderCartCustomer();
  toast(`"${ps.label}" recalled`, 'success');
}

$('#park-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) $('#park-modal').style.display = 'none'; });
$('#park-modal-close')?.addEventListener('click', () => { $('#park-modal').style.display = 'none'; });

// ── Customer selection (F10) ─────────────────────────────────────────────────
let _custSearchTimer = null;

function _applyCustomerPricing() {
  const tab = activeTab();
  if (!tab) return;
  const isWholesale = tab._customer?.customer_type === 'wholesale';
  let changed = false;
  tab.cart.forEach(item => {
    if (item._type === 'service') return; // services don't have wholesale price
    const target = (isWholesale && item._wholesalePrice != null)
      ? item._wholesalePrice
      : item._retailPrice;
    if (target != null && Math.abs(item.price - target) > 0.001) {
      item.price      = target;
      item._basePrice = target;
      changed = true;
    }
  });
  if (changed) renderCart();
}

function renderCartCustomer() {
  const tab = activeTab();
  const bar = $('#cart-customer-bar');
  if (!bar) return;
  if (tab?._customer) {
    const isWholesale = tab._customer.customer_type === 'wholesale';
    const typeBadge   = isWholesale
      ? `<span class="cart-cust-wholesale"><i class="fa fa-boxes-stacked"></i> Wholesale</span>` : '';
    bar.innerHTML = `<i class="fa fa-user" style="color:var(--accent)"></i>
      <span class="cart-cust-name">${escHtml(tab._customer.name)}</span>
      ${typeBadge}
      ${tab._customer.phone ? `<span class="cart-cust-phone">${escHtml(tab._customer.phone)}</span>` : ''}
      <button class="cart-cust-clear" id="cart-cust-clear" title="Remove customer"><i class="fa fa-xmark"></i></button>`;
    bar.style.display = 'flex';
    $('#cart-cust-clear')?.addEventListener('click', () => {
      if (tab) tab._customer = null;
      renderCartCustomer();
      _applyCustomerPricing();
    });
    _applyCustomerPricing();
  } else {
    bar.style.display = 'none';
    bar.innerHTML = '';
  }
}

function openCustomerModal() {
  const modal = $('#cust-modal');
  if (!modal) return;
  modal.style.display = 'flex';
  const input = $('#cust-search-input');
  if (input) { input.value = ''; input.focus(); }
  $('#cust-results').innerHTML = '';
  $('#cust-new-form').style.display = 'none';
  _loadCustomerConfig();
}

async function _searchCustomers(q) {
  const res = await API.customers(q);
  const list = res.body?.data ?? [];
  const el = $('#cust-results');
  if (!el) return;
  if (!list.length) {
    el.innerHTML = `<div class="cust-empty"><i class="fa fa-user-slash"></i> No customers found.<br><a href="#" id="cust-create-link">Create "${escHtml(q)}"</a></div>`;
    $('#cust-create-link')?.addEventListener('click', e => { e.preventDefault(); _showCustomerCreateForm(q); });
    return;
  }
  el.innerHTML = list.map(c => {
    const wsBadge = c.customer_type === 'wholesale'
      ? `<span class="cart-cust-wholesale" style="margin-left:auto"><i class="fa fa-boxes-stacked"></i> Wholesale</span>` : '';
    return `<div class="cust-row" data-id="${c.id}">
      <div class="cust-row-name" style="display:flex;align-items:center;gap:6px">${escHtml(c.name)}${wsBadge}</div>
      ${c.phone ? `<div class="cust-row-meta">${escHtml(c.phone)}</div>` : ''}
    </div>`;
  }).join('');
  el.querySelectorAll('.cust-row').forEach(row => {
    row.addEventListener('click', () => {
      const c = list.find(x => x.id === Number(row.dataset.id));
      if (!c) return;
      const tab = activeTab();
      if (tab) tab._customer = c;
      $('#cust-modal').style.display = 'none';
      renderCartCustomer();
      toast(`Customer: ${c.name}`, 'success');
    });
  });
}

function _showCustomerCreateForm(prefill) {
  const form = $('#cust-new-form');
  if (!form) return;
  $('#cust-new-name').value    = prefill || '';
  $('#cust-new-phone').value   = '';
  $('#cust-new-email').value   = '';
  $('#cust-new-address').value = '';
  $('#cust-new-phone').placeholder   = _custCfg.requirePhone   ? 'Phone *'   : 'Phone (optional)';
  $('#cust-new-email').placeholder   = _custCfg.requireEmail   ? 'Email *'   : 'Email (optional)';
  $('#cust-new-address').placeholder = _custCfg.requireAddress ? 'Address *' : 'Address (optional)';
  _setCategoryComboValue('#cust-new-category-input', '#cust-new-category', '');
  form.style.display = '';
  $('#cust-new-name').focus();
}

$('#cust-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) $('#cust-modal').style.display = 'none'; });
$('#cust-modal-close')?.addEventListener('click', () => { $('#cust-modal').style.display = 'none'; });
$('#cust-show-create')?.addEventListener('click', () => _showCustomerCreateForm(''));

$('#cust-search-input')?.addEventListener('input', e => {
  clearTimeout(_custSearchTimer);
  const q = e.target.value.trim();
  if (q.length < 1) { $('#cust-results').innerHTML = ''; return; }
  _custSearchTimer = setTimeout(() => _searchCustomers(q), 300);
});

$('#cust-search-input')?.addEventListener('keydown', e => {
  if (e.key === 'Escape') { $('#cust-modal').style.display = 'none'; e.preventDefault(); }
  if (e.key === 'Enter') {
    const first = $('#cust-results .cust-row');
    if (first) first.click();
  }
});

$('#cust-new-cancel')?.addEventListener('click', () => { $('#cust-new-form').style.display = 'none'; });

$('#cust-new-save')?.addEventListener('click', async () => {
  const name          = $('#cust-new-name')?.value.trim();
  const phone         = $('#cust-new-phone')?.value.trim();
  const email         = $('#cust-new-email')?.value.trim();
  const address       = $('#cust-new-address')?.value.trim();
  const customer_type = $('input[name="cust-new-type"]:checked')?.value || 'retail';
  const customer_category_id = $('#cust-new-category')?.value || null;
  if (!name) { toast('Name is required', 'error'); return; }
  if (_custCfg.requirePhone && !phone) { toast('Phone number is required', 'error'); $('#cust-new-phone').focus(); return; }
  if (_custCfg.requireEmail && !email) { toast('Email is required', 'error'); $('#cust-new-email').focus(); return; }
  if (_custCfg.requireAddress && !address) { toast('Address is required', 'error'); $('#cust-new-address').focus(); return; }
  const res = await API.createCustomer({ name, phone: phone || null, email: email || null, address: address || null, customer_type, customer_category_id });
  if (res.status !== 201) { toast('Failed to create customer', 'error'); return; }
  const c = res.body?.data;
  if (!c) return;
  const tab = activeTab();
  if (tab) tab._customer = c;
  $('#cust-modal').style.display = 'none';
  renderCartCustomer();
  toast(`Customer "${c.name}" created and selected`, 'success');
});

$('#cust-new-name')?.addEventListener('keydown', e => {
  if (e.key === 'Enter') $('#cust-new-save')?.click();
  if (e.key === 'Escape') { $('#cust-new-form').style.display = 'none'; e.preventDefault(); }
});

// ── Customers Management Modal ──────────────────────────────────────────────
const _cm = {
  page: 1, lastPage: 1, total: 0,
  searchQ: '', searchTimer: null,
  selectedId: null, editingId: null,
  list: [],
};

let _cmReturnToSaleWizard = false;

function openCustomersModal() {
  $('#customers-modal').style.display = 'flex';
  _cmReturnToSaleWizard = false;
  _cm.page = 1; _cm.searchQ = ''; _cm.selectedId = null; _cm.editingId = null;
  $('#cm-search').value = '';
  _cmShowDetail(false); _cmShowForm(false);
  _cmLoadList();
  _loadCustomerConfig();
  requestAnimationFrame(() => $('#cm-search').focus());
}

function _cmClose() {
  $('#customers-modal').style.display = 'none';
  if (_cmReturnToSaleWizard) {
    _cmReturnToSaleWizard = false;
    $('#sale-wizard').style.display = 'flex';
  }
}

async function _cmLoadList() {
  const list = $('#cm-list');
  list.innerHTML = '<div class="cm-list-empty"><i class="fa fa-spinner fa-spin"></i></div>';
  const res = await API.customers(_cm.searchQ, _cm.page);
  if (res.status !== 200) { list.innerHTML = '<div class="cm-list-empty"><i class="fa fa-triangle-exclamation"></i> Failed to load</div>'; return; }
  _cm.list      = res.body?.data ?? [];
  _cm.lastPage  = res.body?.meta?.last_page ?? 1;
  _cm.total     = res.body?.meta?.total ?? _cm.list.length;
  _cmRenderList();
  _cmRenderPagination();
}

function _cmRenderList() {
  const list = $('#cm-list');
  if (!_cm.list.length) {
    list.innerHTML = `<div class="cm-list-empty"><i class="fa fa-user-slash"></i><span>${_cm.searchQ ? 'No results' : 'No customers yet'}</span></div>`;
    return;
  }
  list.innerHTML = _cm.list.map(c => {
    const initial = (c.name || '?')[0].toUpperCase();
    const sub     = c.phone || c.email || '';
    const wsBadge = c.customer_type === 'wholesale'
      ? `<span class="cart-cust-wholesale" style="font-size:9.5px"><i class="fa fa-boxes-stacked"></i> WS</span>` : '';
    return `<div class="cm-item${c.id === _cm.selectedId ? ' active' : ''}" data-id="${c.id}">
      <div class="cm-item-avatar">${escHtml(initial)}</div>
      <div class="cm-item-body">
        <div class="cm-item-name" style="display:flex;align-items:center;gap:6px">${escHtml(c.name)}${wsBadge}</div>
        ${sub ? `<div class="cm-item-sub">${escHtml(sub)}</div>` : ''}
      </div>
    </div>`;
  }).join('');

  list.querySelectorAll('.cm-item').forEach(el => {
    el.addEventListener('click', () => _cmSelectCustomer(Number(el.dataset.id)));
  });
}

function _cmRenderPagination() {
  const el = $('#cm-pagination');
  if (_cm.lastPage <= 1) { el.innerHTML = `<span>${_cm.total} customer${_cm.total !== 1 ? 's' : ''}</span>`; return; }
  el.innerHTML = `
    <button class="cm-page-btn" id="cm-pg-prev" ${_cm.page <= 1 ? 'disabled' : ''}><i class="fa fa-chevron-left"></i></button>
    <span>${_cm.page} / ${_cm.lastPage}</span>
    <button class="cm-page-btn" id="cm-pg-next" ${_cm.page >= _cm.lastPage ? 'disabled' : ''}><i class="fa fa-chevron-right"></i></button>`;
  $('#cm-pg-prev')?.addEventListener('click', () => { if (_cm.page > 1) { _cm.page--; _cmLoadList(); } });
  $('#cm-pg-next')?.addEventListener('click', () => { if (_cm.page < _cm.lastPage) { _cm.page++; _cmLoadList(); } });
}

async function _cmSelectCustomer(id) {
  _cm.selectedId = id;
  _cm.editingId  = null;
  _cmRenderList();
  _cmShowForm(false);
  _cmShowDetail(true);
  const pane = $('#cm-detail-view');
  if (pane) pane.style.opacity = '.5';

  const res = await API.customer(id);
  if (res.status !== 200) { _cmShowDetail(false); return; }
  const c = res.body?.data;
  if (!c) return;

  if (pane) pane.style.opacity = '1';
  const init = (c.name || '?')[0].toUpperCase();
  $('#cm-dv-avatar').textContent = init;
  $('#cm-dv-name').textContent   = c.name;
  $('#cm-dv-sales-badge').textContent = `${c.sales_count ?? 0} sale${(c.sales_count ?? 0) !== 1 ? 's' : ''}`;

  const isWholesaleCust = c.customer_type === 'wholesale';
  const typeVal = isWholesaleCust
    ? '<span class="cart-cust-wholesale"><i class="fa fa-boxes-stacked"></i> Wholesale</span>'
    : '<span style="color:var(--text-muted)">Retail</span>';
  const fields = [
    { label: 'Type',     val: typeVal, raw: true },
    { label: 'Category', val: c.category_name },
    { label: 'Phone',    val: c.phone },
    { label: 'Email',    val: c.email },
    { label: 'Address',  val: c.address },
    { label: 'Notes',    val: c.notes },
  ];
  $('#cm-dv-fields').innerHTML = fields.map(f => `
    <div class="cm-dv-field">
      <div class="cm-dv-field-label">${f.label}</div>
      <div class="cm-dv-field-val${f.val ? '' : ' empty'}">${f.val ? (f.raw ? f.val : escHtml(f.val)) : '—'}</div>
    </div>`).join('');

  const history = $('#cm-dv-history');
  if (c.recent_sales?.length) {
    history.innerHTML = `<div class="cm-dv-history-title"><i class="fa fa-clock-rotate-left"></i> Recent Sales</div>` +
      c.recent_sales.map(s => `
        <div class="cm-dv-sale-row">
          <span class="cm-dv-sale-num">${escHtml(s.sale_number || `#${s.id}`)}</span>
          <span class="cm-dv-sale-date">${s.sold_at ? s.sold_at.slice(0, 10) : ''}</span>
          <span class="cm-dv-sale-amt">${parseFloat(s.total || 0).toFixed(2)}</span>
        </div>`).join('');
  } else {
    history.innerHTML = '<div class="cm-dv-no-sales"><i class="fa fa-receipt"></i> No sales yet</div>';
  }
}

function _cmShowDetail(show) {
  $('#cm-detail-empty').style.display = show ? 'none' : '';
  $('#cm-detail-view').style.display  = show ? 'flex' : 'none';
}

function _cmShowForm(show, customer = null) {
  $('#cm-form-view').style.display   = show ? 'flex' : 'none';
  $('#cm-detail-empty').style.display = (!show && !_cm.selectedId) ? '' : 'none';
  $('#cm-detail-view').style.display  = (!show && _cm.selectedId) ? 'flex' : 'none';

  if (show) {
    const isEdit = customer !== null;
    $('#cm-form-title').textContent  = isEdit ? 'Edit Customer' : 'New Customer';
    $('#cm-f-name').value    = customer?.name    ?? '';
    $('#cm-f-phone').value   = customer?.phone   ?? '';
    $('#cm-f-email').value   = customer?.email   ?? '';
    $('#cm-f-address').value = customer?.address ?? '';
    $('#cm-f-notes').value   = customer?.notes   ?? '';
    const custType = customer?.customer_type ?? 'retail';
    const typeRadio = $(`input[name="cm-customer-type"][value="${custType}"]`);
    if (typeRadio) typeRadio.checked = true;
    _setCategoryComboValue('#cm-f-category-input', '#cm-f-category', customer?.customer_category_id ?? '');
    _applyCustomerFieldRequirements();
    requestAnimationFrame(() => $('#cm-f-name').focus());
  }
}

async function _cmSave() {
  const name          = $('#cm-f-name').value.trim();
  const phone         = $('#cm-f-phone').value.trim() || null;
  const email         = $('#cm-f-email').value.trim() || null;
  const address       = $('#cm-f-address').value.trim() || null;
  const notes         = $('#cm-f-notes').value.trim() || null;
  const customer_type = $('input[name="cm-customer-type"]:checked')?.value || 'retail';
  const customer_category_id = $('#cm-f-category')?.value || null;

  if (!name) { toast('Name is required', 'error'); $('#cm-f-name').focus(); return; }
  if (_custCfg.requirePhone && !phone) { toast('Phone number is required', 'error'); $('#cm-f-phone').focus(); return; }
  if (_custCfg.requireEmail && !email) { toast('Email is required', 'error'); $('#cm-f-email').focus(); return; }
  if (_custCfg.requireAddress && !address) { toast('Address is required', 'error'); $('#cm-f-address').focus(); return; }

  const btn = $('#cm-form-save');
  btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Saving…';

  const payload = { name, phone, email, address, notes, customer_type, customer_category_id };
  let res;
  if (_cm.editingId) {
    res = await API.updateCustomer(_cm.editingId, payload);
  } else {
    res = await API.createCustomer(payload);
  }

  btn.disabled = false; btn.innerHTML = '<i class="fa fa-check"></i> Save';

  if (res.status !== 200 && res.status !== 201) {
    const msg = res.body?.errors?.name?.[0] || res.body?.message || 'Failed to save';
    toast(msg, 'error'); return;
  }

  const c = res.body?.data;
  const wasEditing = !!_cm.editingId;
  _cm.editingId = null;

  if (_cmReturnToSaleWizard && !wasEditing) {
    _cmReturnToSaleWizard = false;
    $('#customers-modal').style.display = 'none';
    $('#sale-wizard').style.display = 'flex';
    if (c) _sawSelectCustomer(c.id, c.name);
    toast('Customer saved', 'success');
    return;
  }

  _cmShowForm(false);
  await _cmLoadList();
  if (c) { _cm.selectedId = c.id; _cmRenderList(); _cmSelectCustomer(c.id); }
  toast(wasEditing ? 'Customer updated' : 'Customer saved', 'success');
}

async function _cmDelete() {
  if (!_cm.selectedId) return;
  const c = _cm.list.find(x => x.id === _cm.selectedId);
  if (!confirm(`Delete "${c?.name ?? 'this customer'}"? This cannot be undone.`)) return;
  const res = await API.deleteCustomer(_cm.selectedId);
  if (res.status !== 200 && res.status !== 204) { toast('Failed to delete', 'error'); return; }
  _cm.selectedId = null;
  _cmShowDetail(false);
  _cmLoadList();
  toast('Customer deleted', 'success');
}

// Wire modal controls
$('#cm-close')?.addEventListener('click', _cmClose);
$('#customers-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) _cmClose(); });

$('#cm-new-btn')?.addEventListener('click', () => {
  _cm.editingId = null; _cm.selectedId = null;
  _cmRenderList();
  _cmShowDetail(false);
  _cmShowForm(true);
});

$('#cm-btn-edit')?.addEventListener('click', async () => {
  if (!_cm.selectedId) return;
  const res = await API.customer(_cm.selectedId);
  if (res.status !== 200) return;
  const c = res.body?.data;
  _cm.editingId = _cm.selectedId;
  _cmShowForm(true, c);
});

$('#cm-btn-assign')?.addEventListener('click', () => {
  const c = _cm.list.find(x => x.id === _cm.selectedId);
  if (!c) return;
  const tab = activeTab();
  if (tab) tab._customer = c;
  renderCartCustomer();
  _cmClose();
  toast(`Customer "${c.name}" assigned to sale`, 'success');
});

$('#cm-btn-delete')?.addEventListener('click', _cmDelete);

$('#cm-form-cancel')?.addEventListener('click', () => {
  if (_cmReturnToSaleWizard) { _cmClose(); return; }
  _cm.editingId = null;
  _cmShowForm(false);
  if (_cm.selectedId) _cmShowDetail(true);
});

$('#cm-form-save')?.addEventListener('click', _cmSave);

$('#cm-search')?.addEventListener('input', e => {
  clearTimeout(_cm.searchTimer);
  _cm.searchQ = e.target.value.trim();
  _cm.page = 1;
  _cm.searchTimer = setTimeout(_cmLoadList, 300);
});

$('#cm-search')?.addEventListener('keydown', e => {
  if (e.key === 'Escape') { e.preventDefault(); if (_cm.searchQ) { _cm.searchQ = ''; e.target.value = ''; _cm.page = 1; _cmLoadList(); } else _cmClose(); }
  if (e.key === 'Enter' && _cm.list.length) { _cmSelectCustomer(_cm.list[0].id); }
});

['#cm-f-name','#cm-f-phone','#cm-f-email','#cm-f-address','#cm-f-notes'].forEach(sel => {
  $(sel)?.addEventListener('keydown', e => { if (e.key === 'Enter' && sel !== '#cm-f-notes') _cmSave(); if (e.key === 'Escape') $('#cm-form-cancel')?.click(); });
});

// ── Customer required-field settings + Customer Categories ─────────────────
const _custCfg = { requirePhone: false, requireEmail: false, requireAddress: false, categories: [] };

async function _loadCustomerConfig() {
  try {
    const [sRes, cRes] = await Promise.all([API.settingsGet(), API.customerCategories()]);
    const s = sRes.body?.data ?? {};
    _custCfg.requirePhone   = !!s.customer_require_phone;
    _custCfg.requireEmail   = !!s.customer_require_email;
    _custCfg.requireAddress = !!s.customer_require_address;
    _custCfg.categories     = cRes.body?.data ?? [];
  } catch (_) {}
  _applyCustomerFieldRequirements();
}

function _applyCustomerFieldRequirements() {
  const map = { '#cm-req-phone': _custCfg.requirePhone, '#cm-req-email': _custCfg.requireEmail, '#cm-req-address': _custCfg.requireAddress };
  Object.entries(map).forEach(([sel, required]) => {
    const el = $(sel);
    if (el) el.style.display = required ? '' : 'none';
  });
}

// ── Category combobox: searchable, scrollable replacement for a plain <select> ──
function _setCategoryComboValue(inputSel, hiddenSel, id) {
  const cat = id ? _custCfg.categories.find(c => c.id === Number(id)) : null;
  const hidden = $(hiddenSel), input = $(inputSel);
  if (hidden) hidden.value = cat ? cat.id : '';
  if (input)  input.value  = cat ? cat.name : '';
}

function _catComboRender(listEl, inputSel, hiddenSel, filter) {
  const q = (filter || '').trim().toLowerCase();
  const items = _custCfg.categories.filter(c => c.name.toLowerCase().includes(q));
  let html = `<div class="cat-combo-item" data-id="" data-name="">No category</div>`;
  html += items.map(c => `<div class="cat-combo-item" data-id="${c.id}" data-name="${escHtml(c.name)}">${escHtml(c.name)}</div>`).join('');
  if (!items.length && q) html += '<div class="cat-combo-empty">No matching categories</div>';
  listEl.innerHTML = html;
  listEl.querySelectorAll('.cat-combo-item[data-id]').forEach(el => {
    el.addEventListener('mousedown', ev => {
      ev.preventDefault();
      $(hiddenSel).value = el.dataset.id;
      $(inputSel).value  = el.dataset.name || '';
      listEl.style.display = 'none';
    });
  });
}

function _wireCategoryCombo(inputSel, hiddenSel, listSel) {
  const input = $(inputSel), list = $(listSel);
  if (!input || !list) return;
  input.addEventListener('focus', () => { _catComboRender(list, inputSel, hiddenSel, ''); list.style.display = ''; });
  input.addEventListener('input', () => {
    $(hiddenSel).value = '';
    _catComboRender(list, inputSel, hiddenSel, input.value);
    list.style.display = '';
  });
  input.addEventListener('blur', () => { setTimeout(() => { list.style.display = 'none'; }, 150); });
  input.addEventListener('keydown', e => { if (e.key === 'Escape') { list.style.display = 'none'; input.blur(); } });
}

_wireCategoryCombo('#cm-f-category-input',     '#cm-f-category',     '#cm-f-category-list');
_wireCategoryCombo('#cust-new-category-input', '#cust-new-category', '#cust-new-category-list');

function _cstRenderCategoryList() {
  const el = $('#cst-cat-list');
  if (!el) return;
  if (!_custCfg.categories.length) {
    el.innerHTML = '<div class="cm-list-empty"><i class="fa fa-tags"></i><span>No categories yet</span></div>';
    return;
  }
  el.innerHTML = _custCfg.categories.map(c => `
    <div class="pfs-field-row" data-cat-id="${c.id}">
      <div class="pfs-field-icon"><i class="fa fa-tag"></i></div>
      <div class="pfs-field-body">
        <div class="pfs-field-label">${escHtml(c.name)}</div>
        ${c.description ? `<div class="pfs-field-desc">${escHtml(c.description)}</div>` : ''}
      </div>
      <button class="prod-batch-del" data-edit-cat="${c.id}" title="Edit category" style="color:var(--text-muted)"><i class="fa fa-pen"></i></button>
      <button class="prod-batch-del" data-del-cat="${c.id}" title="Delete category"><i class="fa fa-trash"></i></button>
    </div>`).join('');
  el.querySelectorAll('[data-edit-cat]').forEach(btn => {
    btn.addEventListener('click', () => _cstStartEditCategory(Number(btn.dataset.editCat)));
  });
  el.querySelectorAll('[data-del-cat]').forEach(btn => {
    btn.addEventListener('click', () => _cstDeleteCategory(Number(btn.dataset.delCat)));
  });
}

let _cstEditingCatId = null;

function _cstStartEditCategory(id) {
  const cat = _custCfg.categories.find(c => c.id === id);
  if (!cat) return;
  _cstEditingCatId = id;
  $('#cst-cat-name').value = cat.name;
  $('#cst-cat-desc').value = cat.description || '';
  $('#cst-cat-add').innerHTML = '<i class="fa fa-check"></i> Update Category';
  $('#cst-cat-cancel-edit').style.display = '';
  $('#cst-cat-name').focus();
}

function _cstCancelEditCategory() {
  _cstEditingCatId = null;
  $('#cst-cat-name').value = '';
  $('#cst-cat-desc').value = '';
  $('#cst-cat-add').innerHTML = '<i class="fa fa-plus"></i> Add Category';
  $('#cst-cat-cancel-edit').style.display = 'none';
}

// ── Generic confirm dialog (custom, replaces window.confirm) ───────────────
let _cstConfirmResolve = null;

function _cstConfirm(message, title = 'Are you sure?') {
  return new Promise(resolve => {
    _cstConfirmResolve = resolve;
    $('#cst-confirm-title').textContent = title;
    $('#cst-confirm-msg').textContent   = message;
    $('#cst-confirm-modal').style.display = 'flex';
  });
}

function _cstConfirmClose(result) {
  $('#cst-confirm-modal').style.display = 'none';
  if (_cstConfirmResolve) { _cstConfirmResolve(result); _cstConfirmResolve = null; }
}

$('#cst-confirm-ok')?.addEventListener('click',     () => _cstConfirmClose(true));
$('#cst-confirm-cancel')?.addEventListener('click', () => _cstConfirmClose(false));
$('#cst-confirm-close')?.addEventListener('click',  () => _cstConfirmClose(false));
$('#cst-confirm-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) _cstConfirmClose(false); });

async function _cstDeleteCategory(id) {
  const cat = _custCfg.categories.find(c => c.id === id);
  const ok = await _cstConfirm(`Delete category "${cat?.name ?? ''}"? This cannot be undone.`, 'Delete Category');
  if (!ok) return;
  const res = await API.deleteCustomerCategory(id);
  if (res.status !== 200 && res.status !== 204) {
    toast(res.body?.message || 'Failed to delete category', 'error');
    return;
  }
  _custCfg.categories = _custCfg.categories.filter(c => c.id !== id);
  if (_cstEditingCatId === id) _cstCancelEditCategory();
  _cstRenderCategoryList();
  toast('Category deleted', 'success');
}

function _cstSyncTabs() {
  const active = $('#cust-settings-nav .pfs-opt-tab.active')?.dataset.cstTab || 'general';
  $('#cst-panel-general').style.display  = active === 'general'  ? '' : 'none';
  $('#cst-panel-category').style.display = active === 'category' ? '' : 'none';
}

async function _openCustomerSettingsModal() {
  const modal = $('#cust-settings-modal');
  if (!modal) return;
  await _loadCustomerConfig();
  $('#cst-req-phone').checked   = _custCfg.requirePhone;
  $('#cst-req-email').checked   = _custCfg.requireEmail;
  $('#cst-req-address').checked = _custCfg.requireAddress;
  _cstCancelEditCategory();
  _cstRenderCategoryList();
  $$('#cust-settings-nav .pfs-opt-tab').forEach(b => b.classList.toggle('active', b.dataset.cstTab === 'general'));
  _cstSyncTabs();
  modal.style.display = 'flex';
}

$('#cm-settings-btn')?.addEventListener('click', _openCustomerSettingsModal);

$('#cust-settings-nav')?.addEventListener('click', e => {
  const btn = e.target.closest('.pfs-opt-tab[data-cst-tab]');
  if (!btn) return;
  $$('#cust-settings-nav .pfs-opt-tab').forEach(b => b.classList.toggle('active', b === btn));
  _cstSyncTabs();
});

$('#cust-settings-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) $('#cust-settings-modal').style.display = 'none'; });
$('#cust-settings-close')?.addEventListener('click', () => { $('#cust-settings-modal').style.display = 'none'; });
$('#cust-settings-cancel')?.addEventListener('click', () => { $('#cust-settings-modal').style.display = 'none'; });

$('#cst-cat-add')?.addEventListener('click', async () => {
  const name = $('#cst-cat-name')?.value.trim();
  const description = $('#cst-cat-desc')?.value.trim() || null;
  if (!name) { toast('Category name is required', 'error'); $('#cst-cat-name')?.focus(); return; }

  const isEdit = !!_cstEditingCatId;
  const btn = $('#cst-cat-add');
  btn.disabled = true; btn.innerHTML = `<i class="fa fa-spinner fa-spin"></i> ${isEdit ? 'Updating…' : 'Adding…'}`;
  const res = isEdit
    ? await API.updateCustomerCategory(_cstEditingCatId, { name, description })
    : await API.createCustomerCategory({ name, description });
  btn.disabled = false;

  if ((isEdit && res.status !== 200) || (!isEdit && res.status !== 201)) {
    btn.innerHTML = isEdit ? '<i class="fa fa-check"></i> Update Category' : '<i class="fa fa-plus"></i> Add Category';
    toast(res.body?.errors?.name?.[0] || res.body?.message || `Failed to ${isEdit ? 'update' : 'add'} category`, 'error');
    return;
  }

  const c = res.body?.data;
  if (isEdit) {
    const idx = _custCfg.categories.findIndex(x => x.id === _cstEditingCatId);
    if (idx !== -1 && c) _custCfg.categories[idx] = c;
  } else if (c) {
    _custCfg.categories.push(c);
  }
  _custCfg.categories.sort((a, b) => a.name.localeCompare(b.name));
  _cstRenderCategoryList();
  toast(`Category "${c?.name ?? name}" ${isEdit ? 'updated' : 'added'}`, 'success');
  _cstCancelEditCategory();
});

$('#cst-cat-cancel-edit')?.addEventListener('click', _cstCancelEditCategory);

$('#cust-settings-save')?.addEventListener('click', async () => {
  const btn = $('#cust-settings-save');
  btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Saving…';
  const res = await API.settingsUpdate({
    customer_require_phone:   $('#cst-req-phone').checked,
    customer_require_email:   $('#cst-req-email').checked,
    customer_require_address: $('#cst-req-address').checked,
  });
  btn.disabled = false; btn.innerHTML = '<i class="fa fa-check"></i> Save';
  if (res.status !== 200) { toast('Failed to save settings', 'error'); return; }
  _custCfg.requirePhone   = $('#cst-req-phone').checked;
  _custCfg.requireEmail   = $('#cst-req-email').checked;
  _custCfg.requireAddress = $('#cst-req-address').checked;
  _applyCustomerFieldRequirements();
  $('#cust-settings-modal').style.display = 'none';
  toast('Customer settings saved', 'success');
});

// ── CSV Customer Import ──────────────────────────────────────────────────────
const _CUST_CSV_SAMPLE = [
  'name,phone,email,address,notes,category,customer_type',
  'John Silva,0771234567,john.silva@example.com,"123 Main St, Colombo",Prefers SMS updates,VIP,retail',
  'Nimal Perera,0719876543,nimal.perera@example.com,"45 Galle Rd, Kandy",,Regular,retail',
  'Priya Fernando,0765555555,,,"Wholesale buyer",Wholesale,wholesale',
].join('\n');

// Column name aliases → canonical key
const _CUST_CSV_COL_MAP = {
  'name': 'name', 'customer name': 'name', 'customer': 'name', 'full name': 'name',
  'phone': 'phone', 'phone number': 'phone', 'mobile': 'phone', 'contact': 'phone', 'contact number': 'phone',
  'email': 'email', 'email address': 'email',
  'address': 'address',
  'notes': 'notes', 'note': 'notes', 'remarks': 'notes',
  'category': 'category', 'customer category': 'category',
  'customer_type': 'customer_type', 'type': 'customer_type', 'customer type': 'customer_type',
};

let _custCsvParsedRows = [];
let _custCsvValidRows  = [];

function _custCsvParseFile(text) {
  const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n').filter(l => l.trim());
  if (lines.length < 2) return { headers: [], rows: [], error: 'File must have a header row and at least one data row.' };

  const headers = _csvParseLine(lines[0]).map(h => h.trim().toLowerCase());
  const colMap  = {};
  headers.forEach((h, i) => { if (_CUST_CSV_COL_MAP[h]) colMap[_CUST_CSV_COL_MAP[h]] = i; });

  if (colMap['name'] === undefined) {
    return { headers, rows: [], error: 'Missing required column: "name" (or "customer", "full name").' };
  }

  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cells = _csvParseLine(lines[i]);
    const row   = {};
    Object.entries(colMap).forEach(([key, ci]) => { row[key] = (cells[ci] || '').trim(); });
    row._rowNum = i + 1;

    // Validate
    row._errors = [];
    if (!row.name) row._errors.push('Name is required');
    if (_custCfg.requirePhone   && !row.phone)   row._errors.push('Phone number is required');
    if (_custCfg.requireEmail   && !row.email)   row._errors.push('Email is required');
    if (_custCfg.requireAddress && !row.address) row._errors.push('Address is required');
    if (row.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(row.email)) row._errors.push('Invalid email');
    if (row.customer_type && !['retail', 'wholesale'].includes(row.customer_type.toLowerCase())) {
      row._errors.push('customer_type must be "retail" or "wholesale"');
    } else {
      row.customer_type = (row.customer_type || 'retail').toLowerCase();
    }

    rows.push(row);
  }
  return { headers: Object.keys(colMap), rows };
}

function _custCsvSetStep(n) {
  [1, 2, 3].forEach(i => {
    const body = $(`#cust-csv-step-${i}`);
    const ind  = $(`#cust-csv-step-ind-${i}`);
    if (body) body.style.display = i === n ? 'flex' : 'none';
    if (ind)  {
      ind.classList.toggle('active', i === n);
      ind.classList.toggle('done',   i < n);
    }
  });
}

function _custCsvShowPreview(rows) {
  const valid = rows.filter(r => !r._errors.length);
  const bad   = rows.filter(r => r._errors.length);
  _custCsvValidRows = valid;

  // Summary badges
  const sumEl = $('#cust-csv-preview-summary');
  sumEl.innerHTML = `
    <b>${rows.length} row${rows.length !== 1 ? 's' : ''} found</b>
    <span class="csv-preview-badge ok"><i class="fa fa-circle-check"></i> ${valid.length} valid</span>
    ${bad.length ? `<span class="csv-preview-badge error"><i class="fa fa-triangle-exclamation"></i> ${bad.length} with errors</span>` : ''}
    ${rows.length > 100 ? `<span class="csv-preview-badge warn"><i class="fa fa-eye"></i> Showing first 100 rows</span>` : ''}`;

  // Table
  const display = rows.slice(0, 100);
  $('#cust-csv-preview-thead').innerHTML = `<tr>
    <th>#</th><th>Name</th><th>Phone</th><th>Email</th><th>Address</th>
    <th>Category</th><th>Type</th><th>Status</th>
  </tr>`;
  $('#cust-csv-preview-tbody').innerHTML = display.map(r => {
    const isErr = r._errors.length > 0;
    const status = isErr
      ? `<span class="csv-row-error-msg"><i class="fa fa-triangle-exclamation"></i> ${escHtml(r._errors.join('; '))}</span>`
      : `<span style="color:#10b981;font-size:11px"><i class="fa fa-circle-check"></i> OK</span>`;
    return `<tr class="${isErr ? 'csv-row-error' : ''}">
      <td style="color:var(--text-muted)">${r._rowNum}</td>
      <td><strong>${escHtml(r.name || '—')}</strong></td>
      <td style="color:var(--text-muted)">${escHtml(r.phone || '—')}</td>
      <td style="color:var(--text-muted)">${escHtml(r.email || '—')}</td>
      <td style="color:var(--text-muted)">${escHtml(r.address || '—')}</td>
      <td>${escHtml(r.category || '—')}</td>
      <td>${escHtml(r.customer_type || 'retail')}</td>
      <td>${status}</td>
    </tr>`;
  }).join('');

  $('#cust-csv-import-count').textContent = valid.length;
  $('#cust-csv-import-btn').disabled = valid.length === 0;
  _custCsvSetStep(2);
}

