// ── Custom Requirement prompt (services) ────────────────────────────────────
let _askCreqResolve  = null;
let _creqActiveFields = [];

function _askCustomRequirement(service) {
  return new Promise(resolve => {
    _askCreqResolve   = resolve;
    _creqActiveFields = service.custom_requirement_fields || [];
    $('#pos-custom-req-service-name').textContent = service.name;

    const body = $('#pos-custom-req-fields');
    body.innerHTML = _creqActiveFields.map(f => {
      const key = escHtml(f.key);
      if (f.type === 'textarea') {
        return `<div class="psm-field-row" style="margin:0 0 12px">
          <label class="psm-field-label">${escHtml(f.label)}</label>
          <textarea class="psm-input pos-creq-input" data-key="${key}" rows="3" style="resize:vertical"></textarea>
        </div>`;
      }
      if (f.type === 'select') {
        const opts = (f.options || []).map(o => `<option value="${escHtml(o)}">${escHtml(o)}</option>`).join('');
        return `<div class="psm-field-row" style="margin:0 0 12px">
          <label class="psm-field-label">${escHtml(f.label)}</label>
          <select class="psm-input pos-creq-input" data-key="${key}">
            <option value="">— Select —</option>${opts}
          </select>
        </div>`;
      }
      if (f.type === 'radio') {
        const opts = (f.options || []).map(o => `
          <label style="display:flex;align-items:center;gap:6px;font-size:13px;color:var(--text);margin-top:6px;cursor:pointer">
            <input type="radio" name="creq_${key}" class="pos-creq-radio" data-key="${key}" value="${escHtml(o)}"> ${escHtml(o)}
          </label>`).join('');
        return `<div class="psm-field-row" style="margin:0 0 12px">
          <label class="psm-field-label">${escHtml(f.label)}</label>
          ${opts || '<span style="font-size:12px;color:var(--text-muted)">No options configured.</span>'}
        </div>`;
      }
      if (f.type === 'checkbox') {
        return `<div class="psm-field-row" style="margin:0 0 12px">
          <label style="display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text);cursor:pointer">
            <input type="checkbox" class="pos-creq-checkbox" data-key="${key}"> ${escHtml(f.label)}
          </label>
        </div>`;
      }
      if (f.type === 'number') {
        return `<div class="psm-field-row" style="margin:0 0 12px">
          <label class="psm-field-label">${escHtml(f.label)}</label>
          <input type="number" class="psm-input pos-creq-input" data-key="${key}">
        </div>`;
      }
      if (f.type === 'date') {
        return `<div class="psm-field-row" style="margin:0 0 12px">
          <label class="psm-field-label">${escHtml(f.label)}</label>
          <input type="date" class="psm-input pos-creq-input" data-key="${key}">
        </div>`;
      }
      return `<div class="psm-field-row" style="margin:0 0 12px">
        <label class="psm-field-label">${escHtml(f.label)}</label>
        <input type="text" class="psm-input pos-creq-input" data-key="${key}">
      </div>`;
    }).join('');

    $('#pos-custom-req-overlay').style.display = 'flex';
    setTimeout(() => body.querySelector('.pos-creq-input')?.focus(), 60);
  });
}

function _creqResolve(result) {
  $('#pos-custom-req-overlay').style.display = 'none';
  if (_askCreqResolve) { const r = _askCreqResolve; _askCreqResolve = null; r(result); }
}

$('#pos-custom-req-confirm').addEventListener('click', () => {
  const values = _creqActiveFields.map(f => {
    let value = '';
    if (f.type === 'checkbox') {
      const cb = $(`#pos-custom-req-fields .pos-creq-checkbox[data-key="${CSS.escape(f.key)}"]`);
      value = cb && cb.checked ? 'Yes' : 'No';
    } else if (f.type === 'radio') {
      const checked = $(`#pos-custom-req-fields input[name="creq_${CSS.escape(f.key)}"]:checked`);
      value = checked ? checked.value : '';
    } else {
      const input = $(`#pos-custom-req-fields .pos-creq-input[data-key="${CSS.escape(f.key)}"]`);
      value = input ? input.value.trim() : '';
    }
    return { key: f.key, label: f.label, type: f.type, value };
  });
  _creqResolve(values);
});
$('#pos-custom-req-cancel').addEventListener('click', () => _creqResolve(null));
$('#pos-custom-req-overlay').addEventListener('click', e => {
  if (e.target === e.currentTarget) _creqResolve(null);
});
// ── End Custom Requirement prompt ───────────────────────────────────────────

// ── Stock layer picker ─────────────────────────────────────────────────────
let _layerPickerResolve = null;

function _fmtQty(n) { return String((parseFloat(n) || 0).toFixed(3)).replace(/\.?0+$/, ''); }

function posLayersDifferInPrice(layers) {
  if (!layers || layers.length < 2) return false;
  const first = Number(layers[0].unit_sell_price || 0).toFixed(2);
  for (let i = 1; i < layers.length; i++) {
    if (Number(layers[i].unit_sell_price || 0).toFixed(2) !== first) return true;
  }
  return false;
}

function openPosLayerPicker() {
  const m = $('#pos-layer-picker');
  if (m) { m.style.display = ''; m.classList.add('is-open'); m.setAttribute('aria-hidden', 'false'); }
  requestAnimationFrame(() => _lpHighlight(0));
}

function closePosLayerPicker() {
  _lpClear();
  const m = $('#pos-layer-picker');
  if (m) { m.classList.remove('is-open'); m.setAttribute('aria-hidden', 'true'); }
  if (_layerPickerResolve) { const r = _layerPickerResolve; _layerPickerResolve = null; r(null); }
}

$('#pos-layer-picker-cancel').addEventListener('click', closePosLayerPicker);
$('#pos-layer-picker-backdrop').addEventListener('click', closePosLayerPicker);

let _lpSelIdx = -1;

function _lpOptions() {
  return [...$$('#pos-layer-picker-list .pos-layer-picker__option')];
}

function _lpHighlight(idx) {
  const opts = _lpOptions();
  if (!opts.length) return;
  _lpSelIdx = Math.max(0, Math.min(opts.length - 1, idx));
  opts.forEach((o, i) => o.classList.toggle('kbd-active', i === _lpSelIdx));
  opts[_lpSelIdx].scrollIntoView({ block: 'nearest', behavior: 'smooth' });
}

function _lpClear() {
  _lpSelIdx = -1;
  _lpOptions().forEach(o => o.classList.remove('kbd-active'));
}

document.addEventListener('keydown', e => {
  if (!$('#pos-layer-picker')?.classList.contains('is-open')) return;

  if (e.key === 'Escape')     { e.preventDefault(); closePosLayerPicker(); return; }
  if (e.key === 'ArrowDown')  { e.preventDefault(); _lpHighlight(_lpSelIdx < 0 ? 0 : _lpSelIdx + 1); return; }
  if (e.key === 'ArrowUp')    { e.preventDefault(); _lpHighlight(_lpSelIdx < 0 ? 0 : _lpSelIdx - 1); return; }
  if (e.key === 'Enter' && _lpSelIdx >= 0) {
    e.preventDefault();
    _lpOptions()[_lpSelIdx]?.click();
  }
});

function posPickStockLayer(product, layers) {
  return new Promise(resolve => {
    const subtitleEl = $('#pos-layer-picker-subtitle');
    const listEl     = $('#pos-layer-picker-list');
    if (!listEl || !layers?.length) { resolve(null); return; }

    // Group same-price batches into one row
    const priceMap = {};
    layers.forEach(l => {
      const key = Number(l.unit_sell_price || 0).toFixed(2);
      (priceMap[key] = priceMap[key] || []).push(l);
    });
    const opts = Object.values(priceMap).map(group => {
      if (group.length === 1) return { layer: group[0], merged: false };
      const totalStock = group.reduce((s, l) => s + (parseFloat(l.quantity_remaining) || 0), 0);
      return {
        layer: { ...group[0], quantity_remaining: totalStock },
        merged: true,
        mergedLabel: `${group[0].label || 'Batch #' + group[0].id} + ${group.length - 1} more batch${group.length > 2 ? 'es' : ''}`,
        batchCount: group.length,
        totalStock,
      };
    });

    // Auto-pick if only one price option remains
    if (opts.length === 1) { resolve(opts[0].layer); return; }

    _layerPickerResolve = resolve;
    if (subtitleEl) subtitleEl.textContent = `${product.name} — choose a batch to add to the cart.`;

    listEl.innerHTML = '';
    opts.forEach(opt => {
      const layer = opt.layer;
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'pos-layer-picker__option';
      const metaText = opt.merged
        ? `${_fmtQty(opt.totalStock)} total in stock (${opt.batchCount} batches)`
        : `${_fmtQty(layer.quantity_remaining)} in stock`;
      btn.innerHTML = `
        <span class="pos-layer-picker__option__main">
          <span class="pos-layer-picker__option__label">${escHtml(opt.merged ? opt.mergedLabel : (layer.label || 'Batch #' + layer.id))}</span>
          <span class="pos-layer-picker__option__meta">${escHtml(metaText)}</span>
        </span>
        <span class="pos-layer-picker__option__price">${parseFloat(layer.unit_sell_price || 0).toFixed(2)}</span>`;
      btn.addEventListener('click', () => {
        _layerPickerResolve = null;
        closePosLayerPicker();
        resolve(layer);
      });
      listEl.appendChild(btn);
    });

    openPosLayerPicker();
  });
}

async function handleProductClick(p) {
  const layers  = p.layers || [];
  const inStock = layers.filter(l => parseFloat(l.quantity_remaining) > 0);
  const stockMode = state.receiptSettings?.stock_selection_mode ?? 'fifo';

  let cartItem;

  const _wholesalePrice = p.wholesale_price != null ? parseFloat(p.wholesale_price) : null;
  const _tab = activeTab();
  const _isWholesale = _tab?._customer?.customer_type === 'wholesale';

  if (stockMode === 'choose' && layers.length > 1) {
    // Manual batch picker
    const pickable = inStock.length > 0 ? inStock : layers;
    const layer = await posPickStockLayer(p, pickable);
    if (!layer) return;
    const retailP = parseFloat(layer.unit_sell_price);
    cartItem = {
      id: p.id, layerId: layer.id, layerLabel: layer.label || `Batch #${layer.id}`,
      name: p.name, price: (_isWholesale && _wholesalePrice != null) ? _wholesalePrice : retailP,
      stock: parseFloat(layer.quantity_remaining),
      _retailPrice: retailP, _wholesalePrice,
    };
  } else if (stockMode === 'last_price' && layers.length > 1) {
    // Use the most recently added in-stock batch (highest id = latest price update)
    const pool  = inStock.length > 0 ? inStock : layers;
    const layer = pool.reduce((best, l) => ((l.id > best.id) ? l : best), pool[0]);
    const retailP = parseFloat(layer.unit_sell_price);
    cartItem = {
      id: p.id, layerId: layer.id, layerLabel: layer.label || `Batch #${layer.id}`,
      name: p.name, price: (_isWholesale && _wholesalePrice != null) ? _wholesalePrice : retailP,
      stock: parseFloat(layer.quantity_remaining),
      _retailPrice: retailP, _wholesalePrice,
    };
  } else if (inStock.length > 0) {
    // FIFO: backend handles layer selection; no layerId pinned so consumeFifo runs server-side
    const layer = inStock[0];
    const retailP = parseFloat(layer.unit_sell_price);
    cartItem = {
      id: p.id, layerId: null, layerLabel: null,
      name: p.name, price: (_isWholesale && _wholesalePrice != null) ? _wholesalePrice : retailP,
      stock: p.stock_quantity != null ? parseFloat(p.stock_quantity) : null,
      _retailPrice: retailP, _wholesalePrice,
    };
  } else if (layers.length >= 1) {
    const layer = layers[0];
    const retailP = parseFloat(layer.unit_sell_price);
    cartItem = {
      id: p.id, layerId: null, layerLabel: null,
      name: p.name, price: (_isWholesale && _wholesalePrice != null) ? _wholesalePrice : retailP,
      stock: 0,
      _retailPrice: retailP, _wholesalePrice,
    };
  } else {
    const retailP = parseFloat(p.discounted_sell_price ?? p.unit_sell_price ?? 0);
    cartItem = {
      id: p.id, layerId: null, layerLabel: null,
      name: p.name, price: (_isWholesale && _wholesalePrice != null) ? _wholesalePrice : retailP,
      stock: p.stock_quantity != null ? parseFloat(p.stock_quantity) : null,
      _retailPrice: retailP, _wholesalePrice,
    };
  }

  // choose_price: ask for the unit price before adding
  if (state.receiptSettings?.choose_price) {
    const overridden = await _askPrice(cartItem.name, cartItem.price);
    if (overridden === null) return; // cancelled
    cartItem.price = overridden;
  }

  // warranty: ask only when adding a new item (not incrementing existing)
  if (p.has_warranty) {
    const tab = activeTab();
    const key = cartItem.layerId != null ? `${cartItem.id}:${cartItem.layerId}` : `${cartItem.id}`;
    const alreadyInCart = tab?.cart.some(i => i._key === key);
    if (!alreadyInCart) {
      if (p.warranty_duration) {
        // Preset duration — auto-apply, no popup
        const wty = _resolveWarrantyFromDuration(p.warranty_duration);
        cartItem.warrantyType = wty.type;
        cartItem.warrantyDate = wty.date ?? null;
      } else {
        // No preset — ask via popup
        const wty = await _askWarranty(cartItem.name);
        if (wty === null) return; // cancelled
        cartItem.warrantyType = wty.type;
        cartItem.warrantyDate = wty.date ?? null;
      }
    }
  }

  addToCart(cartItem);
}

// ── Cart ───────────────────────────────────────────────────────────────────
const _beep = new Audio('sounds/beep.wav');

function addToCart(product) {
  _beep.currentTime = 0;
  _beep.play().catch(() => {});
  const tab = activeTab();
  if (!tab) return;
  const key = product.layerId != null ? `${product.id}:${product.layerId}` : `${product.id}`;
  const existing = tab.cart.find(i => i._key === key);
  if (existing) {
    existing.qty += 1;
  } else {
    tab.cart.push({ ...product, qty: 1, _key: key, _basePrice: product.price, _discountPct: null, _note: null, _retailPrice: product._retailPrice ?? product.price, _wholesalePrice: product._wholesalePrice ?? null });
  }
  renderCart();
  renderPosTabBar();
  // Focus qty input of the item just added/updated
  requestAnimationFrame(() => {
    const input = $(`#cart-items .ci-qty-input[data-key="${CSS.escape(key)}"]`);
    if (input) { input.focus(); input.select(); }
  });
}

// Stable reference so innerHTML wipes never lose the node
const _cartEmptyEl = $('#cart-empty');

function renderCart() {
  const tab    = activeTab();
  const cart   = tab ? tab.cart : [];
  const items  = $('#cart-items');
  const footer = $('#cart-footer');
  const empty  = _cartEmptyEl;

  if (!cart.length) {
    empty.style.display = '';
    footer.style.display = 'none';
    items.innerHTML = '';
    items.appendChild(empty);
    return;
  }

  // Detach empty first so innerHTML swap doesn't destroy it
  if (empty.parentNode) empty.parentNode.removeChild(empty);
  empty.style.display = 'none';
  footer.style.display = '';

  items.innerHTML = cart.map((item, idx) => {
    const discountBadge = item._discountPct > 0
      ? `<span class="ci-badge ci-badge--discount"><i class="fa fa-tag"></i> ${item._discountPct}%</span>` : '';
    const noteBadge = item._note
      ? `<span class="ci-badge ci-badge--note"><i class="fa fa-pen-to-square"></i> ${escHtml(item._note)}</span>` : '';
    const typeBadge = item._type === 'service'
      ? `<span class="ci-badge ci-badge--service"><i class="fa fa-screwdriver-wrench"></i> Service</span>` : '';
    const warrantyBadge = item.warrantyType
      ? `<span class="warranty-badge"><i class="fa fa-shield-halved"></i> ${escHtml(_warrantyLabel(item.warrantyType, item.warrantyDate, null))}</span>` : '';
    const creqBadge = (item.customRequirementValues && item.customRequirementValues.length)
      ? `<span class="ci-badge ci-badge--creq"><i class="fa fa-list-check"></i> Details saved</span>` : '';
    const extras = (discountBadge || noteBadge || typeBadge || warrantyBadge || creqBadge)
      ? `<div class="ci-badges">${typeBadge}${discountBadge}${noteBadge}${warrantyBadge}${creqBadge}</div>` : '';
    return `
    <div class="cart-item" data-key="${escHtml(item._key)}">
      <div class="ci-name">
        ${escHtml(item.name)}
        ${item.layerLabel ? `<div class="ci-layer">${escHtml(item.layerLabel)}</div>` : ''}
        ${extras}
      </div>
      <div class="ci-qty">
        <button class="ci-qty-btn" data-action="dec" data-idx="${idx}">-</button>
        <input class="ci-qty-input" type="number" data-idx="${idx}" value="${item.qty}" min="1" data-key="${escHtml(item._key)}">
        <button class="ci-qty-btn" data-action="inc" data-idx="${idx}">+</button>
      </div>
      <div class="ci-price">${(item.price * item.qty).toFixed(2)}</div>
      <button class="ci-remove" data-action="remove" data-idx="${idx}"><i class="fa fa-xmark"></i></button>
    </div>`;
  }).join('');

  // Click on a cart item row → select it
  items.querySelectorAll('.cart-item').forEach((el, i) => {
    el.addEventListener('click', () => _ciSelect(i));
  });

  // Restore previous selection if the item is still in the cart
  _ciRestoreSelection();

  items.querySelectorAll('.ci-qty-btn, .ci-remove').forEach(btn => {
    btn.addEventListener('click', (e) => { e.stopPropagation(); // don't deselect via row click
      const t = activeTab();
      if (!t) return;
      const idx = Number(btn.dataset.idx);
      if (btn.dataset.action === 'inc')    { t.cart[idx].qty += 1; }
      if (btn.dataset.action === 'dec')    { t.cart[idx].qty = Math.max(1, t.cart[idx].qty - 1); }
      if (btn.dataset.action === 'remove') { t.cart.splice(idx, 1); renderCart(); renderPosTabBar(); return; }
      renderCart();
      renderPosTabBar();
    });
  });

  items.querySelectorAll('.ci-qty-input').forEach(input => {
    input.addEventListener('click', e => e.stopPropagation());
    input.addEventListener('change', () => {
      const t = activeTab();
      if (!t) return;
      const idx = Number(input.dataset.idx);
      const val = parseInt(input.value) || 1;
      t.cart[idx].qty = Math.max(1, val);
      renderCart();
      renderPosTabBar();
    });
    input.addEventListener('keydown', e => {
      if (e.key === 'Enter') { e.preventDefault(); $('#product-search').focus(); }
      if (e.key === 'Escape') { e.preventDefault(); $('#product-search').focus(); }
    });
    // select all on focus for quick overwrite
    input.addEventListener('focus', () => input.select());
  });

  const baseTotal    = cart.reduce((s, i) => s + (i._basePrice ?? i.price) * i.qty, 0);
  const discountAmt  = cart.reduce((s, i) => s + ((i._basePrice ?? i.price) - i.price) * i.qty, 0);
  const subtotal     = baseTotal - discountAmt;
  $('#cart-subtotal').textContent = baseTotal.toFixed(2);
  $('#cart-discount').textContent = discountAmt > 0 ? `-${discountAmt.toFixed(2)}` : '0.00';
  $('#cart-total').textContent = subtotal.toFixed(2);
}

function clearCart() {
  const tab = activeTab();
  if (tab) tab.cart = [];
  renderCart();
  renderPosTabBar();
  toast('Cart cleared', 'info');
}

$('#rb-clear-cart').addEventListener('click', clearCart);
$('#checkout-btn').addEventListener('click', openCheckout);
$('#rb-checkout').addEventListener('click', () => { const t = activeTab(); if (t && t.cart.length) openCheckout(); });
$('#btn-park')?.addEventListener('click', parkCurrentSale);
$('#btn-recall')?.addEventListener('click', openParkedSalesModal);
$('#btn-customer')?.addEventListener('click', openCustomerModal);

function _posCartPrefill() {
  const tab = activeTab();
  if (!tab || !tab.cart.length) { toast('Cart is empty', 'info'); return null; }
  return {
    customerId: tab._customer?.id ?? null,
    items: tab.cart.map(i => ({
      description: i.name,
      quantity:    i.qty,
      unit_price:  i._basePrice ?? i.price,
    })),
  };
}

$('#pos-to-invoice')?.addEventListener('click', () => {
  const prefill = _posCartPrefill();
  if (!prefill) return;
  activateTab('sales');
  _salSwitchView('invoices');
  setTimeout(() => _invOpenForm(null, prefill), 80);
});

$('#pos-to-quote')?.addEventListener('click', () => {
  const prefill = _posCartPrefill();
  if (!prefill) return;
  activateTab('sales');
  _salSwitchView('quotes');
  setTimeout(() => _qtOpenForm(null, prefill), 80);
});

// ── Sales Order confirmation modal ─────────────────────────────────────────
(function () {
  function _soRequireCustomer(tab) {
    toast('A customer is required to create a sales order', 'error');
    const bar = $('#cart-customer-bar');
    if (bar) {
      bar.style.outline = '2px solid var(--accent)';
      bar.style.borderRadius = '6px';
      bar.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      setTimeout(() => { bar.style.outline = ''; bar.style.borderRadius = ''; }, 2000);
    }
  }

  function _soOpenConfirm(tab) {
    const cur = state.currency || '';
    // Populate customer line
    $('#so-confirm-customer').textContent = tab._customer?.name
      ? `Customer: ${tab._customer.name}`
      : 'Customer: —';

    // Populate items table
    let subtotal = 0;
    $('#so-confirm-rows').innerHTML = tab.cart.map(i => {
      const price = i._basePrice ?? i.price ?? 0;
      const line  = Math.round(price * i.qty * 100) / 100;
      subtotal   += line;
      const qtyStr = i.qty % 1 === 0 ? i.qty : i.qty.toFixed(3).replace(/\.?0+$/, '');
      return `<tr>
        <td>${escHtml(i.name)}</td>
        <td class="r">${qtyStr}</td>
        <td class="r">${cur}${price.toFixed(2)}</td>
        <td class="r">${cur}${line.toFixed(2)}</td>
      </tr>`;
    }).join('');

    $('#so-confirm-total').textContent = cur + subtotal.toFixed(2);

    // Reset optional fields
    $('#so-confirm-delivery').value = '';
    $('#so-confirm-notes').value    = '';

    $('#so-confirm-modal').style.display = 'flex';
    $('#so-confirm-delivery').focus();
  }

  $('#pos-to-sales-order')?.addEventListener('click', () => {
    const tab = activeTab();
    if (!tab || !tab.cart.length) { toast('Cart is empty', 'info'); return; }
    if (!tab._customer?.id) { _soRequireCustomer(tab); return; }
    _soOpenConfirm(tab);
  });

  function _soClose() {
    $('#so-confirm-modal').style.display = 'none';
  }

  $('#so-confirm-close')?.addEventListener('click',  _soClose);
  $('#so-confirm-cancel')?.addEventListener('click', _soClose);
  $('#so-confirm-modal')?.addEventListener('click', e => {
    if (e.target === e.currentTarget) _soClose();
  });

  $('#so-confirm-submit')?.addEventListener('click', async () => {
    const tab = activeTab();
    if (!tab || !tab.cart.length) { _soClose(); return; }
    if (!tab._customer?.id) { _soClose(); _soRequireCustomer(tab); return; }

    const submitBtn = $('#so-confirm-submit');
    submitBtn.disabled = true;
    submitBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Creating…';

    const delivery = $('#so-confirm-delivery').value || null;
    const notes    = $('#so-confirm-notes').value.trim() || null;

    const body = {
      customer_id:           tab._customer.id,
      order_date:            new Date().toISOString().slice(0, 10),
      expected_delivery_date: delivery,
      notes,
      items: tab.cart.map(i => ({
        description: i.name,
        quantity:    i.qty,
        unit_price:  i._basePrice ?? i.price,
      })),
    };

    const res = await API.createSalesOrder(body);

    submitBtn.disabled = false;
    submitBtn.innerHTML = '<i class="fa fa-check"></i> Confirm &amp; Create Order';

    if (res.status === 201) {
      const orderNum = res.body?.data?.order_number || 'Sales Order';
      _soClose();
      // Clear cart and customer
      tab.cart      = [];
      tab._customer = null;
      renderCart();
      renderPosTabBar();
      toast(`${orderNum} created — cart cleared`, 'success');
    } else {
      toast(res.body?.message || 'Failed to create sales order', 'error');
    }
  });
}());

// ── Checkout ───────────────────────────────────────────────────────────────
let _coSubtotal = 0; // base subtotal before order-level discount
let _coAmount   = ''; // numpad string
let _coDiscType = 'pct'; // 'pct' | 'flat'

function _itemEffectivePct(item) {
  const gross = item.price * item.qty;
  if ((item.itemDiscType || 'pct') === 'flat') {
    const flat = Math.max(0, parseFloat(item.itemDiscountFlat) || 0);
    return gross > 0 ? Math.min(100, Math.round(flat / gross * 10000) / 100) : 0;
  }
  return Math.min(100, Math.max(0, parseFloat(item.itemDiscountPct) || 0));
}

function _itemLineNet(item) {
  const gross = item.price * item.qty;
  if ((item.itemDiscType || 'pct') === 'flat') {
    const flat = Math.max(0, parseFloat(item.itemDiscountFlat) || 0);
    return Math.max(0, Math.round((gross - flat) * 100) / 100);
  }
  const d = Math.min(100, Math.max(0, parseFloat(item.itemDiscountPct) || 0));
  return Math.round(gross * (1 - d / 100) * 100) / 100;
}

function _coComputeSubtotal() {
  const tab = activeTab();
  if (!tab) return 0;
  return Math.round(tab.cart.reduce((s, i) => s + _itemLineNet(i), 0) * 100) / 100;
}

function _coRenderItems() {
  const tab  = activeTab();
  const list = $('#co-items-list');
  const badge = $('#co-items-badge');
  const ftrTotal = $('#co-items-ftr-total');
  if (!list || !tab) return;
  const cur = state.currency ? ' ' + state.currency : '';
  const items = tab.cart;
  if (badge) badge.textContent = items.length;

  const s = state.receiptSettings || {};
  const taxRules = Array.isArray(s.tax_rules)
    ? s.tax_rules.filter(r => parseFloat(r.value || 0) > 0)
    : [];
  const midEl = list.closest('.co-mid');
  if (midEl) midEl.classList.toggle('co-has-tax', taxRules.length > 0);

  list.innerHTML = items.map((i, idx) => {
    const svc      = i._type === 'service';
    const qty      = i.qty % 1 === 0 ? parseInt(i.qty) : parseFloat(i.qty).toFixed(2);
    const price    = parseFloat(i.price).toFixed(2);
    const discType = i.itemDiscType || 'pct';
    const discVal  = discType === 'flat'
      ? (parseFloat(i.itemDiscountFlat) || 0)
      : (Math.min(100, Math.max(0, parseFloat(i.itemDiscountPct) || 0)));
    const hasDisc  = discVal > 0;
    const line     = _itemLineNet(i).toFixed(2);
    const typeLbl  = discType === 'flat' ? escHtml(state.currency || '¤') : '%';
    const taxOpts  = taxRules.map((r, ri) => {
      const isSel = i.itemTaxRule
        && i.itemTaxRule.name === r.name
        && String(i.itemTaxRule.value) === String(r.value)
        && i.itemTaxRule.type  === r.type;
      const lbl = escHtml(r.name) + (r.type !== 'flat' ? ' ' + r.value + '%' : '');
      return `<option value="${ri}"${isSel ? ' selected' : ''}>${lbl}</option>`;
    }).join('');
    const taxCell = taxRules.length > 0
      ? `<div class="co-ir-tax"><select class="co-ir-tax-sel${i.itemTaxRule ? ' has-tax' : ''}" data-idx="${idx}"><option value="">–</option>${taxOpts}</select></div>`
      : '<div class="co-ir-tax"></div>';
    return `<div class="co-ir" data-idx="${idx}">
      <div class="co-ir-icon ${svc ? 'is-service' : 'is-product'}">
        <i class="fa ${svc ? 'fa-screwdriver-wrench' : 'fa-box'}"></i>
      </div>
      <div class="co-ir-name" title="${escHtml(i.name)}">${escHtml(i.name)}</div>
      <div class="co-ir-qty">${qty}</div>
      <div class="co-ir-price">${price}</div>
      <div class="co-ir-disc">
        <input type="number" class="co-ir-disc-inp${hasDisc ? ' has-discount' : ''}"
               data-idx="${idx}" value="${discVal || ''}"
               min="0" ${discType === 'pct' ? 'max="100"' : ''} step="${discType === 'flat' ? '0.01' : '0.5'}" placeholder="0">
        <button class="co-ir-disc-type${discType === 'flat' ? ' is-flat' : ''}" data-idx="${idx}" title="Toggle % / flat">${typeLbl}</button>
      </div>
      ${taxCell}
      <div class="co-ir-total">${line}</div>
    </div>`;
  }).join('');
  _coSubtotal = _coComputeSubtotal();
  if (ftrTotal) ftrTotal.textContent = _coSubtotal.toFixed(2) + cur;
}

function _coGetAfterDiscount() {
  const raw = parseFloat($('#co-discount-pct')?.value) || 0;
  if (_coDiscType === 'flat') {
    return Math.max(0, Math.round((_coSubtotal - Math.max(0, raw)) * 100) / 100);
  }
  const pct = Math.min(100, Math.max(0, raw));
  return Math.max(0, Math.round(_coSubtotal * (1 - pct / 100) * 100) / 100);
}

function _coGetTaxBreakdown(afterDisc) {
  const s    = state.receiptSettings || {};
  const tab  = activeTab();
  const cart = tab?.cart || [];
  const hasItemTax = cart.some(i => i.itemTaxRule);
  if (hasItemTax) {
    const grouped = {};
    cart.forEach(i => {
      if (!i.itemTaxRule) return;
      const base = _itemLineNet(i);
      const r   = i.itemTaxRule;
      const v   = parseFloat(r.value || 0);
      const amt = r.type === 'flat'
        ? Math.round(v * 100) / 100
        : Math.round(base * v / 100 * 100) / 100;
      const key = `${r.name}|${r.type}|${v}`;
      if (!grouped[key]) grouped[key] = { name: r.name, type: r.type, value: v, amount: 0 };
      grouped[key].amount = Math.round((grouped[key].amount + amt) * 100) / 100;
    });
    return Object.values(grouped).filter(t => t.amount > 0);
  }
  if (!s.tax_enabled) return [];
  const rules = Array.isArray(s.tax_rules) ? s.tax_rules : [];
  return rules
    .filter(r => parseFloat(r.value || 0) > 0)
    .map(r => {
      const v   = parseFloat(r.value || 0);
      const amt = r.type === 'flat'
        ? Math.round(v * 100) / 100
        : Math.round(afterDisc * v / 100 * 100) / 100;
      return { name: r.name || 'Tax', type: r.type || 'percentage', value: v, amount: amt };
    });
}

function _coGetTotal() {
  const afterDisc = _coGetAfterDiscount();
  const taxes     = _coGetTaxBreakdown(afterDisc);
  const taxTotal  = Math.round(taxes.reduce((s, t) => s + t.amount, 0) * 100) / 100;
  return Math.round((afterDisc + taxTotal) * 100) / 100;
}

function _coGetMethod() {
  return $$('.co-pay-method.active')[0]?.dataset.method || 'cash';
}

function _coRefresh() {
  const afterDisc = _coGetAfterDiscount();
  const taxes     = _coGetTaxBreakdown(afterDisc);
  const taxTotal  = Math.round(taxes.reduce((s, t) => s + t.amount, 0) * 100) / 100;
  const total     = Math.round((afterDisc + taxTotal) * 100) / 100;
  const saved     = Math.round((_coSubtotal - afterDisc) * 100) / 100;
  const cur       = state.currency ? ' ' + state.currency : '';
  const amount    = parseFloat(_coAmount) || 0;
  const change    = Math.round((amount - total) * 100) / 100;

  if ($('#co-subtotal')) $('#co-subtotal').textContent = _coSubtotal.toFixed(2) + cur;
  if ($('#co-saved'))    $('#co-saved').textContent    = saved > 0 ? saved.toFixed(2) + cur : '—';

  const taxRowsEl = $('#co-tax-rows');
  if (taxRowsEl) {
    taxRowsEl.innerHTML = taxes.map(t => {
      const lbl = escHtml(t.name) + (t.type === 'flat' ? '' : ' ' + t.value + '%');
      return `<div class="co-sum-row">
        <span style="color:var(--text-muted);font-size:12px">${lbl}</span>
        <strong style="color:#f59e0b;font-size:12px">+${t.amount.toFixed(2)}${cur}</strong>
      </div>`;
    }).join('');
  }

  if ($('#co-total'))    $('#co-total').textContent    = total.toFixed(2);
  if ($('#co-currency')) $('#co-currency').textContent = state.currency || '';
  const amountEl = $('#co-amount');
  if (amountEl) amountEl.value = _coAmount || '';
  if ($('#co-amount-due')) $('#co-amount-due').textContent = total.toFixed(2) + cur;
  const changeEl = $('#co-change');
  if (changeEl) {
    changeEl.textContent  = change.toFixed(2) + cur;
    changeEl.className    = change >= 0 ? 'co-change-pos' : 'co-change-neg';
  }
}

function _coNumpadKey(key) {
  if (key === 'exact') {
    _coAmount = _coGetTotal().toFixed(2);
  } else if (key === 'clear') {
    _coAmount = '';
  } else if (key === 'back') {
    _coAmount = _coAmount.slice(0, -1);
  } else if (key === '.') {
    if (!_coAmount.includes('.')) _coAmount += '.';
  } else {
    if (_coAmount === '0' || _coAmount === '') _coAmount = key;
    else _coAmount += key;
    // Max 2 decimal places
    const parts = _coAmount.split('.');
    if (parts[1] && parts[1].length > 2) _coAmount = parts[0] + '.' + parts[1].slice(0, 2);
  }
  _coRefresh();
}

function openCheckout() {
  const tab = activeTab();
  if (!tab || !tab.cart.length) { toast('Cart is empty', 'error'); return; }
  _coSubtotal = _coComputeSubtotal();

  // Reset discount first so _coGetTotal() computes at 0% discount
  _coDiscType = 'pct';
  $('#co-disc-btn-pct')?.classList.add('active');
  $('#co-disc-btn-flat')?.classList.remove('active');
  const discSuffix = $('#co-disc-suffix');
  if (discSuffix) discSuffix.textContent = '%';
  const discEl = $('#co-discount-pct');
  if (discEl) { discEl.value = '0'; discEl.max = '100'; discEl.step = '1'; }
  _coAmount = _coGetTotal().toFixed(2);

  // Reset payment method to cash
  $$('.co-pay-method').forEach(b => b.classList.remove('active'));
  $$('.co-pay-method')[0]?.classList.add('active');

  // Reset credit fields
  const creditDueDateEl = $('#co-credit-due-date');
  if (creditDueDateEl) creditDueDateEl.value = '';
  _coSyncPaymentSections();

  // Reset notes & alert
  const notesEl = $('#co-notes');
  if (notesEl) notesEl.value = '';
  $('#checkout-alert').style.display = 'none';

  // Update modal subtitle
  const cartHasServices = tab.cart.some(i => i._type === 'service');
  const cartHasProducts = tab.cart.some(i => i._type !== 'service');
  const coSub = $('#co-header-sub');
  if (coSub) coSub.textContent = cartHasServices && cartHasProducts
    ? 'Products will be sold + service requests created'
    : 'Review your order and complete payment';

  _coRefresh();
  _coRenderItems();
  _coSyncCustomer();
  $('#checkout-modal').style.display = 'flex';

  // If the cart has warranty products and no customer is assigned, warn immediately
  // and focus the customer input so the cashier can search/assign one.
  const _wtyItems = tab.cart.filter(i => i.warrantyType);
  if (_wtyItems.length && !tab._customer) {
    const _wtyNames = _wtyItems.map(i => i.name).join(', ');
    showAlert($('#checkout-alert'),
      `Warranty product${_wtyItems.length > 1 ? 's' : ''} in cart (${_wtyNames}) — please assign a customer or add a customer to this bill to register the warranty.`);
    setTimeout(() => $('#co-cust-input')?.focus(), 100);
  } else {
    setTimeout(() => { const a = $('#co-amount'); if (a) { a.select(); a.focus(); } }, 60);
  }
}

$('#checkout-cancel').addEventListener('click', () => { $('#checkout-modal').style.display = 'none'; });

function _coSyncPaymentSections() {
  const isCredit = _coGetMethod() === 'credit';
  const creditSec  = $('#co-credit-section');
  const cashSec    = $('#co-cash-section');
  const numpadSec  = $('#co-numpad-section');
  if (creditSec)  creditSec.style.display  = isCredit ? '' : 'none';
  if (cashSec)    cashSec.style.display    = isCredit ? 'none' : '';
  if (numpadSec)  numpadSec.style.display  = isCredit ? 'none' : '';
  _coSyncCreditNotice();
}

function _coSyncCreditNotice() {
  const notice = $('#co-credit-customer-notice');
  if (!notice) return;
  const tab = activeTab();
  notice.style.display = (_coGetMethod() === 'credit' && !tab?._customer) ? '' : 'none';
}

// Payment method tabs
$$('.co-pay-method').forEach(btn => {
  btn.addEventListener('click', () => {
    $$('.co-pay-method').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    _coSyncPaymentSections();
  });
});

// Discount input (order-level)
$('#co-discount-pct').addEventListener('input', _coRefresh);

// Flat / percent toggle
$$('#co-disc-btn-pct, #co-disc-btn-flat').forEach(btn => {
  btn.addEventListener('click', () => {
    _coDiscType = btn.dataset.type;
    $$('.co-disc-type-btn').forEach(b => b.classList.toggle('active', b === btn));
    const discEl = $('#co-discount-pct');
    const suffix = $('#co-disc-suffix');
    if (discEl) {
      discEl.value = '0';
      if (_coDiscType === 'flat') {
        discEl.removeAttribute('max'); discEl.step = '0.01';
      } else {
        discEl.max = '100'; discEl.step = '1';
      }
    }
    if (suffix) suffix.textContent = _coDiscType === 'flat' ? (state.currency || '—') : '%';
    _coRefresh();
  });
});

// Per-item discount inputs (event delegation on the list container)
$('#co-items-list').addEventListener('input', e => {
  const inp = e.target.closest('.co-ir-disc-inp');
  if (!inp) return;
  const idx = parseInt(inp.dataset.idx);
  const tab = activeTab();
  if (!tab?.cart[idx]) return;
  const item = tab.cart[idx];
  const raw = Math.max(0, parseFloat(inp.value) || 0);
  if ((item.itemDiscType || 'pct') === 'flat') {
    item.itemDiscountFlat = raw;
  } else {
    item.itemDiscountPct = Math.min(100, raw);
  }
  inp.classList.toggle('has-discount', raw > 0);
  const totalEl = inp.closest('.co-ir')?.querySelector('.co-ir-total');
  if (totalEl) totalEl.textContent = _itemLineNet(item).toFixed(2);
  _coSubtotal = _coComputeSubtotal();
  const cur = state.currency ? ' ' + state.currency : '';
  const ftrEl = $('#co-items-ftr-total');
  if (ftrEl) ftrEl.textContent = _coSubtotal.toFixed(2) + cur;
  _coRefresh();
});

// Per-item discount type toggle (% / flat)
$('#co-items-list').addEventListener('click', e => {
  const btn = e.target.closest('.co-ir-disc-type');
  if (!btn) return;
  const idx = parseInt(btn.dataset.idx);
  const tab = activeTab();
  if (!tab?.cart[idx]) return;
  const item = tab.cart[idx];
  const newType = (item.itemDiscType || 'pct') === 'pct' ? 'flat' : 'pct';
  item.itemDiscType     = newType;
  item.itemDiscountPct  = 0;
  item.itemDiscountFlat = 0;
  _coRenderItems();
  _coRefresh();
});

// Per-item tax select (event delegation)
$('#co-items-list').addEventListener('change', e => {
  const sel = e.target.closest('.co-ir-tax-sel');
  if (!sel) return;
  const idx = parseInt(sel.dataset.idx);
  const tab = activeTab();
  if (!tab?.cart[idx]) return;
  const s = state.receiptSettings || {};
  const taxRules = Array.isArray(s.tax_rules)
    ? s.tax_rules.filter(r => parseFloat(r.value || 0) > 0)
    : [];
  const ri = sel.value === '' ? -1 : parseInt(sel.value);
  tab.cart[idx].itemTaxRule = ri >= 0 && taxRules[ri] ? taxRules[ri] : null;
  sel.classList.toggle('has-tax', !!tab.cart[idx].itemTaxRule);
  _coRefresh();
});

// Numpad
$$('.co-key').forEach(btn => {
  btn.addEventListener('click', () => _coNumpadKey(btn.dataset.key));
});

// Amount input — keyboard typing
$('#co-amount')?.addEventListener('input', function () {
  _coAmount = this.value;
  _coRefresh();
});

// ── Checkout customer search ────────────────────────────────────────────────
let _coCustTimer = null;

function _coSyncCustomer() {
  const tab  = activeTab();
  const cust = tab?._customer ?? null;
  const wrap    = $('#co-cust-wrap');
  const nameEl  = $('#co-cust-name-disp');
  const clearBtn = $('#co-cust-clear');
  const ddEl    = $('#co-cust-dd');
  const inp     = $('#co-cust-input');

  if (cust) {
    if (nameEl)   nameEl.textContent = cust.name;
    if (clearBtn) clearBtn.style.display = '';
    if (wrap)     { wrap.classList.add('has-customer'); wrap.classList.remove('open'); }
  } else {
    if (nameEl)   nameEl.textContent = 'Select customer…';
    if (clearBtn) clearBtn.style.display = 'none';
    if (wrap)     { wrap.classList.remove('has-customer', 'open'); }
  }
  if (ddEl) ddEl.style.display = 'none';
  if (inp)  inp.value = '';
}

// ── Checkout customer dropdown ──────────────────────────────────────────────
async function _coCustRender(q) {
  const listEl = $('#co-cust-dd-list');
  if (!listEl) return;
  const res  = await API.customers(q || '');
  const list = res.body?.data ?? [];

  const rows = list.map(c => `
    <div class="co-cust-dd-row" data-cid="${c.id}">
      <div class="co-cust-dd-name">${escHtml(c.name)}</div>
      ${c.phone ? `<div class="co-cust-dd-meta">${escHtml(c.phone)}</div>` : ''}
    </div>`).join('');

  const emptyRow = !list.length
    ? `<div class="co-cust-dd-row co-cust-dd-empty"><div class="co-cust-dd-name">No customers found</div></div>`
    : '';

  listEl.innerHTML = rows + emptyRow + `
    <div class="co-cust-dd-row co-cust-dd-add" id="co-cust-dd-add-row">
      <i class="fa fa-user-plus"></i>
      <span class="co-cust-dd-name">Add customer</span>
    </div>`;

  listEl.querySelectorAll('.co-cust-dd-row[data-cid]').forEach(row => {
    row.addEventListener('click', () => {
      const c = list.find(x => x.id === Number(row.dataset.cid));
      if (!c) return;
      const tab = activeTab();
      if (tab) tab._customer = c;
      renderCartCustomer();
      _coSyncCustomer();
      _coSyncCreditNotice();
    });
  });

  $('#co-cust-dd-add-row')?.addEventListener('click', () => {
    _coSyncCustomer(); // closes panel
    openCustomerModal();
    setTimeout(() => _showCustomerCreateForm(''), 60);
  });
}

function _coCustOpen() {
  const dd   = $('#co-cust-dd');
  const wrap = $('#co-cust-wrap');
  if (!dd) return;
  dd.style.display = '';
  wrap?.classList.add('open');
  _coCustRender('');
  setTimeout(() => $('#co-cust-input')?.focus(), 50);
}

function _coCustClose() {
  const dd   = $('#co-cust-dd');
  const wrap = $('#co-cust-wrap');
  if (dd) dd.style.display = 'none';
  wrap?.classList.remove('open');
  const inp = $('#co-cust-input');
  if (inp) inp.value = '';
}

$('#co-cust-trigger')?.addEventListener('click', e => {
  if (e.target.closest('#co-cust-clear')) return;
  const isOpen = $('#co-cust-dd')?.style.display !== 'none';
  isOpen ? _coCustClose() : _coCustOpen();
});

$('#co-cust-trigger')?.addEventListener('keydown', e => {
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); _coCustOpen(); }
  if (e.key === 'Escape') _coCustClose();
});

$('#co-cust-input')?.addEventListener('input', function () {
  clearTimeout(_coCustTimer);
  _coCustTimer = setTimeout(() => _coCustRender(this.value.trim()), 220);
});

$('#co-cust-input')?.addEventListener('keydown', e => {
  if (e.key === 'Escape') _coCustClose();
});

// Close when clicking outside the dropdown
document.addEventListener('click', e => {
  if (!e.target.closest('#co-cust-wrap')) _coCustClose();
}, true);

$('#co-cust-clear')?.addEventListener('click', e => {
  e.stopPropagation();
  const tab = activeTab();
  if (tab) tab._customer = null;
  renderCartCustomer();
  _coSyncCustomer();
  _coSyncCreditNotice();
});

$('#checkout-confirm').addEventListener('click', async () => {
  if (state.registerLockedUntil && Date.now() < state.registerLockedUntil) {
    toast('Cash register is locked. Unlock the register to process sales.', 'error');
    return;
  }

  const method = _coGetMethod();
  const amount = parseFloat(_coAmount) || 0;
  const notes  = $('#co-notes')?.value || '';
  const alertEl = $('#checkout-alert');
  const btn    = $('#checkout-confirm');
  const tab    = activeTab();
  const cart   = tab ? tab.cart : [];
  const total  = _coGetTotal();

  if (method !== 'credit' && amount < total) {
    showAlert(alertEl, `Amount given (${amount.toFixed(2)}) is less than total (${total.toFixed(2)})`);
    return;
  }

  // Credit payment requires a customer
  if (method === 'credit' && !tab?._customer) {
    showAlert(alertEl, 'Credit payment requires a customer. Please assign a customer above.');
    _coSyncCreditNotice();
    setTimeout(() => $('#co-cust-trigger')?.focus(), 60);
    return;
  }

  // Block checkout if warranty products are in the cart but no customer is assigned
  if (cart.some(i => i.warrantyType) && !tab?._customer) {
    showAlert(alertEl, 'Warranty products require a customer. Please assign a customer or add a customer to this bill before completing the sale.');
    setTimeout(() => $('#co-cust-input')?.focus(), 60);
    return;
  }

  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Processing…';
  alertEl.style.display = 'none';

  const productItems = cart.filter(i => i._type !== 'service');
  const serviceItems = cart.filter(i => i._type === 'service');
  const _discRaw    = parseFloat($('#co-discount-pct')?.value) || 0;
  const discountPct  = _coDiscType === 'pct' ? Math.min(100, Math.max(0, _discRaw)) : 0;
  const discountFlat = _coDiscType === 'flat' ? Math.max(0, _discRaw) : 0;

  // Single unified checkout — products and services in one Sale record
  const body = {
    payment_method:   method,
    amount_paid:      method === 'credit' ? total : amount,
    amount_tendered:  method === 'cash'   ? amount : undefined,
    notes:            notes || undefined,
    discount_percent: discountPct  > 0 ? discountPct  : undefined,
    discount_flat:    discountFlat > 0 ? discountFlat : undefined,
    pos_customer_id:  tab?._customer?.id ?? undefined,
    pos_counter_id:   state.posCounterId ?? undefined,
    credit_due_date:  method === 'credit' ? ($('#co-credit-due-date')?.value || undefined) : undefined,
    items: [
      ...productItems.map(i => ({
        product_id:             i.id,
        quantity:               i.qty,
        product_stock_layer_id: i.layerId ?? undefined,
        warranty_type:          i.warrantyType ?? undefined,
        warranty_date:          i.warrantyDate ?? undefined,
        item_discount_percent:  _itemEffectivePct(i) > 0 ? _itemEffectivePct(i) : undefined,
        item_tax_rule:          i.itemTaxRule ?? undefined,
      })),
      ...serviceItems.map(i => ({
        item_type:              'service',
        service_item_id:        i.id,
        quantity:               i.qty,
        warranty_type:          i.warrantyType ?? undefined,
        warranty_date:          i.warrantyDate ?? undefined,
        item_discount_percent:  _itemEffectivePct(i) > 0 ? _itemEffectivePct(i) : undefined,
        item_tax_rule:          i.itemTaxRule ?? undefined,
        custom_requirement_values: (i.customRequirementValues && i.customRequirementValues.length) ? i.customRequirementValues : undefined,
      })),
    ],
  };

  const res = await API.checkout(body);

  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-check"></i> Complete sale';

  if (res.status !== 200 && res.status !== 201) {
    showAlert(alertEl, res.body?.message || 'Checkout failed');
    return;
  }

  const postCustomerId = tab?._customer?.id ?? null;
  // Snapshot tax breakdown before clearing the cart (per-item taxes live in cart items)
  const _taxSnap = _coGetTaxBreakdown(_coGetAfterDiscount());
  $('#checkout-modal').style.display = 'none';
  if (tab) { tab.cart = []; tab._customer = null; }
  renderCart(); renderPosTabBar(); renderCartCustomer();

  // Reload catalogs
  if (productItems.length) loadProducts(state.searchQuery, state.activeCategory);
  if (serviceItems.length && state.posMode === 'services') loadServices(state.serviceSearchQuery, state.serviceActiveCategory);

  const sale = res.body?.data;
  if (sale) {
    if (_taxSnap.length > 0) sale._taxBreakdown = _taxSnap;
    if ((state.receiptSettings?.receipt_mode || 'bill') === 'invoice') {
      _posCreateInvoiceFromSale(sale, postCustomerId);
    } else {
      showReceiptModal(sale);
    }
  }

  // Refresh ribbon stats after each sale
  _loadPosRibbonStats();
});

// ── Register Lock ──────────────────────────────────────────────────────────
let _regLockCountdown = null;
let _regLockPwResolve = null;

function _regLockKey() {
  return `pos_register_lock_${state.config?.businessId || 'default'}`;
}

function lockRegister(untilTs) {
  localStorage.setItem(_regLockKey(), JSON.stringify({ lockedUntil: untilTs }));
  state.registerLockedUntil = untilTs;
  _showLockScreen(new Date(untilTs));
}

function unlockRegister() {
  localStorage.removeItem(_regLockKey());
  state.registerLockedUntil = null;
  if (_regLockCountdown) { clearInterval(_regLockCountdown); _regLockCountdown = null; }
  $('#reg-lock-screen').style.display = 'none';
}

function checkRegisterLock() {
  const raw = localStorage.getItem(_regLockKey());
  if (!raw) return;
  try {
    const { lockedUntil } = JSON.parse(raw);
    if (lockedUntil && Date.now() < lockedUntil) {
      state.registerLockedUntil = lockedUntil;
      _showLockScreen(new Date(lockedUntil));
    } else {
      localStorage.removeItem(_regLockKey());
    }
  } catch (_) { localStorage.removeItem(_regLockKey()); }
}

function _showLockScreen(untilDate) {
  const timeStr = untilDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  $('#reg-lock-at-time').textContent = timeStr;
  $('#reg-lock-screen').style.display = 'flex';

  if (_regLockCountdown) clearInterval(_regLockCountdown);
  function _tick() {
    const remaining = state.registerLockedUntil - Date.now();
    if (remaining <= 0) { unlockRegister(); return; }
    const h = Math.floor(remaining / 3600000);
    const m = Math.floor((remaining % 3600000) / 60000);
    const s = Math.floor((remaining % 60000) / 1000);
    const pad = (n) => String(n).padStart(2, '0');
    $('#reg-lock-countdown').textContent = h > 0
      ? `${pad(h)}:${pad(m)}:${pad(s)}`
      : `${pad(m)}:${pad(s)}`;
  }
  _tick();
  _regLockCountdown = setInterval(_tick, 1000);
}

function _askRegLockPw(actionLabel) {
  return new Promise(resolve => {
    _regLockPwResolve = resolve;
    $('#reg-pw-action-label').textContent = actionLabel;
    $('#reg-lock-pw-input').value = '';
    $('#reg-lock-pw-alert').style.display = 'none';
    $('#reg-lock-pw-modal').style.display = 'flex';
    requestAnimationFrame(() => $('#reg-lock-pw-input').focus());
  });
}

async function _submitRegLockPw() {
  const pw = $('#reg-lock-pw-input').value;
  if (!pw) {
    $('#reg-lock-pw-alert').textContent = 'Please enter your password.';
    $('#reg-lock-pw-alert').style.display = '';
    return;
  }
  const btn = $('#reg-lock-pw-confirm');
  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>';
  const res = await API.verifyPassword(pw);
  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-check"></i> Confirm';
  if (res.status === 200) {
    $('#reg-lock-pw-modal').style.display = 'none';
    if (_regLockPwResolve) { const r = _regLockPwResolve; _regLockPwResolve = null; r(true); }
  } else {
    $('#reg-lock-pw-alert').textContent = res.body?.message || 'Incorrect password.';
    $('#reg-lock-pw-alert').style.display = '';
  }
}

function _cancelRegLockPw() {
  $('#reg-lock-pw-modal').style.display = 'none';
  if (_regLockPwResolve) { const r = _regLockPwResolve; _regLockPwResolve = null; r(null); }
}

function _calcLockUntil(val, customTime) {
  const now = Date.now();
  if (val === 'day') {
    const midnight = new Date(); midnight.setHours(24, 0, 0, 0); return midnight.getTime();
  }
  if (val === '1h') return now + 3600000;
  if (val === '6h') return now + 6 * 3600000;
  if (val === 'custom' && customTime) {
    const [hh, mm] = customTime.split(':').map(Number);
    const target = new Date(); target.setHours(hh, mm, 0, 0);
    if (target.getTime() <= now) target.setDate(target.getDate() + 1);
    return target.getTime();
  }
  return now + 3600000;
}

$('#reg-lock-pw-confirm').addEventListener('click', _submitRegLockPw);
$('#reg-lock-pw-input').addEventListener('keydown', e => {
  if (e.key === 'Enter') _submitRegLockPw();
  if (e.key === 'Escape') _cancelRegLockPw();
});
$('#reg-lock-pw-cancel').addEventListener('click', _cancelRegLockPw);
$('#reg-lock-pw-modal').addEventListener('click', e => {
  if (e.target === e.currentTarget) _cancelRegLockPw();
});

$$('input[name="reg-lock-dur"]').forEach(r => {
  r.addEventListener('change', () => {
    $('#reg-lock-custom-row').style.display = r.value === 'custom' ? '' : 'none';
  });
});

$('#reg-lock-cancel').addEventListener('click', () => {
  $('#reg-lock-modal').style.display = 'none';
});
$('#reg-lock-modal').addEventListener('click', e => {
  if (e.target === e.currentTarget) $('#reg-lock-modal').style.display = 'none';
});

$('#reg-lock-confirm').addEventListener('click', async () => {
  const val = $('input[name="reg-lock-dur"]:checked')?.value || 'day';
  const customTime = $('#reg-lock-custom-time').value;
  if (val === 'custom' && !customTime) { toast('Pick a custom unlock time first.', 'error'); return; }
  $('#reg-lock-modal').style.display = 'none';
  const verified = await _askRegLockPw('lock');
  if (!verified) return;
  const untilTs = _calcLockUntil(val, customTime);
  lockRegister(untilTs);
  toast('Cash register locked', 'success');
});

$('#reg-lock-unlock-btn').addEventListener('click', async () => {
  const verified = await _askRegLockPw('unlock');
  if (!verified) return;
  unlockRegister();
  toast('Register unlocked', 'success');
});

$('#rb-lock-register').addEventListener('click', () => {
  if (state.registerLockedUntil && Date.now() < state.registerLockedUntil) {
    toast('Register is already locked.', 'error');
    return;
  }
  const now = Date.now();
  const fmt = (ts) => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  $('#rld-1h-until').textContent = 'Until ' + fmt(now + 3600000);
  $('#rld-6h-until').textContent = 'Until ' + fmt(now + 6 * 3600000);
  $('#rld-day').checked = true;
  $('#reg-lock-custom-row').style.display = 'none';
  $('#reg-lock-modal').style.display = 'flex';
});
