// ── Ribbon action wiring ───────────────────────────────────────────────────
$('#rb-new-session').addEventListener('click', () => {
  activateTab('pos');
  addPosTab();
  toast('New session added', 'success');
});
$('#rb-close-session').addEventListener('click', () => {
  const tab = activeTab();
  if (tab) closePosTab(tab.id);
});
$('#rb-barcode').addEventListener('click', async () => {
  const sku = prompt('Enter barcode / SKU:');
  if (!sku) return;
  // Try local product-level match first (fast path)
  if (_trySkuAdd(sku.trim())) return;
  // Fall back to API — handles batch SKUs like PRD-IIW3ZFGK-02
  const res = await API.productBySku(sku.trim());
  if (res.status !== 200) { toast('Product not found', 'error'); return; }
  const p = res.body?.data || res.body;
  const layerId = p.matched_layer_id ?? null;
  const matchedLayer = layerId && p.layers ? p.layers.find(l => l.id === layerId) : null;
  const price = matchedLayer
    ? parseFloat(matchedLayer.unit_sell_price)
    : parseFloat(p.discounted_sell_price ?? p.unit_sell_price ?? p.price ?? 0);
  const cartItem = { id: p.id, name: p.name, price, stock: p.layer_qty_remaining ?? p.stock_quantity ?? null, layerId };
  if (p.has_warranty) {
    const tab = activeTab();
    const key = layerId != null ? `${p.id}:${layerId}` : `${p.id}`;
    const alreadyInCart = tab?.cart.some(i => i._key === key);
    if (!alreadyInCart) {
      if (p.warranty_duration) {
        const wty = _resolveWarrantyFromDuration(p.warranty_duration);
        cartItem.warrantyType = wty.type;
        cartItem.warrantyDate = wty.date ?? null;
      } else {
        const wty = await _askWarranty(cartItem.name);
        if (wty === null) return;
        cartItem.warrantyType = wty.type;
        cartItem.warrantyDate = wty.date ?? null;
      }
    }
  }
  addToCart(cartItem);
});
// ── Quick Add Product ──────────────────────────────────────────────────────
async function openAddProductModal() {
  // Reset form
  $('#qap-name').value  = '';
  $('#qap-sku').value   = '';
  $('#qap-price').value = '';
  $('#qap-stock').value = '';
  $('#qap-alert').style.display = 'none';
  $('#qap-alert').classList.remove('qap-alert-success');

  // Currency prefix
  $('#qap-currency-prefix').textContent = state.currency || '';

  // Reset unit combo
  _qapUnit = { id: null, name: '', _new: false };
  $('#qap-unit-input').value = '';
  $('#qap-unit-dd').style.display = 'none';

  // Save button reset
  const btn = $('#qap-save');
  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-plus"></i> Add Product';
  const anotherBtn = $('#qap-save-another');
  anotherBtn.disabled = false;
  anotherBtn.innerHTML = '<i class="fa fa-plus"></i> Save & add another';

  $('#qap-modal').style.display = 'flex';
  setTimeout(() => $('#qap-name').focus(), 80);

  // Fetch fresh units in background so dropdown is populated
  API.units().then(res => {
    if (res.status === 200) state.productUnits = res.body?.data || [];
  });
}

async function submitAddProduct(andAnother = false) {
  const name  = $('#qap-name').value.trim();
  const price = parseFloat($('#qap-price').value);
  const alertEl = $('#qap-alert');

  alertEl.style.display = 'none';
  alertEl.classList.remove('qap-alert-success');

  if (!name) {
    alertEl.textContent = 'Product name is required.';
    alertEl.style.display = 'block';
    $('#qap-name').focus();
    return;
  }
  if (isNaN(price) || price < 0) {
    alertEl.textContent = 'Enter a valid selling price.';
    alertEl.style.display = 'block';
    $('#qap-price').focus();
    return;
  }

  const btn        = $('#qap-save');
  const anotherBtn = $('#qap-save-another');
  const activeBtn  = andAnother ? anotherBtn : btn;
  btn.disabled = true;
  anotherBtn.disabled = true;
  activeBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Adding…';

  // Create new unit on the fly if needed
  let _unitId = _qapUnit.id || undefined;
  if (_qapUnit._new && _qapUnit.name) {
    const uRes = await API.createUnit({ name: _qapUnit.name });
    if (uRes.status !== 201) {
      alertEl.textContent = `Failed to create unit "${_qapUnit.name}"`;
      alertEl.style.display = 'block';
      btn.disabled = false;
      anotherBtn.disabled = false;
      btn.innerHTML = '<i class="fa fa-plus"></i> Add Product';
      anotherBtn.innerHTML = '<i class="fa fa-plus"></i> Save & add another';
      return;
    }
    _unitId = uRes.body?.data?.id;
    state.productUnits = [...(state.productUnits || []), uRes.body.data];
  }

  const body = {
    name,
    unit_price:      price,
    sku:             $('#qap-sku').value.trim() || undefined,
    stock_quantity:  parseFloat($('#qap-stock').value) || 0,
    product_unit_id: _unitId,
  };

  const res = await API.createProduct(body);
  btn.disabled = false;
  anotherBtn.disabled = false;
  btn.innerHTML = '<i class="fa fa-plus"></i> Add Product';
  anotherBtn.innerHTML = '<i class="fa fa-plus"></i> Save & add another';

  if (res.status !== 201 && res.status !== 200) {
    const firstError = res.body?.errors ? Object.values(res.body.errors)[0]?.[0] : null;
    alertEl.textContent = firstError || res.body?.message || 'Failed to add product.';
    alertEl.style.display = 'block';
    return;
  }

  toast(`"${escHtml(name)}" added to catalog`, 'success');
  loadProducts(state.searchQuery, state.activeCategory);

  if (andAnother) {
    // Stay open — reset the form for the next product
    $('#qap-name').value  = '';
    $('#qap-sku').value   = '';
    $('#qap-price').value = '';
    $('#qap-stock').value = '';
    _qapUnit = { id: null, name: '', _new: false };
    $('#qap-unit-input').value = '';
    $('#qap-unit-dd').style.display = 'none';

    alertEl.textContent = `"${name}" added successfully.`;
    alertEl.classList.add('qap-alert-success');
    alertEl.style.display = 'block';

    setTimeout(() => $('#qap-name')?.focus(), 60);
  } else {
    $('#qap-modal').style.display = 'none';
  }
}

$('#qap-sku-gen').addEventListener('click', () => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const rand  = (n) => Array.from({ length: n }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
  $('#qap-sku').value = `SKU-${rand(4)}-${rand(4)}`;
  $('#qap-sku').focus();
});

$('#qap-close').addEventListener('click',  () => { $('#qap-modal').style.display = 'none'; });
$('#qap-cancel').addEventListener('click', () => { $('#qap-modal').style.display = 'none'; });
$('#qap-modal').addEventListener('click', (e) => {
  if (e.target === e.currentTarget) e.currentTarget.style.display = 'none';
});
$('#qap-save').addEventListener('click', () => submitAddProduct(false));
$('#qap-save-another').addEventListener('click', () => submitAddProduct(true));
$('#qap-modal').addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submitAddProduct(false); }
  if (e.key === 'Escape') $('#qap-modal').style.display = 'none';
});

// ── Unit combo for quick-add product dialog ────────────────────────────────
let _qapUnit = { id: null, name: '', _new: false };

function _qapUnitRenderDd() {
  const input = $('#qap-unit-input');
  const dd    = $('#qap-unit-dd');
  const q     = input.value.trim();
  const qLow  = q.toLowerCase();
  const all   = state.productUnits || [];
  const filtered = all.filter(u => !q || (u.name || '').toLowerCase().includes(qLow));
  const hasExact = all.some(u => (u.name || '').toLowerCase() === qLow);

  const rows = filtered.slice(0, 30).map(u => {
    const n = escHtml(u.name || String(u.id));
    return `<div class="tag-dd-item" data-id="${u.id}" data-name="${n}">${n}</div>`;
  });
  if (q && !hasExact) {
    rows.push(`<div class="tag-dd-item tag-dd-create" data-new="1" data-name="${escHtml(q)}"><i class="fa fa-plus"></i> Create "${escHtml(q)}"</div>`);
  }

  dd.innerHTML = rows.length
    ? rows.join('')
    : `<div class="tag-dd-empty">${q ? 'No matches' : 'Type to search or create…'}</div>`;

  dd.style.display = 'block';

  dd.querySelectorAll('.tag-dd-item').forEach(opt => opt.addEventListener('mousedown', e => {
    e.preventDefault();
    const name = opt.dataset.name;
    _qapUnit = opt.dataset.new
      ? { id: null, name, _new: true }
      : { id: parseInt(opt.dataset.id), name, _new: false };
    input.value = name;
    dd.style.display = 'none';
  }));
}

(function _qapUnitWire() {
  const input = $('#qap-unit-input');
  const dd    = $('#qap-unit-dd');
  if (!input) return;
  input.addEventListener('focus', _qapUnitRenderDd);
  input.addEventListener('input', _qapUnitRenderDd);
  input.addEventListener('blur', () => setTimeout(() => {
    dd.style.display = 'none';
    const v = input.value.trim();
    if (!v) { _qapUnit = { id: null, name: '', _new: false }; return; }
    const m = (state.productUnits || []).find(u => (u.name || '').toLowerCase() === v.toLowerCase());
    _qapUnit = m ? { id: m.id, name: m.name, _new: false } : { id: null, name: v, _new: true };
    if (m) input.value = m.name;
  }, 200));
  input.addEventListener('keydown', e => {
    if (e.key === 'Escape') { dd.style.display = 'none'; input.blur(); }
    if (e.key === 'Enter') { e.preventDefault(); const first = dd.querySelector('.tag-dd-item'); if (first) first.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })); }
  });
})();

