// ── HR Attendance ────────────────────────────────────────────────────────────

let _attendanceRecords = [];

async function loadAttendance(search) {
  const area   = $('#att-cards-area');
  const footer = $('#att-footer-text');
  area.innerHTML = '<p style="color:var(--text-muted);padding:20px 0"><i class="fa fa-spinner fa-spin"></i> Loading attendance…</p>';

  const res = await API.attendance(search);
  if (res.status !== 200) {
    area.innerHTML = '<p style="color:#e74c3c"><i class="fa fa-circle-exclamation"></i> Failed to load attendance.</p>';
    return;
  }

  _attendanceRecords = res.body.data || [];
  $('#att-total-count').textContent = res.body.total_count ?? _attendanceRecords.length;

  if (!_attendanceRecords.length) {
    area.innerHTML = `<p style="color:var(--text-muted);text-align:center;padding:40px 0"><i class="fa fa-clock" style="font-size:32px;display:block;margin-bottom:12px;opacity:.3"></i>${search ? 'No attendance records match your search.' : 'No attendance records yet. Click <strong>Upload CSV</strong> to import check-in / check-out logs.'}</p>`;
    footer.textContent = '0 records';
    return;
  }

  area.innerHTML = _attendanceRecords.map(r => buildAttendanceCard(r)).join('');
  footer.textContent = `${_attendanceRecords.length} record${_attendanceRecords.length !== 1 ? 's' : ''}`;
}

function _attFmtTime(dt) {
  if (!dt) return '—';
  const d = new Date(dt.replace(' ', 'T'));
  if (isNaN(d.getTime())) return dt;
  return d.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
}

function _attFmtWorked(minutes) {
  if (minutes === null || minutes === undefined) return '—';
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return `${h}h ${m}m`;
}

function buildAttendanceCard(r) {
  return `
    <div class="lm-card" style="cursor:default">
      <div class="lm-card-header">
        <div class="lm-card-icon" style="background:#dbeafe20;color:#2563eb"><i class="fa fa-user-clock"></i></div>
        <div class="lm-card-title-wrap">
          <span class="lm-card-name">${escHtml(r.employee_name || 'Unknown')} <span style="color:var(--text-muted);font-weight:400">#${escHtml(r.employee_id || '—')}</span></span>
          <div class="lm-card-pills">
            <span class="lm-pill" style="background:#dbeafe18;color:#2563eb"><i class="fa fa-right-to-bracket"></i> In: ${_attFmtTime(r.check_in_at)}</span>
            <span class="lm-pill" style="background:#fef3c718;color:#d97706"><i class="fa fa-right-from-bracket"></i> Out: ${_attFmtTime(r.check_out_at)}</span>
            <span class="lm-pill" style="background:#dcfce718;color:#16a34a"><i class="fa fa-hourglass-half"></i> ${_attFmtWorked(r.worked_minutes)}</span>
          </div>
        </div>
        <span style="font-size:11px;color:var(--text-muted);white-space:nowrap">${escHtml(r.work_date || '')}</span>
      </div>
    </div>`;
}

$('#att-search')?.addEventListener('input', e => loadAttendance(e.target.value));
$('#att-import-btn')?.addEventListener('click', _attCsvOpenModal);

// ── Attendance: CSV Import ──────────────────────────────────────────────────
const _ATT_CSV_SAMPLE = [
  'employee_id,check_in,check_out',
  '0001,2026-09-03 09:00,2026-09-03 17:30',
  '0002,2026-09-03 09:05,2026-09-03 17:00',
].join('\n');

const _ATT_CSV_COL_MAP = {
  'employee_id': 'employee_id', 'employee id': 'employee_id', 'emp id': 'employee_id',
  'emp_id': 'employee_id', 'employee code': 'employee_id', 'id': 'employee_id', 'code': 'employee_id',
  'check_in': 'check_in', 'check in': 'check_in', 'in': 'check_in', 'time in': 'check_in',
  'clock in': 'check_in', 'check_in_at': 'check_in', 'in time': 'check_in',
  'check_out': 'check_out', 'check out': 'check_out', 'out': 'check_out', 'time out': 'check_out',
  'clock out': 'check_out', 'check_out_at': 'check_out', 'out time': 'check_out',
};

let _attCsvParsedRows = [];
let _attCsvValidRows  = [];

function _attCsvParseFile(text) {
  const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n').filter(l => l.trim());
  if (lines.length < 2) return { headers: [], rows: [], error: 'File must have a header row and at least one data row.' };

  const headers = _csvParseLine(lines[0]).map(h => h.trim().toLowerCase());
  const colMap  = {};
  headers.forEach((h, i) => { if (_ATT_CSV_COL_MAP[h]) colMap[_ATT_CSV_COL_MAP[h]] = i; });

  if (colMap['employee_id'] === undefined) {
    return { headers, rows: [], error: 'Missing required column: "employee_id" (or "employee id", "emp id").' };
  }
  if (colMap['check_in'] === undefined) {
    return { headers, rows: [], error: 'Missing required column: "check_in" (or "check in", "in", "time in").' };
  }

  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cells = _csvParseLine(lines[i]);
    const row   = {};
    Object.entries(colMap).forEach(([key, ci]) => { row[key] = (cells[ci] || '').trim(); });
    row._rowNum = i + 1;

    row._errors = [];
    if (!row.employee_id) row._errors.push('Employee ID is required');
    if (!row.check_in && !row.check_out) row._errors.push('Check-in or check-out time is required');
    if (row.check_in && isNaN(new Date(row.check_in.replace(' ', 'T')).getTime())) row._errors.push('Invalid check-in date/time');
    if (row.check_out && isNaN(new Date(row.check_out.replace(' ', 'T')).getTime())) row._errors.push('Invalid check-out date/time');

    rows.push(row);
  }
  return { headers: Object.keys(colMap), rows };
}

function _attCsvSetStep(n) {
  [1, 2, 3].forEach(i => {
    const body = $(`#att-csv-step-${i}`);
    const ind  = $(`#att-csv-step-ind-${i}`);
    if (body) body.style.display = i === n ? 'flex' : 'none';
    if (ind) {
      ind.classList.toggle('active', i === n);
      ind.classList.toggle('done',   i < n);
    }
  });
}

function _attCsvShowPreview(rows) {
  const valid = rows.filter(r => !r._errors.length);
  const bad   = rows.filter(r => r._errors.length);
  _attCsvValidRows = valid;

  const sumEl = $('#att-csv-preview-summary');
  sumEl.innerHTML = `
    <b>${rows.length} row${rows.length !== 1 ? 's' : ''} found</b>
    <span class="csv-preview-badge ok"><i class="fa fa-circle-check"></i> ${valid.length} valid</span>
    ${bad.length ? `<span class="csv-preview-badge error"><i class="fa fa-triangle-exclamation"></i> ${bad.length} with errors</span>` : ''}
    ${rows.length > 100 ? `<span class="csv-preview-badge warn"><i class="fa fa-eye"></i> Showing first 100 rows</span>` : ''}`;

  const display = rows.slice(0, 100);
  $('#att-csv-preview-thead').innerHTML = `<tr>
    <th>#</th><th>Employee ID</th><th>Check In</th><th>Check Out</th><th>Status</th>
  </tr>`;
  $('#att-csv-preview-tbody').innerHTML = display.map(r => {
    const isErr = r._errors.length > 0;
    const status = isErr
      ? `<span class="csv-row-error-msg"><i class="fa fa-triangle-exclamation"></i> ${escHtml(r._errors.join('; '))}</span>`
      : `<span style="color:#10b981;font-size:11px"><i class="fa fa-circle-check"></i> OK</span>`;
    return `<tr class="${isErr ? 'csv-row-error' : ''}">
      <td style="color:var(--text-muted)">${r._rowNum}</td>
      <td><strong>${escHtml(r.employee_id || '—')}</strong></td>
      <td style="color:var(--text-muted)">${escHtml(r.check_in || '—')}</td>
      <td style="color:var(--text-muted)">${escHtml(r.check_out || '—')}</td>
      <td>${status}</td>
    </tr>`;
  }).join('');

  $('#att-csv-import-count').textContent = valid.length;
  $('#att-csv-import-btn').disabled = valid.length === 0;
  _attCsvSetStep(2);
}

function _attCsvReset() {
  _attCsvParsedRows = [];
  _attCsvValidRows  = [];
  $('#att-csv-file-input').value = '';
  _attCsvSetStep(1);
}

function _attCsvOpenModal() {
  _attCsvReset();
  $('#att-csv-import-modal').style.display = 'flex';
}

function _attCsvCloseModal() {
  $('#att-csv-import-modal').style.display = 'none';
  _attCsvReset();
}

function _attCsvDownloadSample() {
  const blob = new Blob([_ATT_CSV_SAMPLE], { type: 'text/csv' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href     = url;
  a.download = 'attendance-sample.csv';
  a.click();
  URL.revokeObjectURL(url);
}

function _attCsvHandleFile(file) {
  if (!file || !file.name.match(/\.csv$/i)) { toast('Please select a .csv file', 'error'); return; }
  const reader = new FileReader();
  reader.onload = (e) => {
    const { rows, error } = _attCsvParseFile(e.target.result);
    if (error) { toast(error, 'error'); return; }
    if (rows.length > 1000) { toast(`CSV has ${rows.length} rows. Only the first 1000 will be imported.`, 'error'); }
    _attCsvParsedRows = rows.slice(0, 1000);
    _attCsvShowPreview(_attCsvParsedRows);
  };
  reader.readAsText(file);
}

const _attCsvDz = $('#att-csv-dropzone');
if (_attCsvDz) {
  _attCsvDz.addEventListener('dragover',  e => { e.preventDefault(); _attCsvDz.classList.add('drag-over'); });
  _attCsvDz.addEventListener('dragleave', () => _attCsvDz.classList.remove('drag-over'));
  _attCsvDz.addEventListener('drop', e => {
    e.preventDefault(); _attCsvDz.classList.remove('drag-over');
    _attCsvHandleFile(e.dataTransfer.files[0]);
  });
}
$('#att-csv-file-input')?.addEventListener('change', e => _attCsvHandleFile(e.target.files[0]));
$('#att-csv-download-sample')?.addEventListener('click', _attCsvDownloadSample);
$('#att-csv-import-close')?.addEventListener('click',  _attCsvCloseModal);
$('#att-csv-import-modal')?.addEventListener('click',  e => { if (e.target === e.currentTarget) _attCsvCloseModal(); });
$('#att-csv-back-btn')?.addEventListener('click',      _attCsvReset);
$('#att-csv-done-btn')?.addEventListener('click',      _attCsvCloseModal);
$('#att-csv-import-more-btn')?.addEventListener('click', _attCsvReset);

$('#att-csv-import-btn')?.addEventListener('click', async () => {
  if (!_attCsvValidRows.length) return;
  const btn = $('#att-csv-import-btn');
  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Importing…';

  const payload = _attCsvValidRows.map(r => ({
    employee_id: r.employee_id,
    check_in:    r.check_in  || undefined,
    check_out:   r.check_out || undefined,
  }));

  const res = await API.importAttendance(payload);
  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-file-import"></i> Import Records';

  if (res.status !== 200) { toast(res.body?.message || 'Import failed', 'error'); return; }

  const { imported, skipped, errors } = res.body;
  const resSum = $('#att-csv-result-summary');
  resSum.innerHTML = `
    <div class="csv-result-stat">
      <div class="csv-result-stat-num green">${imported}</div>
      <div class="csv-result-stat-label"><i class="fa fa-circle-check"></i> Records imported</div>
    </div>
    <div class="csv-result-stat">
      <div class="csv-result-stat-num ${skipped > 0 ? 'red' : ''}">${skipped}</div>
      <div class="csv-result-stat-label"><i class="fa fa-triangle-exclamation"></i> Rows skipped</div>
    </div>`;

  const errWrap = $('#att-csv-result-errors');
  if (errors && errors.length) {
    errWrap.style.display = '';
    $('#att-csv-result-errors-list').innerHTML = errors.map(e =>
      `<div class="csv-result-error-row"><b>Row ${e.row}${e.employee_id ? ' — ' + escHtml(String(e.employee_id)) : ''}:</b><span>${escHtml(e.message)}</span></div>`
    ).join('');
  } else {
    errWrap.style.display = 'none';
  }

  _attCsvSetStep(3);
  if (imported > 0) loadAttendance($('#att-search').value);
});
// ── End Attendance ───────────────────────────────────────────────────────────

// ── Services Panel ─────────────────────────────────────────────────────────
let _svcView       = 'requests';
let _svcReqSearch  = '';
let _svcReqStatus  = '';   // active chip filter (client-side)
let _svcCatSearch  = '';
let _svcAllRequests = [];  // full unfiltered list for stat counts

function switchSvcView(view) {
  _svcView = view;
  $$('[data-svc]').forEach(b => b.classList.toggle('active', b.dataset.svc === view));
  $('#svc-requests-view').style.display   = view === 'requests'   ? 'flex' : 'none';
  $('#svc-catalog-view').style.display    = view === 'catalog'    ? 'flex' : 'none';
  $('#svc-item-detail').style.display     = 'none';
  $('#svc-categories-view').style.display = view === 'categories' ? 'flex' : 'none';

  if (view === 'requests')   loadSvcRequests();
  if (view === 'catalog')    loadSvcCatalog();
  if (view === 'categories') loadSvcCategories();
}

// ── Requests ────────────────────────────────────────────────────────────────
async function loadSvcRequests() {
  const tbody = $('#svc-req-tbody');
  tbody.innerHTML = `<tr><td colspan="7" class="svc-tbl-placeholder"><i class="fa fa-spinner fa-spin"></i> Loading…</td></tr>`;

  // Always fetch ALL statuses so summary tiles are always accurate
  const res = await API.serviceRequests(_svcReqSearch, '');
  if (res.status !== 200) {
    tbody.innerHTML = `<tr><td colspan="7" class="svc-tbl-placeholder" style="color:#e74c3c"><i class="fa fa-circle-exclamation"></i> Failed to load requests</td></tr>`;
    return;
  }

  _svcAllRequests = res.body?.data || [];
  _svcRenderRequestRows();
}

function _svcRenderRequestRows() {
  const tbody = $('#svc-req-tbody');
  const cur   = state.currency ? ' ' + state.currency : '';
  const pmOn  = state.features?.has('project_management');

  const rows = _svcReqStatus
    ? _svcAllRequests.filter(r => r.status === _svcReqStatus)
    : _svcAllRequests;

  if (!rows.length) {
    const msg = _svcReqStatus ? `No ${_svcReqStatus.replace('_', ' ')} requests` : 'No requests found';
    tbody.innerHTML = `<tr><td colspan="${pmOn ? 8 : 7}" class="svc-tbl-placeholder">
      <i class="fa fa-clipboard-list svc-tbl-empty-icon"></i>${msg}</td></tr>`;
    return;
  }

  tbody.innerHTML = rows.map(r => {
    const sched = r.scheduled_at
      ? new Date(r.scheduled_at).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' })
      : '<span style="color:var(--text-light)">—</span>';
    const price = r.total_price != null
      ? `<strong>${r.total_price.toFixed(2)}</strong>${cur}`
      : '<span style="color:var(--text-light)">—</span>';
    const badge = `<span class="svc-status-badge" style="background:${r.status_color}18;color:${r.status_color};border:1px solid ${r.status_color}35">${escHtml(r.status_label)}</span>`;
    const svcSub = r.service_item ? `<div class="svc-req-sub"><i class="fa fa-screwdriver-wrench" style="margin-right:3px;opacity:.6"></i>${escHtml(r.service_item.name)}</div>` : '';

    // Start always opens the dialog (PM options shown inside if feature is on)
    const startBtn   = r.status === 'pending'
      ? `<button class="svc-action-btn svc-action-progress" data-svc-start="${r.id}"><i class="fa fa-rotate"></i> Start</button>`
      : '';
    const cancelBtn  = (r.status === 'pending' || r.status === 'in_progress')
      ? `<button class="svc-action-btn svc-action-cancel" data-svc-status="${r.id}" data-svc-to="cancelled"><i class="fa fa-ban"></i> Cancel</button>`
      : '';
    const completeBtn = r.status === 'in_progress'
      ? `<button class="svc-action-btn svc-action-complete" data-svc-status="${r.id}" data-svc-to="completed"><i class="fa fa-circle-check"></i> Complete</button>`
      : '';
    const btns = [startBtn, completeBtn, cancelBtn].filter(Boolean).join('');

    const projectCell = pmOn
      ? `<td>${r.project ? `<span class="svc-proj-tag"><i class="fa fa-diagram-project" style="margin-right:4px;opacity:.6"></i>${escHtml(r.project.name)}</span>` : '<span style="color:var(--text-light);font-size:12px">—</span>'}</td>`
      : '';

    return `<tr class="inv-row">
      <td><span class="svc-req-num">${escHtml(r.request_number || '—')}</span></td>
      <td><div class="svc-req-title">${escHtml(r.title || '—')}</div>${svcSub}</td>
      <td>${r.customer ? `<div style="font-weight:500">${escHtml(r.customer.name)}</div>` : '<span style="color:var(--text-light)">Walk-in</span>'}</td>
      ${projectCell}
      <td>${badge}</td>
      <td style="font-size:12px;white-space:nowrap">${sched}</td>
      <td style="text-align:right;font-size:13px">${price}</td>
      <td style="text-align:center"><div style="display:flex;gap:5px;justify-content:center">${btns || '<span style="color:var(--text-light);font-size:12px">—</span>'}</div></td>
    </tr>`;
  }).join('');

  // Hide project column header if PM not enabled
  const projCol = document.querySelector('.svc-col-project');
  if (projCol) projCol.style.display = pmOn ? '' : 'none';
}

// Event delegation — handles Start, Cancel, Complete buttons rendered in tbody
$('#svc-req-tbody')?.addEventListener('click', e => {
  const startBtn  = e.target.closest('[data-svc-start]');
  const statusBtn = e.target.closest('[data-svc-status]');
  if (startBtn)  svcStartWithProject(Number(startBtn.dataset.svcStart));
  if (statusBtn) setSvcRequestStatus(Number(statusBtn.dataset.svcStatus), statusBtn.dataset.svcTo);
});

async function setSvcRequestStatus(id, status, projectId = null, createTask = null) {
  const res = await API.updateServiceRequestStatus(id, status, projectId, createTask);
  if (res.status === 200) {
    const r = _svcAllRequests.find(x => x.id === id);
    if (r) Object.assign(r, res.body?.data || {});
    _svcRenderRequestRows();
    if (res.body?.pm_task) toast('Task created in project', 'success');
    else toast('Status updated', 'success');
  } else {
    toast(res.body?.message || 'Failed to update status', 'error');
  }
}

// ── Start Service Request — 2-step dialog ───────────────────────────────────
const _svcStart = { requestId: null, request: null };

function _svcStartShow(step) {
  ['choose','project','task'].forEach(s => {
    $('#svc-start-step-' + s).style.display = s === step ? '' : 'none';
  });
  const titles = {
    choose:  '<i class="fa fa-rotate"></i> Start Service Request',
    project: '<i class="fa fa-folder-plus"></i> Create New Project',
    task:    '<i class="fa fa-circle-check"></i> Add as Task',
  };
  $('#svc-start-modal-title').innerHTML = titles[step];
}

function _svcStartClose() {
  $('#svc-start-modal').style.display = 'none';
  _svcStart.requestId = null;
  _svcStart.request   = null;
}

async function svcStartWithProject(requestId) {
  const r = _svcAllRequests.find(x => x.id === requestId);
  _svcStart.requestId = requestId;
  _svcStart.request   = r;

  const label = r ? (r.request_number ? `${r.request_number} — ` : '') + (r.title || '') : '';
  $('#svc-start-req-label').textContent = label;

  // Show or hide PM option cards based on feature flag
  const pmOn = state.features?.has('project_management');
  const optRow = $('#svc-start-step-choose')?.querySelector('.svc-start-opts-row');
  if (optRow) optRow.style.display = pmOn ? '' : 'none';

  _svcStartShow('choose');
  $('#svc-start-modal').style.display = 'flex';
}

$('#svc-start-modal-close')?.addEventListener('click', _svcStartClose);
$('#svc-start-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) _svcStartClose(); });

// Step 1: Just Start
$('#svc-start-skip')?.addEventListener('click', () => {
  const id = _svcStart.requestId;
  _svcStartClose();
  setSvcRequestStatus(id, 'in_progress');
});

// Step 1 → Step 2a: New Project
$('#svc-start-opt-project')?.addEventListener('click', () => {
  const r = _svcStart.request;
  $('#svc-start-proj-name').value   = r?.title || '';
  $('#svc-start-proj-desc').value   = r?.notes || '';
  $('#svc-start-proj-client').value = r?.customer?.name || '';
  $('#svc-start-proj-due').value    = r?.scheduled_at
    ? new Date(r.scheduled_at).toISOString().slice(0, 10) : '';
  $('#svc-start-proj-alert').style.display = 'none';
  _svcStartShow('project');
  setTimeout(() => $('#svc-start-proj-name')?.focus(), 60);
});

// Step 1 → Step 2b: Task in Project
$('#svc-start-opt-task')?.addEventListener('click', async () => {
  const r   = _svcStart.request;
  const sel = $('#svc-start-task-project');
  sel.innerHTML = '<option value="">— Select project —</option>';
  const res = await API.pmProjects();
  if (res.status === 200) {
    (res.body?.data || []).forEach(p => {
      const opt = document.createElement('option');
      opt.value = p.id;
      opt.textContent = p.name;
      sel.appendChild(opt);
    });
  }
  const svcName = r?.service_item?.name ? ` — ${r.service_item.name}` : '';
  $('#svc-start-task-title').value = (r?.title || '') + svcName;
  $('#svc-start-task-alert').style.display = 'none';
  _svcStartShow('task');
});

// Step 2a: Back
$('#svc-start-proj-back')?.addEventListener('click', () => _svcStartShow('choose'));

// Step 2b: Back
$('#svc-start-task-back')?.addEventListener('click', () => _svcStartShow('choose'));

// ── Client field typeahead (New Project step) ─────────────────────────────
let _svcProjClientTimer = null;

function _svcProjClientShowResults(list, q) {
  const el = $('#svc-start-proj-client-results');
  if (!el) return;
  const rows = list.slice(0, 7).map(c =>
    `<div class="svc-tab-result-item" data-cid="${c.id}" data-cname="${escHtml(c.name)}">
      <i class="fa fa-user" style="opacity:.45;margin-right:6px;font-size:11px"></i>
      <span>${escHtml(c.name)}</span>
      ${c.phone ? `<span style="color:var(--text-muted);font-size:11px;margin-left:auto">${escHtml(c.phone)}</span>` : ''}
    </div>`
  ).join('');
  const addRow =
    `<div class="svc-tab-result-item" id="svc-proj-cust-add-row"
      style="color:var(--accent);font-weight:600;border-top:1px solid var(--border);margin-top:4px;padding-top:8px">
      <i class="fa fa-user-plus" style="margin-right:6px"></i>Add Customer
      ${q ? `<span style="color:var(--text-muted);font-weight:400;font-size:11px;margin-left:4px">"${escHtml(q)}"</span>` : ''}
    </div>`;
  el.innerHTML = (list.length === 0
    ? `<div style="padding:8px 12px;font-size:12px;color:var(--text-muted)"><i class="fa fa-magnifying-glass" style="margin-right:5px;opacity:.5"></i>No customers found</div>`
    : rows
  ) + addRow;
  el.style.display = 'block';

  el.querySelectorAll('.svc-tab-result-item[data-cid]').forEach(row => {
    row.addEventListener('mousedown', e => {
      e.preventDefault();
      $('#svc-start-proj-client').value = row.dataset.cname;
      el.style.display = 'none';
    });
  });
  el.querySelector('#svc-proj-cust-add-row')?.addEventListener('mousedown', e => {
    e.preventDefault();
    el.style.display = 'none';
    _openQuickCustomerModal();
  });
}

$('#svc-start-proj-client')?.addEventListener('input', () => {
  clearTimeout(_svcProjClientTimer);
  const q = $('#svc-start-proj-client').value.trim();
  const el = $('#svc-start-proj-client-results');
  if (!q) { if (el) el.style.display = 'none'; return; }
  _svcProjClientTimer = setTimeout(async () => {
    const res = await API.customers(q);
    _svcProjClientShowResults(res.body?.data || [], q);
  }, 220);
});
$('#svc-start-proj-client')?.addEventListener('blur', () => {
  setTimeout(() => { const el = $('#svc-start-proj-client-results'); if (el) el.style.display = 'none'; }, 160);
});

// "+" button next to client field opens modal directly
$('#svc-proj-client-add-trigger')?.addEventListener('click', () => _openQuickCustomerModal());

// ── Quick Add Customer modal ──────────────────────────────────────────────
function _openQuickCustomerModal() {
  const typed = $('#svc-start-proj-client').value.trim();
  $('#svc-qc-name').value  = typed;
  $('#svc-qc-phone').value = '';
  $('#svc-qc-alert').style.display = 'none';
  $('#svc-qc-modal').style.display = 'flex';
  setTimeout(() => { const n = $('#svc-qc-name'); if (n) { n.focus(); n.select(); } }, 60);
}
function _closeQuickCustomerModal() {
  $('#svc-qc-modal').style.display = 'none';
}

$('#svc-qc-close')?.addEventListener('click', _closeQuickCustomerModal);
$('#svc-qc-cancel')?.addEventListener('click', _closeQuickCustomerModal);
$('#svc-qc-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) _closeQuickCustomerModal(); });

$('#svc-qc-save')?.addEventListener('click', async () => {
  const name    = $('#svc-qc-name').value.trim();
  const phone   = $('#svc-qc-phone').value.trim();
  const alertEl = $('#svc-qc-alert');
  alertEl.style.display = 'none';
  if (!name) {
    alertEl.textContent = 'Name is required.';
    alertEl.style.display = 'block';
    $('#svc-qc-name').focus();
    return;
  }
  const btn = $('#svc-qc-save');
  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Adding…';
  const res = await API.createCustomer({ name, phone: phone || null, customer_type: 'retail' });
  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-user-plus"></i> Add Customer';
  if (res.status !== 201) {
    alertEl.textContent = res.body?.message || 'Failed to add customer.';
    alertEl.style.display = 'block';
    return;
  }
  const c = res.body?.data;
  if (c) $('#svc-start-proj-client').value = c.name;
  _closeQuickCustomerModal();
  toast(`Customer "${name}" added`, 'success');
});

// Step 2a: Create Project & Start
$('#svc-start-proj-confirm')?.addEventListener('click', async () => {
  const btn     = $('#svc-start-proj-confirm');
  const alertEl = $('#svc-start-proj-alert');
  const name    = $('#svc-start-proj-name').value.trim();
  alertEl.style.display = 'none';
  if (!name) {
    alertEl.textContent = 'Project name is required.';
    alertEl.style.display = 'block';
    return;
  }

  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Creating…';

  const projRes = await API.pmProjectCreate({
    name,
    description: $('#svc-start-proj-desc').value.trim()   || null,
    client_name: $('#svc-start-proj-client').value.trim() || null,
    due_date:    $('#svc-start-proj-due').value           || null,
  });

  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-folder-plus"></i> Create Project &amp; Start';

  if (projRes.status !== 201) {
    alertEl.textContent = projRes.body?.message || 'Failed to create project.';
    alertEl.style.display = 'block';
    return;
  }

  const newProjectId = projRes.body.data.id;
  const id = _svcStart.requestId;
  _svcStartClose();
  // create_task:false — the project itself is the deliverable, no task needed
  await setSvcRequestStatus(id, 'in_progress', newProjectId, false);
  toast(`Project "${name}" created`, 'success');
});

// Step 2b: Add Task & Start
$('#svc-start-task-confirm')?.addEventListener('click', async () => {
  const btn       = $('#svc-start-task-confirm');
  const alertEl   = $('#svc-start-task-alert');
  const projectId = Number($('#svc-start-task-project').value);
  const taskTitle = $('#svc-start-task-title').value.trim();
  alertEl.style.display = 'none';

  if (!projectId) {
    alertEl.textContent = 'Please select a project.';
    alertEl.style.display = 'block';
    return;
  }

  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Adding…';

  const r       = _svcStart.request;
  const taskRes = await API.pmTaskCreate(projectId, {
    title:    taskTitle || r?.title || 'Service Request',
    status:   'in_progress',
    priority: 'normal',
    due_date: r?.scheduled_at ? new Date(r.scheduled_at).toISOString().slice(0, 10) : null,
    description: r?.notes || null,
  });

  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-circle-check"></i> Add Task &amp; Start';

  if (taskRes.status !== 201) {
    alertEl.textContent = taskRes.body?.message || 'Failed to create task.';
    alertEl.style.display = 'block';
    return;
  }

  const id = _svcStart.requestId;
  _svcStartClose();
  // Pass projectId so the request is linked; create_task:false since we just created the task
  await setSvcRequestStatus(id, 'in_progress', projectId, false);
});

function _svcSetChip(status) {
  _svcReqStatus = status;
  $$('.svc-chip').forEach(c => c.classList.toggle('active', c.dataset.status === status));
  _svcRenderRequestRows();
}

// ── Catalog ─────────────────────────────────────────────────────────────────
const _SVC_ITM_PALETTE = ['#4e8ef7','#8b5cf6','#ec4899','#f59e0b','#10b981','#ef4444','#06b6d4','#6366f1','#f97316','#14b8a6','#a855f7','#84cc16'];

function _svcItmColor(name) {
  let h = 0;
  for (const ch of name) h = (h * 31 + ch.charCodeAt(0)) % _SVC_ITM_PALETTE.length;
  return _SVC_ITM_PALETTE[Math.abs(h)];
}

async function loadSvcCatalog() {
  const tbody = $('#svc-itm-tbody');
  tbody.innerHTML = `<tr><td colspan="7" class="svc-tbl-placeholder"><i class="fa fa-spinner fa-spin"></i> Loading…</td></tr>`;
  const res = await API.serviceMgmtCatalog(_svcCatSearch);
  if (res.status !== 200) {
    tbody.innerHTML = `<tr><td colspan="7" class="svc-tbl-placeholder" style="color:#e74c3c"><i class="fa fa-circle-exclamation"></i> Failed to load services</td></tr>`;
    return;
  }
  const items = res.body?.data || [];
  const cur   = state.currency ? ' ' + state.currency : '';

  if (!items.length) {
    tbody.innerHTML = `<tr><td colspan="7" class="svc-tbl-placeholder"><i class="fa fa-screwdriver-wrench svc-tbl-empty-icon"></i>No services found</td></tr>`;
    return;
  }

  tbody.innerHTML = items.map(i => {
    const color   = _svcItmColor(i.name);
    const initial = i.name.trim().charAt(0).toUpperCase();
    const cats    = (i.categories || []).map(c => `<span class="svc-itm-dur">${escHtml(c)}</span>`).join('') || '<span style="color:var(--text-light)">—</span>';
    const dur     = i.duration_label && i.duration_label !== '—'
      ? escHtml(i.duration_label)
      : '<span style="color:var(--text-light)">—</span>';
    const badge   = i.is_active
      ? `<span class="svc-cat-badge svc-cat-badge--active"><i class="fa fa-circle" style="font-size:6px"></i> Active</span>`
      : `<span class="svc-cat-badge svc-cat-badge--inactive"><i class="fa fa-circle" style="font-size:6px"></i> Inactive</span>`;
    const desc    = i.description
      ? `<span style="color:var(--text-muted);font-size:12px">${escHtml(i.description)}</span>`
      : '<span style="color:var(--text-light)">—</span>';

    const featuredStar = i.is_featured
      ? `<span title="Featured" style="color:#f59e0b;margin-left:5px"><i class="fa fa-star" style="font-size:11px"></i></span>`
      : '';
    const avatar = i.image_url
      ? `<div class="svc-list-avatar" style="--itm-c:${color}"><img src="${escHtml(i.image_url)}" alt=""></div>`
      : `<div class="svc-list-avatar" style="--itm-c:${color}">${escHtml(initial)}</div>`;
    return `<tr class="inv-row svc-itm-row" data-id="${i.id}" style="cursor:pointer">
      <td>${avatar}</td>
      <td><div style="font-weight:500;font-size:13px;display:flex;align-items:center">${escHtml(i.name)}${featuredStar}</div></td>
      <td class="svc-list-desc">${desc}</td>
      <td><div style="display:flex;flex-wrap:wrap;gap:4px">${cats}</div></td>
      <td style="font-size:12px;color:var(--text-muted)">${dur}</td>
      <td style="text-align:right;font-weight:600;font-size:13px">${parseFloat(i.price).toFixed(2)}<span style="font-size:11px;font-weight:400;color:var(--text-muted);margin-left:2px">${cur}</span></td>
      <td style="text-align:center">${badge}</td>
    </tr>`;
  }).join('');

  // Row click → detail
  tbody.querySelectorAll('.svc-itm-row').forEach(row => {
    row.addEventListener('click', () => _svcOpenItemDetail(Number(row.dataset.id)));
  });
}

// ── Service Item Detail ───────────────────────────────────────────────────────
let _svcDetailActiveTab  = 'overview';
let _svcDetailCurrentId  = null;

function _svcOpenItemDetail(id) {
  _svcDetailCurrentId = id;
  $('#svc-catalog-view').style.display = 'none';
  const detail = $('#svc-item-detail');
  detail.style.display = 'flex';

  // Reset to overview tab
  _svcDetailActiveTab = 'overview';
  $$('.svc-detail-tab').forEach(t => t.classList.toggle('active', t.dataset.detailTab === 'overview'));
  $('#svc-dtab-overview').style.display  = '';
  $('#svc-dtab-employees').style.display = 'none';
  $('#svc-dtab-products').style.display  = 'none';

  // Loading state
  $('#svc-detail-avatar').textContent = '…';
  $('#svc-detail-avatar').style.cssText = '';
  $('#svc-detail-name').textContent = 'Loading…';
  $('#svc-detail-badge').innerHTML  = '';
  $('#svc-detail-meta').innerHTML   = '';
  $('#svc-detail-desc').textContent = '';
  $('#svc-detail-kv').innerHTML     = '';
  $('#svc-detail-cats').innerHTML   = '';
  $('#svc-detail-emp-list').innerHTML  = `<div class="svc-tbl-placeholder"><i class="fa fa-spinner fa-spin"></i> Loading…</div>`;
  $('#svc-detail-prod-list').innerHTML = `<div class="svc-tbl-placeholder"><i class="fa fa-spinner fa-spin"></i> Loading…</div>`;

  API.serviceItemDetail(id).then(res => {
    if (res.status !== 200) {
      $('#svc-detail-name').textContent = 'Failed to load';
      return;
    }
    const d   = res.body.data;
    const cur = state.currency ? ' ' + state.currency : '';
    const color   = _svcItmColor(d.name);
    const initial = d.name.trim().charAt(0).toUpperCase();

    // Header
    const avatarEl = $('#svc-detail-avatar');
    avatarEl.innerHTML = d.image_url ? `<img src="${escHtml(d.image_url)}" alt="">` : escHtml(initial);
    avatarEl.style.cssText = `--itm-c:${color}`;
    $('#svc-detail-name').textContent = d.name;
    $('#svc-detail-badge').innerHTML  = d.is_active
      ? `<span class="svc-cat-badge svc-cat-badge--active"><i class="fa fa-circle" style="font-size:6px"></i> Active</span>`
      : `<span class="svc-cat-badge svc-cat-badge--inactive"><i class="fa fa-circle" style="font-size:6px"></i> Inactive</span>`;
    $('#svc-detail-meta').innerHTML = `
      <span class="svc-detail-meta-pill"><i class="fa fa-tag"></i> ${parseFloat(d.price).toFixed(2)}${cur}</span>
      ${d.duration_label && d.duration_label !== '—' ? `<span class="svc-detail-meta-pill"><i class="fa fa-clock"></i> ${escHtml(d.duration_label)}</span>` : ''}
    `;

    // Overview tab
    $('#svc-detail-desc').textContent = d.description || 'No description provided.';
    $('#svc-detail-kv').innerHTML = `
      <div class="svc-detail-kv-item"><span class="svc-detail-kv-key">Price</span><span class="svc-detail-kv-val">${parseFloat(d.price).toFixed(2)}${cur}</span></div>
      <div class="svc-detail-kv-item"><span class="svc-detail-kv-key">Duration</span><span class="svc-detail-kv-val">${escHtml(d.duration_label || '—')}</span></div>
      <div class="svc-detail-kv-item"><span class="svc-detail-kv-key">Status</span><span class="svc-detail-kv-val">${d.is_active ? 'Active' : 'Inactive'}</span></div>
      <div class="svc-detail-kv-item"><span class="svc-detail-kv-key">Featured</span><span class="svc-detail-kv-val" style="${d.is_featured ? 'color:#f59e0b' : ''}">${d.is_featured ? '<i class="fa fa-star"></i> Yes' : 'No'}</span></div>
      <div class="svc-detail-kv-item"><span class="svc-detail-kv-key">Employees</span><span class="svc-detail-kv-val">${d.employees.length}</span></div>
      <div class="svc-detail-kv-item"><span class="svc-detail-kv-key">Products</span><span class="svc-detail-kv-val">${d.products.length}</span></div>
    `;
    $('#svc-detail-cats').innerHTML = d.categories.length
      ? d.categories.map(c => `<span class="svc-form-cat-chip selected" style="cursor:default;pointer-events:none"><i class="fa fa-check"></i>${escHtml(c.name)}</span>`).join('')
      : '<span style="color:var(--text-muted);font-size:13px">No categories assigned</span>';

    // Employees tab
    _svcDetailEmployees = d.employees || [];
    _svcRenderDetailEmployees();

    // Products tab
    _svcDetailProducts = d.products || [];
    _svcRenderDetailProducts();
  });
}

// ── Detail tab state ──────────────────────────────────────────────────────────
let _svcDetailEmployees = [];
let _svcDetailProducts  = [];

// ── Employee tab render + actions ─────────────────────────────────────────────
function _svcRenderDetailEmployees() {
  const el = $('#svc-detail-emp-list');
  if (!el) return;
  if (!_svcDetailEmployees.length) {
    el.innerHTML = `<div class="svc-tab-empty"><i class="fa fa-users svc-tbl-empty-icon"></i>No employees assigned</div>`;
    return;
  }
  el.innerHTML = _svcDetailEmployees.map(e => {
    const initials = (e.name || '?').split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase();
    return `<div class="svc-assign-row" data-emp-id="${e.id}">
      <div class="svc-assign-avatar svc-assign-avatar--emp">${escHtml(initials)}</div>
      <div class="svc-assign-info">
        <div class="svc-assign-name">${escHtml(e.name)}</div>
        <div class="svc-assign-sub">${escHtml(e.job_title || 'No job title')}</div>
      </div>
      <button class="svc-assign-remove" data-emp-id="${e.id}" title="Remove"><i class="fa fa-xmark"></i></button>
    </div>`;
  }).join('');

  el.querySelectorAll('.svc-assign-remove').forEach(btn => {
    btn.addEventListener('click', () => _svcRemoveEmployee(Number(btn.dataset.empId)));
  });
}

async function _svcRemoveEmployee(empId) {
  _svcDetailEmployees = _svcDetailEmployees.filter(e => e.id !== empId);
  _svcRenderDetailEmployees();
  const res = await API.syncServiceEmployees(_svcDetailCurrentId, {
    employee_ids: _svcDetailEmployees.map(e => e.id),
  });
  if (res.status !== 200) {
    toast('Failed to remove employee', 'error');
    _svcOpenItemDetail(_svcDetailCurrentId); // reload
  } else {
    toast('Employee removed', 'success');
  }
}

// Employee search
let _svcEmpSearchTimer = null;
$('#svc-emp-search-q')?.addEventListener('input', () => {
  clearTimeout(_svcEmpSearchTimer);
  const q = $('#svc-emp-search-q').value.trim();
  const resultsEl = $('#svc-emp-search-results');
  if (!q) { resultsEl.style.display = 'none'; return; }
  _svcEmpSearchTimer = setTimeout(async () => {
    const res = await API.employees();
    const all = (res.body?.data || []);
    const filtered = all.filter(e =>
      (e.name || '').toLowerCase().includes(q.toLowerCase()) &&
      !_svcDetailEmployees.some(ex => ex.id === e.id)
    );
    if (!filtered.length) { resultsEl.style.display = 'none'; return; }
    resultsEl.innerHTML = filtered.map(e =>
      `<div class="svc-tab-result-item" data-emp-id="${e.id}" data-emp-name="${escHtml(e.name)}" data-emp-title="${escHtml(e.job_title || '')}">
        <i class="fa fa-user" style="opacity:.5;margin-right:6px"></i>${escHtml(e.name)}
        ${e.job_title ? `<span style="color:var(--text-muted);font-size:11px;margin-left:4px">· ${escHtml(e.job_title)}</span>` : ''}
      </div>`
    ).join('');
    resultsEl.style.display = 'block';
    resultsEl.querySelectorAll('.svc-tab-result-item').forEach(row => {
      row.addEventListener('mousedown', e => {
        e.preventDefault();
        _svcAddEmployee({ id: Number(row.dataset.empId), name: row.dataset.empName, job_title: row.dataset.empTitle });
        $('#svc-emp-search-q').value = '';
        resultsEl.style.display = 'none';
      });
    });
  }, 200);
});
$('#svc-emp-search-q')?.addEventListener('blur', () => {
  setTimeout(() => { const r = $('#svc-emp-search-results'); if (r) r.style.display = 'none'; }, 150);
});

async function _svcAddEmployee(emp) {
  if (_svcDetailEmployees.some(e => e.id === emp.id)) return;
  _svcDetailEmployees.push(emp);
  _svcRenderDetailEmployees();
  const res = await API.syncServiceEmployees(_svcDetailCurrentId, {
    employee_ids: _svcDetailEmployees.map(e => e.id),
  });
  if (res.status !== 200) {
    toast('Failed to add employee', 'error');
    _svcOpenItemDetail(_svcDetailCurrentId);
  } else {
    toast('Employee added', 'success');
  }
}

// ── Product tab render + actions ──────────────────────────────────────────────
function _svcRenderDetailProducts() {
  const el = $('#svc-detail-prod-list');
  if (!el) return;
  if (!_svcDetailProducts.length) {
    el.innerHTML = `<div class="svc-tab-empty"><i class="fa fa-boxes-stacked svc-tbl-empty-icon"></i>No products assigned</div>`;
    return;
  }
  el.innerHTML = _svcDetailProducts.map(p => {
    const initial = (p.name || '?').trim().charAt(0).toUpperCase();
    return `<div class="svc-assign-row" data-prod-id="${p.id}">
      <div class="svc-assign-avatar svc-assign-avatar--prod">${escHtml(initial)}</div>
      <div class="svc-assign-info">
        <div class="svc-assign-name">${escHtml(p.name)}</div>
        ${p.unit ? `<div class="svc-assign-sub">Unit: ${escHtml(p.unit)}</div>` : ''}
      </div>
      <div class="svc-assign-qty-wrap">
        <label class="svc-assign-qty-lbl">Qty</label>
        <input type="number" class="svc-assign-qty-input" data-prod-id="${p.id}" value="${parseFloat(p.qty)}" min="0.001" step="0.001">
      </div>
      <button class="svc-assign-remove" data-prod-id="${p.id}" title="Remove"><i class="fa fa-xmark"></i></button>
    </div>`;
  }).join('');

  el.querySelectorAll('.svc-assign-qty-input').forEach(inp => {
    inp.addEventListener('change', () => {
      const id  = Number(inp.dataset.prodId);
      const qty = parseFloat(inp.value) || 1;
      const p   = _svcDetailProducts.find(x => x.id === id);
      if (p) { p.qty = qty; _svcSyncProducts(); }
    });
  });
  el.querySelectorAll('.svc-assign-remove').forEach(btn => {
    btn.addEventListener('click', () => _svcRemoveProduct(Number(btn.dataset.prodId)));
  });
}

async function _svcSyncProducts() {
  const res = await API.syncServiceProducts(_svcDetailCurrentId, {
    product_lines: _svcDetailProducts.map(p => ({ product_id: p.id, qty: p.qty })),
  });
  if (res.status !== 200) toast('Failed to save products', 'error');
}

async function _svcRemoveProduct(prodId) {
  _svcDetailProducts = _svcDetailProducts.filter(p => p.id !== prodId);
  _svcRenderDetailProducts();
  const res = await API.syncServiceProducts(_svcDetailCurrentId, {
    product_lines: _svcDetailProducts.map(p => ({ product_id: p.id, qty: p.qty })),
  });
  if (res.status !== 200) {
    toast('Failed to remove product', 'error');
    _svcOpenItemDetail(_svcDetailCurrentId);
  } else {
    toast('Product removed', 'success');
  }
}

// Product search
let _svcProdDetailSearchTimer = null;
$('#svc-prod-search-q')?.addEventListener('input', () => {
  clearTimeout(_svcProdDetailSearchTimer);
  const q = $('#svc-prod-search-q').value.trim();
  const resultsEl = $('#svc-prod-search-results');
  if (!q) { resultsEl.style.display = 'none'; return; }
  _svcProdDetailSearchTimer = setTimeout(async () => {
    const res = await API.productSearch(q, 8);
    const items = (res.body?.data || []).filter(p => !_svcDetailProducts.some(ex => ex.id === p.id));
    if (!items.length) { resultsEl.style.display = 'none'; return; }
    resultsEl.innerHTML = items.map(p =>
      `<div class="svc-tab-result-item" data-prod-id="${p.id}" data-prod-name="${escHtml(p.name)}">
        <i class="fa fa-box" style="opacity:.5;margin-right:6px"></i>${escHtml(p.name)}
      </div>`
    ).join('');
    resultsEl.style.display = 'block';
    resultsEl.querySelectorAll('.svc-tab-result-item').forEach(row => {
      row.addEventListener('mousedown', e => {
        e.preventDefault();
        _svcAddProduct({ id: Number(row.dataset.prodId), name: row.dataset.prodName, qty: 1, unit: null });
        $('#svc-prod-search-q').value = '';
        resultsEl.style.display = 'none';
      });
    });
  }, 200);
});
$('#svc-prod-search-q')?.addEventListener('blur', () => {
  setTimeout(() => { const r = $('#svc-prod-search-results'); if (r) r.style.display = 'none'; }, 150);
});

async function _svcAddProduct(prod) {
  if (_svcDetailProducts.some(p => p.id === prod.id)) return;
  _svcDetailProducts.push(prod);
  _svcRenderDetailProducts();
  const res = await API.syncServiceProducts(_svcDetailCurrentId, {
    product_lines: _svcDetailProducts.map(p => ({ product_id: p.id, qty: p.qty })),
  });
  if (res.status !== 200) {
    toast('Failed to add product', 'error');
    _svcOpenItemDetail(_svcDetailCurrentId);
  } else {
    toast('Product added', 'success');
  }
}

$('#svc-detail-back')?.addEventListener('click', () => {
  $('#svc-item-detail').style.display = 'none';
  $('#svc-catalog-view').style.display = 'flex';
});

$('#svc-detail-edit-btn')?.addEventListener('click', () => {
  if (_svcDetailCurrentId) openEditServiceModal(_svcDetailCurrentId);
});

$('#svc-detail-delete-btn')?.addEventListener('click', () => {
  if (_svcDetailCurrentId) {
    const name = $('#svc-detail-name')?.textContent || 'this service';
    _svcDeleteItem(_svcDetailCurrentId, name);
  }
});

$$('.svc-detail-tab').forEach(tab => {
  tab.addEventListener('click', () => {
    _svcDetailActiveTab = tab.dataset.detailTab;
    $$('.svc-detail-tab').forEach(t => t.classList.toggle('active', t === tab));
    $('#svc-dtab-overview').style.display  = _svcDetailActiveTab === 'overview'   ? '' : 'none';
    $('#svc-dtab-employees').style.display = _svcDetailActiveTab === 'employees'  ? '' : 'none';
    $('#svc-dtab-products').style.display  = _svcDetailActiveTab === 'products'   ? '' : 'none';
  });
});

// ── New / Edit Service Modal ──────────────────────────────────────────────────
let _svcSelectedCats = []; // [{id, name}]
let _svcSelectedEmps = []; // [{id, name}]
let _svcAvailCats    = [];
let _svcAvailEmps    = [];
let _svcCatInputWired = false;
let _svcEmpInputWired = false;
let _svcProdLines    = []; // [{product_id, name, qty}]
let _svcEditingId    = null; // null = create mode, number = edit mode
let _svcFormImageFileId = null;
let _svcCustomReqFields = []; // [{_id, key, keyEdited, label, type, options}]
let _svcCreqIdSeq = 0;

function _svcRemoveCat(id) {
  _svcSelectedCats = _svcSelectedCats.filter(x => x.id !== id);
  _tagRender('svc-cat-tags', _svcSelectedCats, _svcRemoveCat);
}
function _svcRemoveEmp(id) {
  _svcSelectedEmps = _svcSelectedEmps.filter(x => x.id !== id);
  _tagRender('svc-emp-tags', _svcSelectedEmps, _svcRemoveEmp);
}

function _svcSetImage(fileId, url) {
  _svcFormImageFileId = fileId;
  const thumb = $('#svc-img-thumb');
  thumb.innerHTML = url ? `<img src="${escHtml(url)}" alt="">` : '<i class="fa fa-image" style="font-size:22px;color:var(--text-muted)"></i>';
  $('#svc-img-remove').style.display = url ? 'inline-flex' : 'none';
}

function _svcResetModal() {
  _svcSelectedCats = [];
  _svcSelectedEmps = [];
  _svcProdLines    = [];
  _tagRender('svc-cat-tags', [], _svcRemoveCat);
  _tagRender('svc-emp-tags', [], _svcRemoveEmp);
  $('#svc-cat-input').value = '';
  $('#svc-emp-input').value = '';
  $('#svc-form-name').value     = '';
  $('#svc-form-barcode').value  = '';
  $('#svc-form-desc').value     = '';
  $('#svc-form-price').value    = '';
  $('#svc-form-cost-price').value      = '';
  $('#svc-form-wholesale-price').value = '';
  $('#svc-form-duration').value = '';
  $('#svc-form-prod-q').value   = '';
  $('#svc-form-prod-results').style.display = 'none';
  $('#svc-form-prod-lines').innerHTML = '';
  $('#svc-form-currency').textContent = state.currency || '';
  $('#svc-form-currency-cost').textContent = state.currency || '';
  $('#svc-form-currency-wholesale').textContent = state.currency || '';
  $('#svc-form-active').checked    = true;
  $('#svc-form-featured').checked  = false;
  $('#svc-form-warranty').checked  = false;
  _svcCustomReqFields = [];
  $('#svc-form-creq-enabled').checked = false;
  $('#svc-creq-section').style.display = 'none';
  _svcRenderCreqFields();
  $$('#svc-new-modal .prod-modal-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === 'basic'));
  $$('#svc-new-modal .prod-modal-pane').forEach(p => p.classList.toggle('active', p.dataset.pane === 'basic'));
  _svcSetImage(null, null);
}

function openNewServiceModal() {
  _svcEditingId = null;
  _svcResetModal();
  $('#svc-new-modal-title-text').textContent = 'New Service';
  $('#svc-form-submit').innerHTML = '<i class="fa fa-plus"></i> Create Service';
  _svcLoadFormCategories();
  _svcLoadFormEmployees();
  $('#svc-new-modal').style.display = 'flex';
  setTimeout(() => $('#svc-form-name')?.focus(), 60);
}

async function openEditServiceModal(id) {
  _svcEditingId = id;
  _svcResetModal();
  $('#svc-new-modal-title-text').textContent = 'Edit Service';
  $('#svc-form-submit').innerHTML = '<i class="fa fa-spinner fa-spin"></i> Loading…';
  $('#svc-form-submit').disabled  = true;
  $('#svc-new-modal').style.display = 'flex';

  const [detailRes] = await Promise.all([
    API.serviceItemDetail(id),
    _svcLoadFormCategories(),
    _svcLoadFormEmployees(),
  ]);

  $('#svc-form-submit').innerHTML = '<i class="fa fa-floppy-disk"></i> Save Changes';
  $('#svc-form-submit').disabled  = false;

  if (detailRes.status !== 200) {
    toast('Failed to load service data.', 'error');
    return;
  }

  const d = detailRes.body.data;
  $('#svc-form-name').value     = d.name || '';
  $('#svc-form-barcode').value  = d.barcode || '';
  $('#svc-form-desc').value     = d.description || '';
  $('#svc-form-price').value    = d.price != null ? d.price : '';
  $('#svc-form-cost-price').value      = d.cost_price != null ? d.cost_price : '';
  $('#svc-form-wholesale-price').value = d.wholesale_price != null ? d.wholesale_price : '';
  $('#svc-form-duration').value = d.duration_minutes || '';
  $('#svc-form-active').checked   = !!d.is_active;
  $('#svc-form-featured').checked = !!d.is_featured;
  $('#svc-form-warranty').checked = !!d.has_warranty;
  _svcSetImage(d.file_manager_file_id || null, d.image_url || null);

  // Pre-fill custom requirement form
  $('#svc-form-creq-enabled').checked = !!d.custom_requirement_enabled;
  $('#svc-creq-section').style.display = d.custom_requirement_enabled ? '' : 'none';
  _svcCustomReqFields = (d.custom_requirement_fields || []).map(f => ({
    _id: ++_svcCreqIdSeq,
    key: f.key || '',
    keyEdited: true,
    label: f.label || '',
    type: ['text', 'textarea', 'select', 'number', 'date', 'checkbox', 'radio'].includes(f.type) ? f.type : 'text',
    options: Array.isArray(f.options) ? f.options.join(', ') : '',
  }));
  _svcRenderCreqFields();

  // Pre-select categories
  _svcSelectedCats = (d.categories || []).map(c => ({ id: c.id, name: c.name }));
  _tagRender('svc-cat-tags', _svcSelectedCats, _svcRemoveCat);

  // Pre-select employees
  _svcSelectedEmps = (d.employees || []).map(e => ({ id: e.id, name: e.name || e.full_name || '' }));
  _tagRender('svc-emp-tags', _svcSelectedEmps, _svcRemoveEmp);

  // Pre-fill product lines
  _svcProdLines = (d.products || []).map(p => ({ product_id: p.id, name: p.name, qty: p.qty }));
  _svcRenderProdLines();
}

function closeNewServiceModal() {
  $('#svc-new-modal').style.display = 'none';
  _svcEditingId = null;
  _sawCatalogResume();
}

async function _svcLoadFormCategories() {
  const res = await API.serviceMgmtCategories();
  _svcAvailCats = (res.body?.data || [])
    .filter(c => c.is_active)
    .map(c => ({ id: c.id, name: c.name }));

  if (!_svcCatInputWired) {
    _tagWireInput(
      'svc-cat-input', 'svc-cat-dd',
      () => _svcAvailCats,
      () => _svcSelectedCats,
      item => {
        if (!_svcSelectedCats.find(x => x.id === item.id)) {
          _svcSelectedCats.push(item);
          _tagRender('svc-cat-tags', _svcSelectedCats, _svcRemoveCat);
        }
      },
    );
    _svcCatInputWired = true;
  }
}

async function _svcLoadFormEmployees() {
  const res = await API.employees();
  _svcAvailEmps = (res.body?.data || []).map(e => ({ id: e.id, name: e.name || e.full_name || '' }));

  if (!_svcEmpInputWired) {
    _tagWireInput(
      'svc-emp-input', 'svc-emp-dd',
      () => _svcAvailEmps,
      () => _svcSelectedEmps,
      item => {
        if (!_svcSelectedEmps.find(x => x.id === item.id)) {
          _svcSelectedEmps.push(item);
          _tagRender('svc-emp-tags', _svcSelectedEmps, _svcRemoveEmp);
        }
      },
    );
    _svcEmpInputWired = true;
  }
}

// ── Product lines for service ─────────────────────────────────────────────
let _svcProdSearchTimer = null;

$('#svc-form-prod-q')?.addEventListener('input', () => {
  clearTimeout(_svcProdSearchTimer);
  const q = $('#svc-form-prod-q').value.trim();
  const resultsEl = $('#svc-form-prod-results');
  if (!q) { resultsEl.style.display = 'none'; return; }
  _svcProdSearchTimer = setTimeout(async () => {
    const res   = await API.productSearch(q, 8);
    const items = (res.body?.data || []).filter(p => !_svcProdLines.some(l => l.product_id === p.id));
    if (!items.length) { resultsEl.style.display = 'none'; return; }
    resultsEl.innerHTML = items.map(p =>
      `<div class="svc-prod-result-item" data-prod-id="${p.id}" data-prod-name="${escHtml(p.name)}">${escHtml(p.name)}</div>`
    ).join('');
    resultsEl.style.display = 'block';
    resultsEl.querySelectorAll('.svc-prod-result-item').forEach(row => {
      row.addEventListener('mousedown', e => {
        e.preventDefault();
        _svcAddProdLine(Number(row.dataset.prodId), row.dataset.prodName);
        $('#svc-form-prod-q').value = '';
        resultsEl.style.display = 'none';
      });
    });
  }, 250);
});

$('#svc-form-prod-q')?.addEventListener('blur', () => {
  setTimeout(() => { const r = $('#svc-form-prod-results'); if (r) r.style.display = 'none'; }, 150);
});

function _svcAddProdLine(productId, name) {
  if (_svcProdLines.some(l => l.product_id === productId)) return;
  _svcProdLines.push({ product_id: productId, name, qty: 1 });
  _svcRenderProdLines();
}

function _svcRenderProdLines() {
  const el = $('#svc-form-prod-lines');
  if (!_svcProdLines.length) { el.innerHTML = ''; return; }
  el.innerHTML = _svcProdLines.map((l, i) =>
    `<div class="svc-prod-line" data-idx="${i}">
      <span class="svc-prod-line-name">${escHtml(l.name)}</span>
      <input type="number" class="svc-form-input svc-prod-line-qty" data-idx="${i}" value="${l.qty}" min="0.001" step="0.001">
      <button type="button" class="svc-prod-line-remove" data-idx="${i}" title="Remove"><i class="fa fa-xmark"></i></button>
    </div>`
  ).join('');
  el.querySelectorAll('.svc-prod-line-qty').forEach(inp => {
    inp.addEventListener('change', () => {
      const idx = Number(inp.dataset.idx);
      _svcProdLines[idx].qty = parseFloat(inp.value) || 1;
    });
  });
  el.querySelectorAll('.svc-prod-line-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      const idx = Number(btn.dataset.idx);
      _svcProdLines.splice(idx, 1);
      _svcRenderProdLines();
    });
  });
}

// ── Custom Requirement form builder (Service modal) ───────────────────────
function _svcCreqSlug(label) {
  return String(label || '').trim().toLowerCase()
    .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'field';
}

function _svcCreqAddField() {
  _svcCustomReqFields.push({
    _id: ++_svcCreqIdSeq, key: '', keyEdited: false,
    label: '', type: 'text', options: '',
  });
  _svcRenderCreqFields();
}

function _svcRenderCreqFields() {
  const el    = $('#svc-creq-fields');
  const empty = $('#svc-creq-empty');
  if (!el) return;
  empty.style.display = _svcCustomReqFields.length ? 'none' : '';
  el.innerHTML = _svcCustomReqFields.map(f => `
    <div class="svc-creq-row" data-id="${f._id}">
      <div class="svc-creq-row-main">
        <select class="po-field-input svc-creq-type" data-id="${f._id}">
          <option value="text"${f.type === 'text' ? ' selected' : ''}>Text</option>
          <option value="textarea"${f.type === 'textarea' ? ' selected' : ''}>Textarea</option>
          <option value="select"${f.type === 'select' ? ' selected' : ''}>Dropdown</option>
          <option value="number"${f.type === 'number' ? ' selected' : ''}>Number</option>
          <option value="date"${f.type === 'date' ? ' selected' : ''}>Date</option>
          <option value="checkbox"${f.type === 'checkbox' ? ' selected' : ''}>Checkbox (Yes/No)</option>
          <option value="radio"${f.type === 'radio' ? ' selected' : ''}>Radio buttons</option>
        </select>
        <input type="text" class="po-field-input svc-creq-label" data-id="${f._id}" placeholder="Label, e.g. Installed OS" value="${escHtml(f.label)}">
        <input type="text" class="po-field-input svc-creq-key" data-id="${f._id}" placeholder="Name" value="${escHtml(f.key)}">
        <button type="button" class="svc-prod-line-remove svc-creq-remove" data-id="${f._id}" title="Remove"><i class="fa fa-xmark"></i></button>
      </div>
      <input type="text" class="po-field-input svc-creq-options" data-id="${f._id}" placeholder="Options, comma separated (e.g. 1 Year, 2 Years)"
        style="margin-top:6px;display:${(f.type === 'select' || f.type === 'radio') ? '' : 'none'}" value="${escHtml(f.options)}">
    </div>`
  ).join('');

  el.querySelectorAll('.svc-creq-type').forEach(sel => {
    sel.addEventListener('change', () => {
      const f = _svcCustomReqFields.find(x => x._id === Number(sel.dataset.id));
      if (f) { f.type = sel.value; _svcRenderCreqFields(); }
    });
  });
  el.querySelectorAll('.svc-creq-label').forEach(inp => {
    inp.addEventListener('input', () => {
      const f = _svcCustomReqFields.find(x => x._id === Number(inp.dataset.id));
      if (!f) return;
      f.label = inp.value;
      if (!f.keyEdited) {
        f.key = _svcCreqSlug(inp.value);
        const keyInput = el.querySelector(`.svc-creq-key[data-id="${f._id}"]`);
        if (keyInput) keyInput.value = f.key;
      }
    });
  });
  el.querySelectorAll('.svc-creq-key').forEach(inp => {
    inp.addEventListener('input', () => {
      const f = _svcCustomReqFields.find(x => x._id === Number(inp.dataset.id));
      if (!f) return;
      f.keyEdited = true;
      f.key = inp.value;
    });
  });
  el.querySelectorAll('.svc-creq-options').forEach(inp => {
    inp.addEventListener('input', () => {
      const f = _svcCustomReqFields.find(x => x._id === Number(inp.dataset.id));
      if (f) f.options = inp.value;
    });
  });
  el.querySelectorAll('.svc-creq-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      _svcCustomReqFields = _svcCustomReqFields.filter(x => x._id !== Number(btn.dataset.id));
      _svcRenderCreqFields();
    });
  });
}

