const DS_TYPES = {
  'letterhead':       { label: 'Letterhead',       icon: 'fa-file-lines',   color: '#6366f1', bg: '#6366f120' },
  'company-profile':  { label: 'Business Profile', icon: 'fa-building',     color: '#0ea5e9', bg: '#0ea5e920' },
  'social-media':     { label: 'Social Media',     icon: 'fa-share-nodes',  color: '#ec4899', bg: '#ec489920' },
  'business-card':    { label: 'Business Card',    icon: 'fa-id-card',      color: '#f59e0b', bg: '#f59e0b20' },
  'custom':           { label: 'Custom',           icon: 'fa-paintbrush',   color: '#10b981', bg: '#10b98120' },
};

// These types are singletons — only one allowed per business; shown as fixed cards, not in the list
const DS_SINGLETON_TYPES = ['letterhead', 'company-profile'];

const DS_TYPE_DEFAULTS = {
  'letterhead':       { w: 794,  h: 1123,  title: 'Business Letterhead' },
  'company-profile':  { w: 1920, h: 1080,  title: 'Business Profile' },
  'social-media':     { w: 1080, h: 1080,  title: '' },
  'business-card':    { w: 1050, h: 600,   title: '' },
};

let _dsActiveType = 'all';
let _dsAllData    = [];

function switchDesignView(type) {
  _dsActiveType = type || 'all';
  $$('#panel-design .fin-subnav .fin-subnav-btn[data-ds]').forEach(b => {
    b.classList.toggle('active', b.dataset.ds === _dsActiveType);
  });

  const propView   = $('#ds-proposals-view');
  const listView   = $('#ds-list-view');
  const singletons = $('.ds-singletons');

  if (type === 'proposals') {
    if (propView)   propView.style.display   = 'flex';
    if (listView)   listView.style.display   = 'none';
    if (singletons) singletons.style.display = 'none';
    if (typeof window._dsLoadProposals === 'function') window._dsLoadProposals();
    return;
  }

  if (propView)   propView.style.display   = 'none';
  if (listView)   listView.style.display   = '';
  if (singletons) singletons.style.display = '';
  _dsAllData = [];
  loadDesigns();
}

const DS_EMPTY_META = {
  'all':          { icon: 'fa-paintbrush',        color: '#6366f1', bg: '#6366f120', title: 'No designs yet',            sub: 'Create your first social media post, business card, or custom design.' },
  'social-media': { icon: 'fa-share-nodes',        color: '#ec4899', bg: '#ec489920', title: 'No social media posts yet', sub: 'Design eye-catching posts for Instagram, Facebook, YouTube and more.' },
  'business-card':{ icon: 'fa-id-card',            color: '#f59e0b', bg: '#f59e0b20', title: 'No business cards yet',    sub: 'Create sleek, professional business card designs ready to print.' },
  'custom':       { icon: 'fa-wand-magic-sparkles', color: '#10b981', bg: '#10b98120', title: 'No custom designs yet',   sub: 'Start with a blank canvas at any size for your own creative projects.' },
};

function updateSingletonCards() {
  DS_SINGLETON_TYPES.forEach(type => {
    const design   = _dsAllData.find(d => d.type === type);
    const statusEl = $('#ds-singleton-status-' + type);
    if (!statusEl) return;
    if (design) {
      statusEl.className = 'ds-singleton-badge ds-singleton-badge-ready';
      statusEl.innerHTML = '<i class="fa fa-pen-to-square"></i> ' + escHtml(design.has_canvas ? 'Edit' : 'Open');
    } else {
      statusEl.className = 'ds-singleton-badge ds-singleton-badge-new';
      statusEl.innerHTML = '<i class="fa fa-plus"></i> Create';
    }
  });
}

async function loadDesigns() {
  const search = ($('#ds-search').value || '').toLowerCase().trim();
  const area   = $('#ds-cards-area');

  if (_dsAllData.length === 0) {
    area.innerHTML = '<div class="ds-loading"><i class="fa fa-spinner fa-spin"></i> Loading designs…</div>';
    const res = await API.designs();
    if (res.status !== 200) {
      area.innerHTML = '<div class="ds-empty"><div class="ds-empty-icon-wrap" style="background:#fef2f2;color:#dc2626"><i class="fa fa-triangle-exclamation"></i></div><p class="ds-empty-title">Failed to load designs</p><p class="ds-empty-sub">Check your connection and try again.</p></div>';
      return;
    }
    // Only overwrite if still empty — prevents a concurrent openSingletonDesign
    // call that already populated the array from being clobbered by this stale response.
    if (_dsAllData.length === 0) {
      _dsAllData = res.body?.data || [];
    } else {
      // Merge server data in without losing any items already added client-side
      const serverIds = new Set((res.body?.data || []).map(d => d.id));
      const clientOnly = _dsAllData.filter(d => !serverIds.has(d.id));
      _dsAllData = [...(res.body?.data || []), ...clientOnly];
    }

    const byType = res.body?.by_type || {};
    $('#ds-total-count').textContent          = res.body?.total_count ?? _dsAllData.length;
    $('#ds-count-social-media').textContent   = byType['social-media']   ?? 0;
    $('#ds-count-business-card').textContent  = byType['business-card']  ?? 0;
    $('#ds-count-custom').textContent         = byType['custom']         ?? 0;
    updateSingletonCards();
  }

  // Singletons are shown in their own section — exclude from the list
  let list = _dsAllData.filter(d => !DS_SINGLETON_TYPES.includes(d.type));
  if (_dsActiveType !== 'all') {
    if (_dsActiveType === 'custom') {
      list = list.filter(d => !d.type || d.type === 'custom');
    } else {
      list = list.filter(d => d.type === _dsActiveType);
    }
  }
  if (search) {
    list = list.filter(d => (d.title || '').toLowerCase().includes(search));
  }

  if (list.length === 0) {
    const em = DS_EMPTY_META[_dsActiveType] || DS_EMPTY_META['all'];
    const btnLabel = _dsActiveType !== 'all'
      ? `New ${DS_TYPES[_dsActiveType]?.label || 'Design'}`
      : 'New Design';
    area.innerHTML = `
      <div class="ds-empty">
        <div class="ds-empty-icon-wrap" style="background:${em.bg};color:${em.color}">
          <i class="fa ${em.icon}"></i>
        </div>
        <p class="ds-empty-title">${em.title}</p>
        <p class="ds-empty-sub">${em.sub}</p>
        <button class="ds-empty-btn" onclick="openDsCreateModal()">
          <i class="fa fa-plus"></i> ${escHtml(btnLabel)}
        </button>
      </div>`;
    $('#ds-footer-text').textContent = '';
    return;
  }

  area.innerHTML = list.map(buildDesignCard).join('');
  $('#ds-footer-text').textContent = `${list.length} design${list.length !== 1 ? 's' : ''}`;

  area.querySelectorAll('.ds-delete-btn').forEach(btn => {
    btn.addEventListener('click', async () => {
      const id    = parseInt(btn.dataset.id, 10);
      const title = btn.dataset.title;
      if (!confirm(`Delete "${title}"? This cannot be undone.`)) return;
      btn.disabled = true;
      const res = await API.deleteDesign(id);
      if (res.status === 200) {
        toast('Design deleted.', 'success');
        _dsAllData = _dsAllData.filter(d => d.id !== id);
        loadDesigns();
      } else {
        btn.disabled = false;
        toast(res.body?.message || 'Failed to delete design.', 'error');
      }
    });
  });

  area.querySelectorAll('.ds-open-btn').forEach(btn => {
    btn.addEventListener('click', () => openDesignEditor(parseInt(btn.dataset.id, 10)));
  });
}

async function openDesignEditor(id) {
  const btn = $('#ds-cards-area').querySelector(`.ds-open-btn[data-id="${id}"]`);
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>'; }
  const res = await API.design(id);
  if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa fa-pen-to-square"></i>'; }
  if (res.status === 200 && res.body?.data) {
    await window.electronAPI.openEditor(res.body.data);
  } else {
    toast(res.body?.message || 'Failed to open editor.', 'error');
  }
}

async function openSingletonDesign(type) {
  const cardEl = $('#ds-singleton-' + type);
  if (cardEl) cardEl.classList.add('ds-singleton-loading');

  try {
    // Load all designs if not yet cached
    if (_dsAllData.length === 0) {
      const list = await API.designs();
      if (list.status === 200) {
        // Only overwrite if still empty — avoids clobbering data another
        // concurrent call (e.g. loadDesigns) may have written between the
        // fetch start and now.
        if (_dsAllData.length === 0) {
          _dsAllData = list.body?.data || [];
        }
        updateSingletonCards();
      }
    }

    let design = _dsAllData.find(d => d.type === type);

    if (!design) {
      // Auto-create the singleton with fixed defaults
      const def = DS_TYPE_DEFAULTS[type];
      const createRes = await API.createDesign({
        title: def.title,
        type,
        width:  def.w,
        height: def.h,
      });
      if (createRes.status === 201) {
        design = createRes.body.data;
        _dsAllData.push(design);
        updateSingletonCards();
      } else if (createRes.status === 422 && createRes.body?.data) {
        // Singleton already existed on the server — use the returned record
        design = createRes.body.data;
        if (!_dsAllData.find(d => d.id === design.id)) {
          _dsAllData.push(design);
          updateSingletonCards();
        }
      } else {
        toast(createRes.body?.message || 'Failed to create design.', 'error');
        return;
      }
    }

    // Fetch full design (includes canvas_json) then open editor
    const res = await API.design(design.id);
    if (res.status === 200 && res.body?.data) {
      const fresh = res.body.data;
      // Sync has_canvas in the cache so the badge shows the right state
      const idx = _dsAllData.findIndex(d => d.id === fresh.id);
      if (idx !== -1) {
        _dsAllData[idx] = { ..._dsAllData[idx], has_canvas: fresh.has_canvas };
        updateSingletonCards();
      }
      await window.electronAPI.openEditor(fresh);
    } else {
      toast(res.body?.message || 'Failed to open editor.', 'error');
    }
  } catch (err) {
    toast(err?.message || 'Failed to open design.', 'error');
  } finally {
    if (cardEl) cardEl.classList.remove('ds-singleton-loading');
  }
}

function buildDesignCard(d) {
  const typeKey = d.type || 'custom';
  const t  = DS_TYPES[typeKey] || DS_TYPES['custom'];
  const dim  = `${d.width} × ${d.height}`;
  const date = d.updated_at ? d.updated_at.split(' ')[0] : (d.created_at || '');
  const canvasBadge = d.has_canvas
    ? `<span class="ds-card-pill" style="background:#10b98115;color:#059669"><i class="fa fa-check"></i> Saved</span>`
    : `<span class="ds-card-pill"><i class="fa fa-plus"></i> New</span>`;

  return `<div class="ds-card">
    <div class="ds-card-bar" style="background:${t.color}"></div>
    <div class="ds-card-body">
      <div class="ds-card-top">
        <div class="ds-card-icon" style="background:${t.bg};color:${t.color}"><i class="fa ${t.icon}"></i></div>
        <div class="ds-card-meta">
          <span class="ds-card-title" title="${escHtml(d.title || 'Untitled')}">${escHtml(d.title || 'Untitled')}</span>
          <span class="ds-card-type-badge" style="background:${t.bg};color:${t.color}">${escHtml(t.label)}</span>
        </div>
      </div>
      <div class="ds-card-pills">
        <span class="ds-card-pill"><i class="fa fa-ruler-combined"></i> ${escHtml(dim)}</span>
        ${canvasBadge}
      </div>
    </div>
    <div class="ds-card-footer">
      <span class="ds-card-date"><i class="fa fa-clock" style="margin-right:3px"></i>${escHtml(date)}</span>
      <div style="display:flex;gap:5px;align-items:center">
        <button class="ds-open-btn" data-id="${d.id}" title="Open in editor"><i class="fa fa-pen-to-square"></i></button>
        <button class="ds-delete-btn" data-id="${d.id}" data-title="${escHtml(d.title || 'Untitled')}" title="Delete design"><i class="fa fa-trash"></i></button>
      </div>
    </div>
  </div>`;
}

// ── Design: context menu & Send as Email ───────────────────────────────────

let _dsCtxDesignId    = null;   // design id that was right-clicked
let _dsEmailDesign    = null;   // full design object (id, title, width, height)
let _dsEmailCustomers = [];     // cached for the dropdown

// Show context menu at cursor position
function _dsShowCtx(e, designId) {
  e.preventDefault();
  _dsCtxDesignId = designId;
  const menu = $('#ds-ctx-menu');
  menu.style.display = 'block';
  // Keep within viewport
  const vw = window.innerWidth, vh = window.innerHeight;
  const mw = 190, mh = 50;
  menu.style.left = (e.clientX + mw > vw ? e.clientX - mw : e.clientX) + 'px';
  menu.style.top  = (e.clientY + mh > vh ? e.clientY - mh : e.clientY) + 'px';
}

function _dsHideCtx() {
  $('#ds-ctx-menu').style.display = 'none';
}

document.addEventListener('click',       _dsHideCtx);
document.addEventListener('contextmenu', (e) => {
  const card = e.target.closest('.ds-card');
  // Only show on design cards inside ds-cards-area; suppress otherwise
  if (!card || !card.closest('#ds-cards-area')) { _dsHideCtx(); return; }
  const id = parseInt(card.querySelector('[data-id]')?.dataset.id, 10);
  if (!id) return;
  _dsShowCtx(e, id);
});

$('#ds-ctx-email').addEventListener('click', async () => {
  _dsHideCtx();
  if (!_dsCtxDesignId) return;

  // Always fetch fresh from server — cached has_canvas may be stale if the
  // user saved in the editor after the list was last loaded.
  const r = await API.design(_dsCtxDesignId);
  if (r.status !== 200) { toast('Failed to load design.', 'error'); return; }
  const design = r.body?.data;
  if (!design) { toast('Design not found.', 'error'); return; }

  // Update the local cache entry so the card badge reflects reality
  const idx = (_dsAllData || []).findIndex(d => d.id === design.id);
  if (idx !== -1) _dsAllData[idx] = { ..._dsAllData[idx], has_canvas: design.has_canvas };

  _dsEmailDesign = design;
  $('#ds-email-design-name').textContent = design.title || 'Untitled';
  $('#ds-email-subject').value  = `${design.title || 'Design'} — from us`;
  $('#ds-email-addr').value     = '';
  $('#ds-email-body').value     = '';
  $('#ds-email-alert').style.display = 'none';
  $('#ds-email-customer').value = '';

  // Populate customers dropdown
  const sel = $('#ds-email-customer');
  if (_dsEmailCustomers.length === 0) {
    sel.innerHTML = '<option value="">Loading…</option>';
    const cr = await API.customers('');
    if (cr.status === 200) {
      _dsEmailCustomers = (cr.body?.data || []).filter(c => c.email);
    }
  }
  sel.innerHTML = '<option value="">— Select a customer —</option>' +
    _dsEmailCustomers.map(c => `<option value="${escHtml(c.email)}">${escHtml(c.name)} (${escHtml(c.email)})</option>`).join('');

  $('#ds-email-modal').style.display = 'flex';
});

// When customer is selected, fill address field
$('#ds-email-customer').addEventListener('change', function () {
  if (this.value) $('#ds-email-addr').value = '';
});
$('#ds-email-addr').addEventListener('input', function () {
  if (this.value.trim()) $('#ds-email-customer').value = '';
});

function _dsEmailClose() {
  $('#ds-email-modal').style.display = 'none';
  _dsEmailDesign = null;
}
$('#ds-email-close').addEventListener('click',  _dsEmailClose);
$('#ds-email-cancel').addEventListener('click', _dsEmailClose);
$('#ds-email-modal').addEventListener('click', (e) => {
  if (e.target === e.currentTarget) _dsEmailClose();
});

$('#ds-email-send').addEventListener('click', async () => {
  const alert  = $('#ds-email-alert');
  const sendBtn  = $('#ds-email-send');
  const sendLbl  = $('#ds-email-send-lbl');

  alert.style.display = 'none';

  const customerEmail = $('#ds-email-customer').value.trim();
  const manualEmail   = $('#ds-email-addr').value.trim();
  const to            = customerEmail || manualEmail;
  const subject       = $('#ds-email-subject').value.trim();
  const body          = $('#ds-email-body').value.trim() ||
    `Please find the attached design "${_dsEmailDesign?.title || ''}" in the PDF.`;

  if (!to) {
    alert.textContent    = 'Please select a customer or enter an email address.';
    alert.style.display  = 'block';
    return;
  }
  if (!subject) {
    alert.textContent   = 'Subject is required.';
    alert.style.display = 'block';
    return;
  }

  sendBtn.disabled = true;
  sendLbl.textContent = 'Exporting PDF…';

  try {
    // canvas_json is already on _dsEmailDesign (fetched fresh when modal opened)
    const canvasJson = _dsEmailDesign.canvas_json;
    if (!canvasJson) throw new Error('Design has no saved canvas. Open it in the editor, draw something, then save.');

    const pdfBase64 = await window.electronAPI.renderDesignToPdf(
      canvasJson,
      _dsEmailDesign.width  || 800,
      _dsEmailDesign.height || 600,
    );
    if (!pdfBase64) throw new Error('PDF export failed. Please try again.');

    sendLbl.textContent = 'Sending…';

    const res = await API.mailSend({
      to,
      subject,
      body,
      attachment_base64: pdfBase64,
      attachment_name:   ((_dsEmailDesign.title || 'design').replace(/[^a-z0-9_-]/gi, '_')) + '.pdf',
    });

    if (res.status !== 200) {
      throw new Error(res.body?.message || 'Failed to send email. Check your mail settings.');
    }

    _dsEmailClose();
    toast(`Email sent to ${to}`, 'success');

  } catch (err) {
    alert.textContent   = err.message || 'An unexpected error occurred.';
    alert.style.display = 'block';
  } finally {
    sendBtn.disabled = false;
    sendLbl.textContent = 'Send';
  }
});

// ── Design: subnav ─────────────────────────────────────────────────────────
$('#panel-design .fin-subnav').addEventListener('click', e => {
  const btn = e.target.closest('[data-ds]');
  if (btn) switchDesignView(btn.dataset.ds);
});

$('#ds-search').addEventListener('input', () => loadDesigns());

$('#ds-new-btn').addEventListener('click', openDsCreateModal);

// ── Design: singleton cards ────────────────────────────────────────────────
$('#ds-singleton-letterhead').addEventListener('click',      () => openSingletonDesign('letterhead'));
$('#ds-singleton-company-profile').addEventListener('click', () => openSingletonDesign('company-profile'));

// ── Design: ribbon buttons ─────────────────────────────────────────────────
$('#rb-design-new').addEventListener('click', () => { activateTab('design'); openDsCreateModal(); });
$('#rb-design-all').addEventListener('click', () => { activateTab('design'); switchDesignView('all'); });
// Singletons: ribbon buttons open/create directly in the editor
$('#rb-design-letterhead').addEventListener('click',      () => { activateTab('design'); openSingletonDesign('letterhead'); });
$('#rb-design-company-profile').addEventListener('click', () => { activateTab('design'); openSingletonDesign('company-profile'); });
$('#rb-design-social-media').addEventListener('click',    () => { activateTab('design'); switchDesignView('social-media'); });
$('#rb-design-business-card').addEventListener('click',   () => { activateTab('design'); switchDesignView('business-card'); });

// ── Design: Create Modal ───────────────────────────────────────────────────

function openDsCreateModal() {
  $('#ds-modal-title').value  = '';
  $('#ds-modal-type').value   = _dsActiveType !== 'all' && _dsActiveType !== 'custom' ? _dsActiveType : '';
  $('#ds-modal-preset').value = '';
  _dsApplyTypeDefaults($('#ds-modal-type').value);
  showDsError('');
  $('#ds-create-modal').style.display = '';
  setTimeout(() => $('#ds-modal-title').focus(), 60);
}

function closeDsCreateModal() {
  $('#ds-create-modal').style.display = 'none';
}

function showDsError(msg) {
  const el = $('#ds-create-alert');
  el.textContent = msg;
  el.style.display = msg ? '' : 'none';
}

function _dsApplyTypeDefaults(type) {
  const d = DS_TYPE_DEFAULTS[type];
  if (d) {
    $('#ds-modal-width').value  = d.w;
    $('#ds-modal-height').value = d.h;
  }
}

$('#ds-modal-type').addEventListener('change', () => {
  $('#ds-modal-preset').value = '';
  _dsApplyTypeDefaults($('#ds-modal-type').value);
});

$('#ds-modal-preset').addEventListener('change', () => {
  const val = $('#ds-modal-preset').value;
  if (!val) return;
  const [w, h] = val.split('x').map(Number);
  $('#ds-modal-width').value  = w;
  $('#ds-modal-height').value = h;
});

$('#ds-create-modal-close').addEventListener('click', closeDsCreateModal);
$('#ds-create-modal-cancel').addEventListener('click', closeDsCreateModal);
$('#ds-create-modal').addEventListener('click', e => { if (e.target === $('#ds-create-modal')) closeDsCreateModal(); });

$('#ds-create-modal-save').addEventListener('click', submitDsCreate);

async function submitDsCreate() {
  const title  = $('#ds-modal-title').value.trim();
  const type   = $('#ds-modal-type').value.trim() || null;
  const width  = parseInt($('#ds-modal-width').value, 10);
  const height = parseInt($('#ds-modal-height').value, 10);

  if (!title) { showDsError('Design title is required.'); return; }
  if (!width  || width  < 100 || width  > 8000) { showDsError('Width must be between 100 and 8000 px.'); return; }
  if (!height || height < 100 || height > 8000) { showDsError('Height must be between 100 and 8000 px.'); return; }

  const btn = $('#ds-create-modal-save');
  btn.disabled = true;
  btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Creating…';

  const res = await API.createDesign({ title, type, width, height });

  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-plus"></i> Create Design';

  if (res.status === 201) {
    closeDsCreateModal();
    toast('Design created.', 'success');
    _dsAllData = [];
    switchDesignView(_dsActiveType);
  } else {
    const msg = res.body?.errors?.title?.[0] || res.body?.message || 'Failed to create design.';
    showDsError(msg);
  }
}

// ── Project Proposals ─────────────────────────────────────────────────────
(function () {
  const PAGE_META = {
    1: { icon: 'fa-star',          color: '#7c3aed', bg: '#7c3aed15', label: 'Cover Page' },
    2: { icon: 'fa-align-left',    color: '#0284c7', bg: '#0284c715', label: 'Executive Summary' },
    3: { icon: 'fa-list-check',    color: '#059669', bg: '#05996915', label: 'Our Services' },
    4: { icon: 'fa-calendar-days', color: '#f59e0b', bg: '#f59e0b15', label: 'Project Timeline' },
    5: { icon: 'fa-dollar-sign',   color: '#ec4899', bg: '#ec489915', label: 'Investment & Pricing' },
    6: { icon: 'fa-handshake',     color: '#8b5cf6', bg: '#8b5cf615', label: 'Contact & Next Steps' },
  };

  let _propData = [];

  // ── Load proposals ────────────────────────────────────────────────────────
  async function loadProposals() {
    const area = $('#ds-proposals-area');
    if (!area) return;
    area.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-muted);font-size:13px"><i class="fa fa-spinner fa-spin" style="margin-bottom:8px;display:block;font-size:24px"></i>Loading proposals…</div>';
    const res = await API.proposals();
    if (res.status !== 200) {
      area.innerHTML = '<div style="text-align:center;padding:40px;color:#ef4444;font-size:13px">Failed to load proposals.</div>';
      return;
    }
    _propData = res.body?.data || [];
    renderProposals();
  }

  function renderProposals() {
    const area = $('#ds-proposals-area');
    if (!area) return;
    if (!_propData.length) {
      area.innerHTML = `
        <div class="ds-proposals-empty">
          <i class="fa fa-file-contract"></i>
          <div class="ds-proposals-empty-title">No project proposals yet</div>
          <div class="ds-proposals-empty-sub">Create a multi-page project proposal and open each page in the Design Studio.</div>
          <button class="svc-form-btn svc-form-btn--primary" onclick="document.getElementById('ds-prop-new-btn').click()">
            <i class="fa fa-plus"></i> New Project Proposal
          </button>
        </div>`;
      return;
    }

    area.innerHTML = _propData.map(p => buildProposalCard(p)).join('');

    // Delete
    area.querySelectorAll('.ds-proposal-del').forEach(btn => {
      btn.addEventListener('click', async e => {
        e.stopPropagation();
        const group = btn.dataset.group;
        const title = btn.dataset.title;
        if (!confirm(`Delete proposal "${title}" and all its pages? This cannot be undone.`)) return;
        btn.disabled = true;
        const res = await API.deleteProposal(group);
        if (res.status === 200) {
          _propData = _propData.filter(p => p.group !== group);
          renderProposals();
          toast('Proposal deleted.', 'success');
        } else {
          btn.disabled = false;
          toast(res.body?.message || 'Failed to delete.', 'error');
        }
      });
    });

    // Edit — open all pages in the multi-page editor
    area.querySelectorAll('.ds-prop-edit-btn').forEach(btn => {
      btn.addEventListener('click', async e => {
        e.stopPropagation();
        const group = btn.dataset.group;
        btn.disabled = true;
        btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>';
        const res = await API.proposalPages(group);
        btn.disabled = false;
        btn.innerHTML = '<i class="fa fa-pen-to-square"></i> Edit';
        if (res.status === 200 && res.body?.data) {
          const prop = res.body.data;
          await window.electronAPI.openEditor({
            proposalTitle:     prop.title,
            proposalGroup:     prop.group,
            proposalPages:     prop.pages,
            proposalStartPage: 0,
            width:             prop.pages[0]?.width  ?? 794,
            height:            prop.pages[0]?.height ?? 1123,
            id:                prop.pages[0]?.id,
            type:              'project-proposal',
            title:             prop.title,
          });
        } else {
          toast('Failed to load proposal.', 'error');
        }
      });
    });
  }

  function buildProposalCard(p) {
    const savedCount  = p.pages?.filter(pg => pg.has_canvas).length || 0;
    const totalCount  = p.pages?.length || 0;
    const updatedDate = p.updated_at ? p.updated_at.split(' ')[0] : '—';
    const clientBadge = p.client
      ? `<span class="ds-card-type-badge" style="background:#7c3aed15;color:#7c3aed;border:1px solid #7c3aed25">
           <i class="fa fa-user"></i> ${escHtml(p.client)}
         </span>`
      : `<span class="ds-card-type-badge" style="background:#7c3aed15;color:#7c3aed;border:1px solid #7c3aed25">
           <i class="fa fa-file-contract"></i> Proposal
         </span>`;

    return `
      <div class="ds-proposal-card">
        <div class="ds-proposal-bar"></div>
        <div class="ds-card-body">
          <div class="ds-card-top">
            <div class="ds-card-icon" style="background:#7c3aed15;color:#7c3aed;font-size:20px">
              <i class="fa fa-file-contract"></i>
            </div>
            <div class="ds-card-meta">
              <span class="ds-card-title" title="${escHtml(p.title)}">${escHtml(p.title)}</span>
              ${clientBadge}
            </div>
          </div>
          <div class="ds-card-pills">
            <span class="ds-card-pill"><i class="fa fa-layer-group"></i> ${totalCount} pages</span>
            <span class="ds-card-pill" style="${savedCount > 0 ? 'color:#059669' : ''}">
              <i class="fa fa-${savedCount > 0 ? 'check-circle' : 'circle-dot'}"></i> ${savedCount} saved
            </span>
          </div>
        </div>
        <div class="ds-card-footer">
          <span class="ds-card-date">${escHtml(updatedDate)}</span>
          <div style="display:flex;gap:5px;align-items:center">
            <button class="ds-prop-edit-btn" data-group="${escHtml(p.group)}">
              <i class="fa fa-pen-to-square"></i> Edit
            </button>
            <button class="ds-delete-btn ds-proposal-del" data-group="${escHtml(p.group)}" data-title="${escHtml(p.title)}" title="Delete proposal">
              <i class="fa fa-trash"></i>
            </button>
          </div>
        </div>
      </div>`;
  }

  // ── Create proposal modal ─────────────────────────────────────────────────
  let _propGenMode = 'blank'; // 'blank' | 'ai'

  function _setPropGenMode(mode) {
    _propGenMode = mode;
    const blankBtn = $('#ds-gen-blank-btn');
    const aiBtn    = $('#ds-gen-ai-btn');
    const aiSect   = $('#ds-gen-ai-section');
    const saveBtn  = $('#ds-prop-modal-save');
    if (mode === 'ai') {
      blankBtn?.classList.remove('ds-gen-tab--active');
      aiBtn?.classList.add('ds-gen-tab--active');
      if (aiSect)  aiSect.style.display  = '';
      if (saveBtn) { saveBtn.dataset.mode = 'ai'; saveBtn.innerHTML = '<i class="fa fa-wand-magic-sparkles"></i> Generate with AI'; }
    } else {
      aiBtn?.classList.remove('ds-gen-tab--active');
      blankBtn?.classList.add('ds-gen-tab--active');
      if (aiSect)  aiSect.style.display  = 'none';
      if (saveBtn) { saveBtn.dataset.mode = 'blank'; saveBtn.innerHTML = '<i class="fa fa-file-contract"></i> Create Proposal'; }
    }
  }

  function openProposalModal() {
    $('#ds-prop-title').value  = '';
    $('#ds-prop-client').value = '';
    const desc = $('#ds-prop-desc');
    if (desc) desc.value = '';
    $('#ds-prop-alert').style.display = 'none';
    _setPropGenMode('blank');
    $('#ds-prop-modal').style.display = 'flex';
    setTimeout(() => $('#ds-prop-title')?.focus(), 60);
  }
  function closeProposalModal() {
    $('#ds-prop-modal').style.display = 'none';
  }

  // ── Canvas template builder for AI-generated pages ────────────────────────
  function _buildProposalCanvas(sort, ai, propTitle, propClient) {
    const W = 794, H = 1123;
    const P   = '#7c3aed', PD = '#6d28d9', PDK = '#1e1b4b';
    const TX  = '#1f2937', MT  = '#6b7280', WH  = '#ffffff', PL = '#f5f3ff';
    const objs = [];

    function rct(l, t, w, h, fill, op) {
      const o = { type:'rect', left:l, top:t, width:w, height:h, fill:fill, selectable:true, evented:true };
      if (op !== undefined) o.opacity = op;
      return o;
    }
    function txt(str, l, t, w, size, bold, color, font, lh) {
      return {
        type: 'textbox',
        text: String(str || ' ').substring(0, 600),
        left: l, top: t, width: w || W - 100,
        fontSize: size || 13,
        fontWeight: bold ? 'bold' : 'normal',
        fill: color || TX,
        fontFamily: font || 'Inter',
        lineHeight: lh || 1.5,
        selectable: true, evented: true,
      };
    }
    function pageHeader(title) {
      objs.push(rct(0, 0, W, 100, P));
      objs.push(rct(0, 100, W, 4, PD));
      objs.push(txt(title, 50, 30, W - 100, 26, true, WH, 'Montserrat', 1.2));
      const sub = propTitle + (propClient ? '  ·  ' + propClient : '');
      objs.push(txt(sub, 50, 67, W - 100, 10, false, 'rgba(255,255,255,0.6)', 'Inter', 1));
    }

    switch (sort) {
      case 1: { // Cover Page
        objs.push(rct(0, 0, W, H, PDK));
        objs.push(rct(0, 0, 6, H, P));
        objs.push(rct(0, 0, W, 5, P));
        objs.push(rct(0, H - 5, W, 5, P));
        objs.push(txt(propTitle || 'Project Proposal', 50, 230, W - 100, 50, true, WH, 'Montserrat', 1.15));
        if (propClient) {
          objs.push(txt('PREPARED FOR', 50, 355, 200, 9, true, 'rgba(167,139,250,0.8)', 'Inter', 1));
          objs.push(txt(propClient, 50, 373, W - 100, 20, true, 'rgba(255,255,255,0.85)', 'Montserrat', 1.2));
        }
        const tagY = propClient ? 420 : 360;
        if (ai?.tagline) objs.push(txt(ai.tagline, 50, tagY, W - 100, 14, false, 'rgba(255,255,255,0.55)', 'Inter', 1.4));
        const dateStr = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long' });
        objs.push(txt(dateStr, 50, H - 52, 300, 11, false, 'rgba(255,255,255,0.35)', 'Inter', 1));
        return JSON.stringify({ version: '5.3.0', objects: objs, background: PDK });
      }
      case 2: { // Executive Summary
        pageHeader('Executive Summary');
        let y = 128;
        if (ai?.summary) {
          objs.push(txt(ai.summary, 50, y, W - 100, 13, false, TX, 'Inter', 1.65));
          y += Math.min(Math.ceil(ai.summary.length / 80) * 22 + 30, 120);
        }
        if (ai?.summary_points?.length) {
          objs.push(txt('Key Highlights', 50, y, W - 100, 15, true, PD, 'Montserrat', 1.2));
          y += 32;
          (ai.summary_points || []).forEach(pt => {
            objs.push(rct(50, y + 5, 4, 13, P));
            objs.push(txt(pt, 66, y, W - 130, 13, false, TX, 'Inter', 1.4));
            y += 30;
          });
        }
        return JSON.stringify({ version: '5.3.0', objects: objs, background: WH });
      }
      case 3: { // Our Services
        pageHeader('Our Services');
        let y = 125;
        (ai?.services || []).forEach((svc, i) => {
          if (i > 0) { objs.push(rct(50, y, W - 100, 1, '#e5e7eb')); y += 12; }
          objs.push(rct(50, y + 2, 3, 40, P));
          objs.push(txt(svc.name || '', 63, y + 2, W - 160, 14, true, PDK, 'Montserrat', 1.2));
          objs.push(txt(svc.desc || '', 63, y + 22, W - 160, 12, false, MT, 'Inter', 1.4));
          y += 58;
        });
        return JSON.stringify({ version: '5.3.0', objects: objs, background: WH });
      }
      case 4: { // Project Timeline
        pageHeader('Project Timeline');
        let y = 125;
        const phColors = [P, '#059669', '#f59e0b', '#ef4444', '#0284c7'];
        (ai?.timeline || []).forEach((ph, i) => {
          const col = phColors[i % phColors.length];
          objs.push(rct(50, y + 8, 14, 14, col)); // dot (rx not in minimal JSON, still round-ish)
          if (i < (ai.timeline.length - 1)) objs.push(rct(56, y + 22, 2, 52, '#e5e7eb'));
          objs.push(txt(ph.phase || ('Phase ' + (i + 1)), 76, y, 100, 10, true, col, 'Inter', 1));
          objs.push(txt(ph.title || '', 76, y + 14, W - 260, 14, true, PDK, 'Montserrat', 1.15));
          if (ph.duration) {
            objs.push(rct(W - 176, y + 10, 126, 22, PL));
            objs.push(txt(ph.duration, W - 172, y + 14, 118, 11, false, PD, 'Inter', 1));
          }
          objs.push(txt(ph.desc || '', 76, y + 32, W - 200, 12, false, MT, 'Inter', 1.4));
          y += 76;
        });
        return JSON.stringify({ version: '5.3.0', objects: objs, background: WH });
      }
      case 5: { // Investment & Pricing
        pageHeader('Investment & Pricing');
        let y = 128;
        const pr = ai?.pricing || {};
        if (pr.subtitle) {
          objs.push(txt(pr.subtitle, 50, y, W - 100, 16, true, PDK, 'Montserrat', 1.2));
          y += 36;
        }
        objs.push(rct(50, y, W - 100, 38, PDK));
        objs.push(txt('Service / Deliverable', 66, y + 11, 360, 11, true, WH, 'Inter', 1));
        objs.push(txt('Amount', W - 186, y + 11, 110, 11, true, WH, 'Inter', 1));
        y += 38;
        (pr.items || []).forEach((item, i) => {
          const bg = i % 2 === 0 ? WH : PL;
          objs.push(rct(50, y, W - 100, 36, bg));
          objs.push(txt(item.name || '', 66, y + 11, 340, 12, false, TX, 'Inter', 1));
          objs.push(txt(item.amount || '', W - 186, y + 11, 110, 12, false, TX, 'Inter', 1));
          y += 36;
        });
        y += 6;
        objs.push(rct(50, y, W - 100, 50, P));
        objs.push(txt('TOTAL INVESTMENT', 66, y + 16, 280, 12, true, WH, 'Montserrat', 1));
        objs.push(txt(pr.total || '', W - 200, y + 12, 140, 22, true, WH, 'Montserrat', 1));
        if (pr.note) {
          y += 66;
          objs.push(txt(pr.note, 50, y, W - 100, 11, false, MT, 'Inter', 1.4));
        }
        return JSON.stringify({ version: '5.3.0', objects: objs, background: WH });
      }
      case 6: { // Contact & Next Steps
        pageHeader('Contact & Next Steps');
        let y = 128;
        const ct = ai?.contact || {};
        if (ct.intro) {
          objs.push(txt(ct.intro, 50, y, W - 100, 13, false, TX, 'Inter', 1.65));
          y += Math.min(Math.ceil(ct.intro.length / 90) * 22 + 28, 80);
        }
        objs.push(txt('Next Steps', 50, y, W - 100, 16, true, PDK, 'Montserrat', 1.2));
        y += 30;
        (ct.steps || []).forEach((step, i) => {
          objs.push(rct(50, y, 26, 26, P));
          objs.push(txt(String(i + 1), 58, y + 7, 18, 11, true, WH, 'Montserrat', 1));
          objs.push(txt(step, 86, y + 7, W - 160, 13, false, TX, 'Inter', 1.4));
          y += 46;
        });
        y += 20;
        objs.push(rct(50, y, W - 100, 1, '#e5e7eb'));
        y += 20;
        objs.push(txt('Ready to get started? We look forward to working with you.', 50, y, W - 100, 14, true, P, 'Montserrat', 1.2));
        return JSON.stringify({ version: '5.3.0', objects: objs, background: WH });
      }
      default:
        return JSON.stringify({ version: '5.3.0', objects: [], background: WH });
    }
  }

  // Expose loadProposals so switchDesignView can call it
  window._dsLoadProposals = loadProposals;

  $('#ds-prop-modal-close')?.addEventListener('click',  closeProposalModal);
  $('#ds-prop-modal-cancel')?.addEventListener('click', closeProposalModal);
  $('#ds-prop-modal')?.addEventListener('click', e => { if (e.target === e.currentTarget) closeProposalModal(); });

  $('#ds-gen-blank-btn')?.addEventListener('click', () => _setPropGenMode('blank'));
  $('#ds-gen-ai-btn')?.addEventListener('click',    () => _setPropGenMode('ai'));

  $('#ds-prop-new-btn')?.addEventListener('click', openProposalModal);
  $('#rb-design-proposals')?.addEventListener('click', () => {
    activateTab('design');
    switchDesignView('proposals');
  });
  $('#rb-design-new-proposal')?.addEventListener('click', () => {
    activateTab('design');
    switchDesignView('proposals');
    openProposalModal();
  });

  $('#ds-prop-modal-save')?.addEventListener('click', async () => {
    const title   = $('#ds-prop-title').value.trim();
    const client  = $('#ds-prop-client').value.trim();
    const desc    = ($('#ds-prop-desc')?.value || '').trim();
    const alertEl = $('#ds-prop-alert');
    const btn     = $('#ds-prop-modal-save');
    const isAi    = _propGenMode === 'ai';

    alertEl.style.display = 'none';
    if (!title) {
      alertEl.textContent = 'Project title is required.';
      alertEl.style.display = 'block';
      $('#ds-prop-title').focus();
      return;
    }
    if (isAi && !desc) {
      alertEl.textContent = 'Please enter a project description for AI generation.';
      alertEl.style.display = 'block';
      $('#ds-prop-desc')?.focus();
      return;
    }

    btn.disabled = true;

    if (!isAi) {
      // ── Blank proposal ──────────────────────────────────────────────────
      btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Creating…';
      const res = await API.createProposal({ title, client: client || null });
      btn.disabled = false;
      btn.innerHTML = '<i class="fa fa-file-contract"></i> Create Proposal';
      if (res.status === 201) {
        closeProposalModal();
        toast('Project proposal created with 6 pages.', 'success');
        _propData = [];
        switchDesignView('proposals');
      } else {
        const msg = res.body?.errors?.title?.[0] || res.body?.message || 'Failed to create proposal.';
        alertEl.textContent = msg;
        alertEl.style.display = 'block';
      }
      return;
    }

    // ── AI-generated proposal ─────────────────────────────────────────────
    try {
      // Step 1: create blank proposal to get the group UUID
      btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Creating proposal…';
      const createRes = await API.createProposal({ title, client: client || null });
      if (createRes.status !== 201) {
        const msg = createRes.body?.errors?.title?.[0] || createRes.body?.message || 'Failed to create proposal.';
        alertEl.textContent = msg;
        alertEl.style.display = 'block';
        btn.disabled = false;
        btn.innerHTML = '<i class="fa fa-wand-magic-sparkles"></i> Generate with AI';
        return;
      }
      const group = createRes.body.data.group;

      // Step 2: AI generates content AND fills all 6 pages on the server in one call
      btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Generating AI content…';
      const fillRes = await API.aiProposalFill(group, { title, client: client || null, description: desc });
      if (fillRes.status !== 200) {
        const msg = fillRes.body?.message || 'AI generation failed. A blank proposal was still created.';
        alertEl.textContent = msg;
        alertEl.style.display = 'block';
        btn.disabled = false;
        btn.innerHTML = '<i class="fa fa-wand-magic-sparkles"></i> Generate with AI';
        _propData = [];
        switchDesignView('proposals');
        return;
      }

      closeProposalModal();
      toast('AI-generated proposal created — all 6 pages filled.', 'success');
      _propData = [];
      switchDesignView('proposals');
    } catch (err) {
      alertEl.textContent = 'An error occurred: ' + (err.message || 'please try again.');
      alertEl.style.display = 'block';
    } finally {
      btn.disabled = false;
      btn.innerHTML = '<i class="fa fa-wand-magic-sparkles"></i> Generate with AI';
    }
  });
}());

